INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('algo-x2', 'algo', 'نبرد مرتب‌سازی‌ها — چرا QuickSort پادشاه است؟', 60, 7, '[{"k":"p","t":"مرتب‌سازی ساده‌ترین مسئله‌ای است که ده‌ها جواب جدی دارد — و هر جواب، فلسفه‌ای. InsertionSort مثل مرتب‌کردن دستِ کارت‌های پاسور است؛ MergeSort تقسیم و حلِ تضمینی؛ QuickSort قمار هوشمندانه‌ای که معمولاً می‌برد. تئوری را با چشم ببین:"},{"k":"visual","visual":"sortRace","title":"شبیه‌ساز: مقایسه زنده الگوریتم‌ها"},{"k":"table","head":["الگوریتم","بهترین","میانگین","بدترین","حافظه","پایدار"],"rows":[["Insertion","O(n)","O(n²)","O(n²)","O(1)","بله"],["Merge","O(n log n)","O(n log n)","O(n log n)","O(n)","بله"],["Quick","O(n log n)","O(n log n)","O(n²)","O(log n)","خیر"],["Heap","O(n log n)","O(n log n)","O(n log n)","O(1)","خیر"],["Counting/Radix","O(n+k)","O(n+k)","O(n+k)","O(k)","بله"]]},{"k":"def","term":"پایداری (Stability)","t":"مرتب‌سازی پایدار، ترتیب عناصر هم‌ارزش را حفظ می‌کند. وقتی رکوردها چند فیلد دارند حیاتی است: اول بر اساس نام مرتب کن، بعد با الگوریتم پایدار بر اساس سن — نتیجه: مرتب بر اساس سن و در تساوی‌ها، بر اساس نام."},{"k":"h","t":"چرا QuickSort با وجود بدترین حالت O(n²) برنده است؟"},{"k":"list","items":["ثابتِ پنهان کوچک: عملیات درجا و Cache-Friendly است","Pivot تصادفی، بدترین حالت را عملاً غیرممکن می‌کند","در زیرمسئله‌های کوچک، InsertionSort جایگزینش می‌شود (Hybrid)","MergeSort حافظه O(n) می‌خواهد؛ Quick فقط O(log n)"]},{"k":"code","lang":"py","title":"quicksort.py","code":"def quicksort(a: list[int]) -> list[int]:\n    if len(a) <= 1:\n        return a\n    pivot = a[len(a) // 2]                 # انتخاب میانه\n    left  = [x for x in a if x < pivot]\n    mid   = [x for x in a if x == pivot]\n    right = [x for x in a if x > pivot]\n    return quicksort(left) + mid + quicksort(right)\n\nprint(quicksort([42, 15, 67, 8, 91, 23]))  # [8, 15, 23, 42, 67, 91]"},{"k":"tip","title":"نکته منتور","t":"در عمل هیچ‌وقت خودت مرتب‌سازی ننویس — sorted() پایتون از Timsort استفاده می‌کند: ترکیبی از Merge و Insertion که برای داده‌های واقعی (بخش‌های از قبل مرتب) بهینه شده. دانستن الگوریتم برای انتخاب و مصاحبه است، نه بازنویسی."}]'::jsonb, '[{"q":"کدام الگوریتم بدترین‌حالتِ تضمین‌شده O(n log n) دارد و پایدار است؟","opts":["QuickSort","MergeSort","InsertionSort","HeapSort"],"ans":1,"why":"MergeSort همیشه n log n است (چون تقسیم‌بندی از داده مستقل است) و چون ادغامش ترتیب برابر را حفظ می‌کند، پایدار است."},{"q":"چرا InsertionSort برای آرایه تقریباً مرتب عالی است؟","opts":["چون بازگشتی است","چون هر عنصر فقط چند خانه جابه‌جا می‌شود — O(n)","چون حافظه نمی‌خواهد","چون پایدار است"],"ans":1,"why":"در داده تقریباً مرتب، حلقه داخلی تقریباً اجرا نمی‌شود؛ به همین دلیل Timsort زیرمسئله‌های کوچک را با آن تمام می‌کند."}]'::jsonb),
('algo-x3', 'algo', 'بازگشت، درخت فراخوانی و هنر Memoization', 55, 8, '[{"k":"p","t":"بازگشت یعنی حل مسئله با نسخه کوچک‌ترِ خودش. مغز انسان در درکش ضعف دارد چون «ردیابی پشته» را دوست ندارد — راه‌حل این است که به‌جای دنبال‌کردن اجرا، به درخت فراخوانی نگاه کنی. درخت زیر، هزینه فیبوناچی ساده را بی‌رحمانه نشان می‌دهد:"},{"k":"visual","visual":"recursionTree","title":"شبیه‌ساز: درخت فراخوانی فیبوناچی"},{"k":"p","t":"ریشه مشکل: زیرمسئله‌های تکراری. fib(5) دو بار fib(3) را کامل حل می‌کند، و fib(3) خودش fib(2) را… با n=۴۰ می‌شود حدود ۳۰۰ میلیون فراخوانی! اما چون زیرمسئله‌ها تکراری‌اند، کافی است جواب هر کدام را یک‌بار حساب و ذخیره کنیم — این یعنی Memoization، قلب برنامه‌ریزی پویا."},{"k":"code","lang":"py","title":"memoization.py","code":"from functools import lru_cache\n\n# ۱) ساده: نمایی — O(2^n)\ndef fib_slow(n: int) -> int:\n    if n <= 1:\n        return n\n    return fib_slow(n - 1) + fib_slow(n - 2)\n\n# ۲) با Memoization: خطی — O(n)\n@lru_cache(maxsize=None)\ndef fib(n: int) -> int:\n    if n <= 1:\n        return n\n    return fib(n - 1) + fib(n - 2)\n\nprint(fib(90))  # 2880067194370816120 — در کسری از ثانیه!"},{"k":"def","term":"برنامه‌ریزی پویا (DP)","t":"DP = بازگشت + حافظه. دو شکل دارد: بالا به پایین (Memoization — بازگشت با کش) و پایین به بالا (Tabulation — پر کردن جدول از زیرمسئله‌های پایه). هر دو یک زیرمسئله را فقط یک‌بار حل می‌کنند."},{"k":"list","items":["شناسایی زیرمسئله: حالت را چه چیزی تعریف می‌کند؟ (مثلاً n)","رابطه بازگشتی: جواب حالت از کدام حالت‌های کوچک‌تر می‌آید؟","شرایط پایه: کوچک‌ترین حالت‌ها چیست؟","ترتیب محاسبه یا کش — و تمام!"]},{"k":"code","lang":"py","title":"tabulation.py","code":"# پایین به بالا: بدون بازگشت، بدون خطر StackOverflow\ndef fib_tab(n: int) -> int:\n    dp = [0, 1]\n    for i in range(2, n + 1):\n        dp.append(dp[i - 1] + dp[i - 2])\n    return dp[n]\n\n# بهینه‌تر: فقط دو مقدار قبلی لازم است — O(1) حافظه\na, b = 0, 1\nfor _ in range(90):\n    a, b = b, a + b\nprint(a)"},{"k":"warn","title":"StackOverflow واقعی","t":"هر فراخوانی بازگشتی یک فریم روی Stack می‌گذارد؛ پایتون پیش‌فرض حدود ۱۰۰۰ فریم اجازه می‌دهد. برای n بزرگ، Tabulation بنویس یا sys.setrecursionlimit را با آگاهی بالا ببر — بهتر: اصلاً بازگشت عمیق طراحی نکن."},{"k":"tip","title":"نکته منتور","t":"قانون طلایی DP: اگر راه‌حل بازگشتی‌ات زیرمسئله تکراری دارد، Memoization بزن و ببین چند فراخوانی واقعاً اجرا می‌شود — اگر چندجمله‌ای شد، DP جواب است. این تشخیص، کلید ده‌ها سوال سخت مصاحبه است."}]'::jsonb, '[{"q":"چرا fib ساده نمایی است؟","opts":["چون اعداد بزرگ می‌شوند","چون هر فراخوانی دو زیرمسئله می‌سازد و زیرمسئله‌ها تکرار می‌شوند","چون پایتون کند است","چون بازگشتی است"],"ans":1,"why":"درخت فراخوانی تقریباً دوبرابر می‌شود در هر سطح؛ و چون کشی نیست، کل زیردرخت‌ها دوباره و دوباره حساب می‌شوند."},{"q":"تفاوت Memoization و Tabulation چیست؟","opts":["یکی سریع‌تر است","اولی بازگشت با کش است (بالا به پایین)، دومی پر کردن جدول از پایه (پایین به بالا)","فرقی ندارند","دومی فقط برای رشته‌هاست"],"ans":1,"why":"نتیجه یکی است: هر زیرمسئله یک‌بار. Tabulation خطر Stack ندارد و Memoization فقط حالت‌های لازم را حساب می‌کند — بسته به مسئله انتخاب کن."}]'::jsonb),
('algo-b1', 'algo', 'تحلیل پیچیدگی و نماد Big-O', 63, 9, '[{"k":"p","t":"Big-O رفتار رشد زمان یا حافظه را با بزرگ‌شدن ورودی توصیف می‌کند و ثابت‌ها را نادیده می‌گیرد چون در مقیاس بزرگ بی‌اهمیت‌اند."},{"k":"h","t":"Big-O دقیقاً چه می‌گوید؛ و چه نمی‌گوید"},{"k":"p","t":"O بزرگ یک «سقف رشد» است: f(n) = O(g(n)) یعنی از جایی به بعد، f از ضرب‌در‌ثابتی از g بزرگ‌تر نمی‌شود. پس وقتی می‌گویی الگوریتم O(n²) است، داری قول می‌دهی «بدتر از این نمی‌شود» — نه «دقیقاً همین است» (آن را Θ می‌گوید) و نه «حداقل این» (آن Ω است). دو سوءتفاهم رایج: اول، O(n log n) یعنی «n ضرب‌در log n بار عملیات» — نه، یعنی رشدش هم‌جنس آن است؛ ثابت‌ها و جملات کوچک‌تر حذف شده‌اند. دوم، O به ورودی‌های «بدترین حالت» اشاره دارد مگر خلافش گفته شود؛ یک hash map که O(1) میانگین دارد، در بدترین حالتِ تئوری O(n) است."},{"k":"h","t":"هنر دیدن log؛ هر جا نصف شد، log آمد"},{"k":"p","t":"سریع‌ترین راه تحلیل، شمردن «حلقه‌ها» نیست — پرسیدن این است: در هر گام، اندازه مسئله چطور عوض می‌شود؟ اگر ثابت کم می‌شود (n-1)، جمع گام‌ها خطی است. اگر نصف می‌شود (n/2)، تعداد گام‌ها تا رسیدن به ۱ برابر log₂n است — جست‌وجوی دودویی، توان‌رسانی دوتایی، و سطح‌های مرج‌سورت همه از این جنس‌اند. اگر در هر گام، روی کل ورودیِ باقی‌مانده کار می‌شود و بعد نصف می‌شود (مثل یک سطح مرج‌سورت)، سطح‌ها n + n/۲ + ... = 2n یعنی O(n log n). این سه الگو — خطی، لگاریتمی، n‌لگاریتمی — حدود ۹۰٪ تحلیل‌های واقعی را می‌سازند؛ بقیه ترکیب و تفریق همین‌هاست."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"تحلیل یک حلقه فریبنده","code":"i = 1\ncount = 0\nwhile i < n:        # i هر بار دو برابر می‌شود\n    j = 0\n    while j < i:    # کار داخلی: به‌اندازه i\n        count += 1\n        j += 1\n    i *= 2\n\n# تحلیل: i می‌گیرد 1، 2، 4، 8، ... ، n\n# کار کل: 1 + 2 + 4 + ... + n = 2n - 1\n# پس O(n) — نه O(n log n)!\n# اشتباه رایج: دیدن دو حلقه و گفتن n×log(n)"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["رشد","نام","نمونه واقعی"],"rows":[["O(1)","ثابت","خواندن ایندکس آرایه"],["O(log n)","لگاریتمی","جست‌وجوی دودویی در ۴ میلیارد: ۳۲ گام"],["O(n)","خطی","یک پاس روی داده"],["O(n log n)","خطی‌لگاریتمی","مرج‌سورت، heap"],["O(n²)","توانی","دو حلقه تو در توی کامل"],["O(2ⁿ)","نمایی","زیرمجموعه‌ها؛ fib بی‌ممو"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["حلقه روی n برابر O(n)؛ حلقه تو در تو O(n²)","جست‌وجوی دودویی O(log n) — نصف‌کردن در هر گام","جمع پیچیدگی‌ها با جمع ورودی‌ها و ضرب با ضرب"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"big_o.py","code":"def f(n):\n    s = 0\n    for i in range(n):        # O(n)\n        s += i\n    for i in range(n):        # O(n)\n        for j in range(n):    # → O(n²)\n            s += 1\n    return s                  # مجموع: O(n²) غالب است"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: حلقه روی n برابر O(n)؛ حلقه تو در تو O(n²) بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا Big-O ثابت‌ها را حذف می‌کند؟","opts":["چون اشتباه است","چون در مقیاس بزرگ، نرخ رشد مهم است نه ضریب","برای راحتی","چون ثابت نیستند"],"ans":1,"why":"۲n و ۱۰۰n هر دو خطی‌اند؛ با n بزرگ هر دو به یک نسبت رشد می‌کنند و تفاوت ضریب ناچیز می‌شود."},{"q":"چرا O(n + 1000) می‌شود O(n)؟","opts":["چون ۱۰۰۰ عدد نیست","چون O فقط نرخ رشد را در n بزرگ می‌سنجد؛ ثابت‌ها جلوی رشد n گم می‌شوند","اشتباه است؛ همان n+1000","برای زیبایی"],"ans":1,"why":"وقتی n میلیارد شود، +۱۰۰۰ یعنی ۰.۰۰۰۱٪ — بی‌اهمیت. O درباره «شکل رشد» است نه مقدار دقیق."},{"q":"حلقه‌ای که در هر گام مسئله را نصف می‌کند چند گام دارد؟","opts":["n","log₂(n) — چون تعداد دفعات نصف‌کردن تا رسیدن به ۱، لگاریتم است","n/2","√n"],"ans":1,"why":"n → n/2 → n/4 → ... → 1 یعنی چند بار ۲ ضرب کنیم تا n شود — و جواب معکوسِ توان، لگاریتم است."}]'::jsonb),
('algo-b2', 'algo', 'بازگشت و اصول آن', 63, 10, '[{"k":"p","t":"بازگشت یعنی تابع خودش را صدا بزند؛ هر بازگشت باید حالت پایه داشته باشد وگرنه بی‌نهایت ادامه می‌یابد و stack سرریز می‌کند."},{"k":"h","t":"جهش ایمان؛ چطور بازگشتی فکر کنیم"},{"k":"p","t":"بزرگ‌ترین مانع درک بازگشت این است که می‌خواهی همه فراخوانی‌ها را همزمان در سرت اجرا کنی — و مغز برای این کار ساخته نشده. راه درست «جهش ایمان» (Leap of Faith) است: فرض کن تابع برای ورودی‌های کوچک‌تر درست کار می‌کند (چون کوچک‌تر است، باورپذیرتر است!) و فقط بپرس: «اگر جواب n-1 را داشته باشم، جواب n را چطور از آن می‌سازم؟» برای fact: اگر fact(n-1) درست است، fact(n) = n × fact(n-1). دیگر لازم نیست درخت فراخوانی را کامل ببینی — فقط حالت پایه (توقف) و گام کوچک‌شدن. با این دو، درست بودن با استقرا ثابت می‌شود؛ دقیقاً همان‌طور که کامپایلر/مفسر اجرا می‌کند، ولی بدون اینکه مغزت stack را شبیه‌سازی کند."},{"k":"h","t":"بهای پنهان بازگشت؛ و سه راه پرداختش"},{"k":"p","t":"هر فراخوانی بازگشتی واقعی هزینه دارد: یک frame پشته (متغیرها + آدرس برگشت) و سربار صدا. fib ساده را حساب کن: fib(50) حدود ۲۵ میلیارد فراخوانی می‌سازد چون زیردرخت‌های fib(48) و fib(47) دوباره کامل حساب می‌شوند — درخت فراخوانی «پهن» شده نه «عمیق». سه درمان: مموایزیشن (کش جواب‌ها — درخت نمایی به خطی تبدیل می‌شود)، تبدیل به حلقه (tabulation — بدون فریم پشته)، و برای زبان‌هایی که پشتیبانی می‌کنند، بازگشت دمی (فراخوانی آخرِ تابع که فریم قبلی قابل‌بازیابی است — پایتون متأسفانه بهینه‌اش نمی‌کند). قاعده عملی: بازگشت را برای خوانایی بنویس، و اگر پروفایلر گفت گلوگاه است، نسخه حلقه‌ای جایگزین کن — نه زودتر."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"fib؛ از نمایی تا خطی","code":"from functools import lru_cache\n\ncalls = {''n'': 0}\n\ndef fib_naive(n):            # O(2ⁿ) — فاجعه\n    calls[''n''] += 1\n    return n if n < 2 else fib_naive(n-1) + fib_naive(n-2)\n\n@lru_cache(maxsize=None)     # یک دکوراتور: O(n)\ndef fib_memo(n):\n    return n if n < 2 else fib_memo(n-1) + fib_memo(n-2)\n\nprint(fib_memo(90))          # لحظه‌ای؛ 2880067194370816120\nfib_naive(25)                # 465 هزار فراخوانی برای n=25!"},{"k":"def","term":"جهش ایمان (Leap of Faith)","t":"روش فکرکردن بازگشتی: به‌جای ردیابی همه فراخوانی‌ها، فرض کن نسخه کوچک‌تر درست است و فقط «گام ترکیب» را بنویس. اگر حالت پایه درست باشد و هر فراخوانی مسئله را کوچک کند، استقرا بقیه را تضمین می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["حالت پایه شرط توقف است","هر فراخوان باید مسئله را کوچک‌تر کند","بازگشت با memoization از محاسبه تکراری جلوگیری می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"recursion.py","code":"def fact(n):\n    if n <= 1: return 1        # حالت پایه\n    return n * fact(n - 1)     # کوچک‌تر شدن\n\ndef fib(n, memo={}):\n    if n < 2: return n\n    if n in memo: return memo[n]\n    memo[n] = fib(n-1, memo) + fib(n-2, memo)\n    return memo[n]"},{"k":"warn","title":"هشدار","t":"fib بدون memo برابر O(2ⁿ) است و برای n=۵۰ عملاً هرگز تمام نمی‌شود — یک خط کش، میلیون‌ها فراخوان را حذف می‌کند."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: حالت پایه شرط توقف است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"نقش حالت پایه در بازگشت چیست؟","opts":["سرعت می‌دهد","شرط توقف است؛ بدون آن بازگشت بی‌نهایت می‌شود","حافظه را آزاد می‌کند","ورودی را کم می‌کند"],"ans":1,"why":"بدون حالت پایه هر فراخوان، فراخوان بعدی را می‌سازد تا stack سرریز شود."},{"q":"چرا fib ساده نمایی است ولی با lru_cache خطی می‌شود؟","opts":["کش سریع‌تر از RAM است","چون بدون کش زیرمسئله‌های یکسان بارها حساب می‌شوند (درخت پهن)؛ با کش هر fib(k) یک‌بار حساب و بعدی‌ها O(1) می‌شوند — جمعاً n محاسبه","شانسی","پایتون بهینه می‌کند"],"ans":1,"why":"fib(48) در دو زیردرخت مستقل دوباره کامل حساب می‌شد؛ مموایزیشن همپوشانی را حذف می‌کند — همان تعریف برنامه‌ریزی پویا."},{"q":"RecursionError یعنی چه و درمانش چیست؟","opts":["باگ مفسر","عمق فراخوانی از سقف فریم‌های پشته رد شده — حالت پایه دور/نیست؛ درمان: اصلاح بازگشت یا تبدیل به حلقه","ورودی اشتباه","حافظه heap پر است"],"ans":1,"why":"هر فراخوانی یک فریم مصرف می‌کند؛ بازگشت بدون پایانِ نزدیک، فریم‌ها را انباشته می‌کند. تبدیل به حلقه، پشته را کلاً حذف می‌کند."}]'::jsonb),
('algo-b3', 'algo', 'تقسیم و حل', 63, 11, '[{"k":"p","t":"تقسیم و حل مسئله را به زیرمسئله‌های مستقل می‌شکند، هرکدام را حل و نتایج را ترکیب می‌کند — مرج‌سورت نمونه کلاسیک آن است."},{"k":"h","t":"کالبدشکافی تقسیم‌وحل؛ و قضیه اصلی به زبان ساده"},{"k":"p","t":"هر الگوریتم تقسیم‌وحل سه مرحله دارد: تقسیم مسئله به a زیرمسئله با اندازه n/b، حل بازگشتی هرکدام، و ترکیب نتایج با هزینه f(n). قضیه اصلی می‌گوید سرنوشت کل الگوریتم را مقایسه «کار ترکیب» با «رشد زیرمسئله‌ها» تعیین می‌کند: اگر ترکیب ناچیز باشد (جست‌وجوی دودویی: O(1)) جواب O(log n)؛ اگر هم‌اندازه کار زیرمسئله‌ها باشد (مرج‌سورت: O(n)) جواب O(n log n)؛ و اگر ترکیب غالب باشد (ضرب ماتریس ساده: O(n²)) جواب همان است. لازم نیست فرمول‌ها را حفظ کنی — بپرس «در هر سطح از درخت، چه‌قدر کار انجام می‌شود و چند سطح هست؟»؛ حاصل‌ضرب این دو، جواب است."},{"k":"h","t":"تقسیم‌وحل‌هایی که در نگاه اول دیده نمی‌شوند"},{"k":"p","t":"قدرت واقعی این پارادایم جایی است که مسئله اصلاً شبیه «مرتب‌سازی» نیست. توان‌رسانی: xⁿ را به‌جای n ضرب، با (x^(n/2))² در log n ضرب حساب کن. بیشینه زیرآرایه: جواب یا در نیمه چپ است، یا راست، یا از وسط رد می‌شود — حالت سوم را خطی پیدا کن و بهترینِ سه را بگیر. نزدیک‌ترین جفت‌نقطه: با مرتب‌کردن و بررسی فقط همسایه‌های خط جداکننده، از O(n²) به O(n log n). و ضرب ماتریس اشتراستن که با ۷ ضرب به‌جای ۸، توان را از ۳ به ۲.۸۱ می‌رساند — مثال اینکه «یک ایده تقسیم بهتر» می‌تواند یک مسئله را متحول کند. هر وقت دیدی جوابِ کل از ترکیب جوابِ دو نیمه می‌آید، بوی تقسیم‌وحل می‌آید."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"توان‌رسانی دوتایی؛ n ضرب در log n ضرب","code":"def power(x, n):\n    if n == 0: return 1              # حالت پایه\n    half = power(x, n // 2)          # جهش ایمان\n    result = half * half             # ترکیب: (x^(n/2))²\n    if n % 2: result *= x            # n فرد: یک x اضافه\n    return result\n\nprint(power(2, 100))\n# برای n=100: حدود ۷ ضرب به‌جای ۱۰۰ ضرب!\n# چون 100 = 1100100₂ و هر بیت ≈ یک ضرب"},{"k":"def","term":"قضیه اصلی (Master Theorem)","t":"فرمولی که پیچیدگی T(n) = a·T(n/b) + f(n) را از مقایسه f(n) با n^(log_b a) می‌خواند: کدام بزرگ‌تر باشد همان (با log اضافی در حالت تساوی) غالب می‌شود — میان‌بُری که تحلیل ده‌ها الگوریتم را یک‌خطی می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["سه مرحله: تقسیم، حل بازگشتی، ترکیب","قضیه اصلی هزینه را از تعداد و اندازه زیرمسئله‌ها می‌دهد","وقتی زیرمسئله‌ها همپوشان‌اند، برنامه‌ریزی پویا بهتر است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"divide.py","code":"def merge_sort(a):\n    if len(a) <= 1: return a\n    mid = len(a) // 2\n    left = merge_sort(a[:mid])\n    right = merge_sort(a[mid:])\n    return merge(left, right)"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: سه مرحله: تقسیم، حل بازگشتی، ترکیب بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت تقسیم‌وحل و برنامه‌ریزی پویا چیست؟","opts":["هیچ","در DP زیرمسئله‌ها همپوشان‌اند و نتایج ذخیره می‌شود","تقسیم‌وحل کندتر است","DP بازگشت ندارد"],"ans":1,"why":"تقسیم‌وحل زیرمسئله‌های مستقل را حل می‌کند؛ DP زیرمسئله‌های تکراری را یک‌بار حل و ذخیره می‌کند."},{"q":"چرا مرج‌سورت O(n log n) است؟","opts":["چون بازگشتی است","چون log n سطح تقسیم داریم و در هر سطح، مجموعاً O(n) کار ادغام انجام می‌شود — ضرب این دو","شانسی","چون پایداری دارد"],"ans":1,"why":"درخت تقسیم log n عمق دارد؛ هر سطح هم n عنصر را بین زیرمسئله‌هایش ادغام می‌کند. عمق × کار هر سطح = n log n."},{"q":"کجا برنامه‌ریزی پویا بر تقسیم‌وحل برتری دارد؟","opts":["وقتی ورودی بزرگ است","وقتی زیرمسئله‌ها همپوشان‌اند — DP نتیجه‌شان را ذخیره می‌کند ولی تقسیم‌وحل دوباره کامل حلشان می‌کند","وقتی آرایه است","هیچ‌وقت"],"ans":1,"why":"تقسیم‌وحل فرض می‌کند زیرمسئله‌ها مستقل‌اند؛ fib و LCS این‌طور نیستند. ذخیره جواب مشترک، دقیقاً همان حلقه‌ای است که DP را نجات می‌دهد."}]'::jsonb),
('algo-b4', 'algo', 'مرج‌سورت و کوییک‌سورت', 63, 12, '[{"k":"p","t":"هر دو مرتب‌سازی مقایسه‌ای O(n log n)‌اند؛ مرج همیشه این تضمین را دارد ولی حافظه می‌خواهد، کوییک در عمل سریع‌تر است ولی بدترین حالت O(n²)."},{"k":"h","t":"چرا هر دو به n log n می‌رسند؛ و چرا در عمل فرق دارند"},{"k":"p","t":"هر دو الگوریتم یک اسکلت دارند: log n سطح تقسیم، و در هر سطح کار خطی (مرج‌سورت در ادغام، کوییک‌سورت در افراز). تفاوت در جزئیات مهندسی است: مرج‌سورت در ادغام، ترتیب برابرها را حفظ می‌کند (پایدار) و رفتارش برای هر ورودی‌ای تضمین‌شده است — ولی آرایه کمکی O(n) می‌خواهد. کوییک‌سورت درجا کار می‌کند و چون افرازش محلی است، با کش CPU دوست‌تر است و در عمل معمولاً ۲ تا ۳ برابر سریع‌تر — ولی کیفیتش به انتخاب pivot وابسته است: pivot همیشه کوچک‌ترین یعنی افراز ۱ به n-1 و سقوط به O(n²). کتابخانه‌های واقعی (مثل sort پایتون و C++) این مصالحه را جدی گرفته‌اند: Timsort و Introsort."},{"k":"h","t":"از pivot بد تا Introsort؛ مهندسی کوییک‌سورت واقعی"},{"k":"p","t":"سه سپر دفاعی کوییک‌سورت مدرن: اول، انتخاب pivot هوشمند — median-of-three (میانه اول، وسط، آخر) یا تصادفی، که ورودی‌های مرتب/معکوس را خنثی می‌کند. دوم، برای آرایه‌های کوچک (مثلاً زیر ۱۶)، به insertion sort بسپار — بازگشت برای این اندازه‌ها سربار بیشتری دارد تا حلقه ساده. سوم و مهم‌تر، Introsort: عمق بازگشت را بشمار؛ اگر از ۲log n رد شد (نشانه pivotهای بد پشت‌سرهم)، وسط کار به heapsort بپر — تضمین O(n log n) بدون از‌دست‌دادن سرعت معمولی. این یعنی «خوش‌بین باش، ولی چاره‌اندیش»: همان فلسفه‌ای که sort واقعی هر زبانی را می‌سازد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"شمارش وارونگی‌ها با مرج‌سورت","code":"def inversions(a):\n    if len(a) <= 1:\n        return a, 0\n    mid = len(a) // 2\n    left, x = inversions(a[:mid])\n    right, y = inversions(a[mid:])\n    merged, z = [], 0\n    i = j = 0\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            merged.append(left[i]); i += 1\n        else:\n            merged.append(right[j]); j += 1\n            z += len(left) - i   # همه باقی‌مانده‌های چپ، وارونگی‌اند\n    merged += left[i:] + right[j:]\n    return merged, x + y + z\n\nprint(inversions([3, 1, 2])[1])   # 2 وارونگی"},{"k":"def","term":"وارونگی (Inversion)","t":"جفت (i, j) که i < j ولی a[i] > a[j] — یعنی یک جفتِ جابه‌جاشده نسبت به ترتیب. تعداد وارونگی‌ها دقیقاً معیار «نامرتبی» است و شمارشش با مرج‌سورتِ اصلاح‌شده در O(n log n) انجام می‌شود؛ الگویی که شباهت دو رتبه‌بندی و فاصله کندال را می‌سازد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["مرج: تقسیم به دو نیمه و ادغام مرتب — پایدار","کوییک: انتخاب pivot و افراز — درجا ولی ناپایدار","انتخاب pivot تصادفی، بدترین حالت کوییک را کم می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"quick.py","code":"def quick(a):\n    if len(a) <= 1: return a\n    p = a[len(a)//2]\n    return (quick([x for x in a if x < p])\n            + [x for x in a if x == p]\n            + quick([x for x in a if x > p]))"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: مرج: تقسیم به دو نیمه و ادغام مرتب — پایدار بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا مرج‌سورت پایدار است ولی کوییک‌سورت نه؟","opts":["تصادفی است","مرج ترتیب برابرها را در ادغام حفظ می‌کند؛ افراز کوییک جابه‌جایشان می‌کند","کوییک کندتر است","مرج حافظه ندارد"],"ans":1,"why":"پایداری یعنی عناصر برابر جای نسبی‌شان حفظ شود؛ ادغام مرج این را تضمین می‌کند."},{"q":"کوییک‌سورت با pivot همیشه کوچک‌ترین عنصر چه می‌شود؟","opts":["همان O(n log n)","افراز هر بار ۱ به n-1 می‌شود؛ n سطح با کار n در هر سطح — یعنی O(n²)","بهتر می‌شود","حلقه بی‌نهایت"],"ans":1,"why":"تقسیم نامتوازن، درخت را از log n سطح به n سطح می‌کشاند. راه‌حل واقعی‌ها: pivot تصادفی یا median-of-three، و Introsort به‌عنوان تور ایمنی."},{"q":"کجا مرج‌سورت بر کوییک‌سورت واجب است؟","opts":["هر جا","جایی که پایداری لازم است (مثل مرتب‌سازی دوم روی کلید دوم) — مرج ترتیب برابرها را حفظ می‌کند","برای اعداد","برای رشته‌ها"],"ans":1,"why":"اگر داده قبلاً با کلید دیگری مرتب شده و حالا روی کلید جدید مرتب می‌شود، فقط مرتب‌سازی پایدار ترتیب قبلیِ برابرها را نگه می‌دارد — مرج و Timsort این‌طورند، کوییک نه."}]'::jsonb),
('algo-b5', 'algo', 'جست‌وجوی دودویی و گونه‌های آن', 63, 13, '[{"k":"p","t":"جست‌وجوی دودویی روی داده مرتب در هر گام نصف فضا را حذف می‌کند — O(log n). گونه‌هایش «اولین/آخرین عنصرِ دارای شرط» را پیدا می‌کنند."},{"k":"h","t":"نصف‌کردن؛ راز log n"},{"k":"p","t":"جست‌وجوی دودویی هر گام نصف فضای باقی‌مانده را حذف می‌کند: با یک مقایسه می‌فهمی جواب در نیمه چپ است یا راست، و نیمه دیگر را کلاً رها می‌کنی. پس فضای n بعد از k گام می‌شود n/2^k؛ وقتی به ۱ برسد یعنی k = log n گام. برای یک میلیارد عنصر، این حدود ۳۰ مقایسه است — در برابر یک میلیارد مقایسه جست‌وجوی خطی. شرطش این است که داده مرتب باشد تا مقایسه واقعاً جهت را بگوید."},{"k":"h","t":"جست‌وجو روی جواب؛ فراتر از آرایه"},{"k":"p","t":"قدرت واقعی دودویی وقتی است که بفهمی لازم نیست روی آرایه بگردی — می‌توانی روی «فضای جواب» بگردی. هر مسئله‌ای که یک تابع یکنوا داشته باشد (مثل «آیا با بودجه x می‌شود همه را خرید؟» که با افزایش x از نه به بله می‌رود)، با دودویی روی x حل می‌شود. الگوی lower_bound (اولین جایی که شرط True می‌شود) همین است و صدها مسئله بهینه‌سازی را به log n می‌رساند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"lower_bound؛ اولین عنصر ≥ x","code":"def lower_bound(a, x):\n    lo, hi = 0, len(a)        # بازه [lo, hi)\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if a[mid] >= x:\n            hi = mid           # جواب اینجاست یا قبل‌تر\n        else:\n            lo = mid + 1       # جواب بعد از mid است\n    return lo                  # اولین ایندکسی که a[i] >= x\n\na = [1, 3, 5, 7, 9]\nprint(lower_bound(a, 6))   # 3 → چون a[3]=7 اولین >= 6 است"},{"k":"tip","title":"نکته منتور","t":"بیشتر باگ‌های دودویی از مرزهاست: یک قرارداد ثابت انتخاب کن (مثل بازه [lo, hi) با شرط lo < hi و hi=mid / lo=mid+1) و در همه‌جا همان را بکار ببر — مخلوط‌کردن قراردادها عامل اصلی حلقه بی‌نهایت و off-by-one است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["شرط لازم: داده مرتب باشد","مرزها را دقیق نگه دار تا حلقه بی‌نهایت نشود","برای «اولین مقدار ≥ x» الگوی lower_bound استفاده کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"bisect.py","code":"def first_ge(a, x):\n    lo, hi = 0, len(a)\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if a[mid] >= x: hi = mid\n        else: lo = mid + 1\n    return lo   # ایندکس اولین ≥ x"},{"k":"tip","title":"نکته منتور","t":"بیشتر باگ‌های جست‌وجوی دودویی از مرزهاست؛ بازه [lo, hi) و شرط lo < hi را ثابت نگه دار و تغییرش نده."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: شرط لازم: داده مرتب باشد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"شرط لازم جست‌وجوی دودویی چیست؟","opts":["داده کوچک باشد","داده مرتب باشد","داده عددی باشد","داده یکتا باشد"],"ans":1,"why":"دودویی با مقایسه نصف فضا را حذف می‌کند و این فقط وقتی معتبر است که ترتیب وجود داشته باشد."},{"q":"چرا جست‌وجوی دودویی روی داده نامرتب کار نمی‌کند؟","opts":["کند می‌شود","چون حذف نصف فضا به این وابسته است که با یک مقایسه جهت معلوم شود — بدون ترتیب، مقایسه هیچ نیمه‌ای را حذف نمی‌کند","حافظه","ممکن نیست"],"ans":1,"why":"منطق دودویی این است: اگر a[mid] < x، پس همه نیمه چپ هم < x‌اند و می‌توان رهایشان کرد. این استنتاج فقط با مرتب‌بودن معتبر است؛ بدون آن نمی‌دانی جواب کجاست و باید همه را ببینی."},{"q":"در lower_bound، چرا هنگام a[mid] >= x می‌نویسیم hi = mid و نه hi = mid - 1؟","opts":["قرارداد","چون mid خودش می‌تواند جواب باشد (اولین >= x)؛ پس نباید حذفش کنیم — فقط می‌گوییم جواب mid یا قبل‌تر است","سرعت","تصادفی"],"ans":1,"why":"ما دنبال اولین جایی هستیم که شرط برقرار است؛ اگر a[mid] >= x باشد، mid کاندیداست و حذفش با mid-1 ممکن است جواب واقعی را از دست بدهد. بازه [lo, hi) و hi=mid این را امن نگه می‌دارد."}]'::jsonb),
('algo-b6', 'algo', 'الگوریتم‌های حریصانه', 63, 14, '[{"k":"p","t":"حریصانه در هر گام بهترین انتخاب محلی را می‌کند و امیدوار است به جواب کلی برسد — وقتی جواب‌های محلی به‌هم نخورند، درست و بسیار سریع است."},{"k":"h","t":"انتخاب محلیِ بهینه"},{"k":"p","t":"الگوریتم حریصانه در هر گام بهترین انتخابِ همان لحظه را می‌کند و امیدوار است به جواب کلی بهینه برسد — بدون اینکه آینده را کامل بررسی کند. این وقتی درست است که مسئله «ساختار حریصانه» داشته باشد: انتخاب محلی بهینه، راهِ بهترِ کلی را نبندد. سرعتش عالی است (معمولاً O(n log n) برای مرتب‌سازی اولیه) ولی صحتش بدیهی نیست و باید اثبات شود — وگرنه جواب زیربهینه می‌دهد."},{"k":"h","t":"کی حریصانه شکست می‌خورد"},{"k":"p","t":"مسئله سکه با سکه‌های استاندارد (۱،۵،۱۰) با حریصانه حل می‌شود، ولی با سکه‌های دلخواه مثل (۱،۳،۴) برای مبلغ ۶ شکست می‌خورد: حریصانه ۴+۱+۱ (سه سکه) می‌دهد در حالی که ۳+۳ (دو سکه) بهتر است. اینجا انتخاب بزرگ‌ترین سکه اول، جلوی ترکیب بهتر را می‌گیرد. پس قبل از استفاده از حریصانه، یا اثبات کن یا با مثال نقض بررسی کن — وگرنه به برنامه‌ریزی پویا نیاز داری."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"زمان‌بندی فعالیت‌ها — حریصانه درست","code":"# بیشترین تعداد جلسه بدون تداخل:\n# حریصانه: همیشه جلسه‌ای که زودتر تمام می‌شود\ndef schedule(intervals):\n    intervals.sort(key=lambda x: x[1])   # مرتب بر اساس پایان\n    chosen, end = [], -1\n    for s, e in intervals:\n        if s >= end:                      # تداخل ندارد\n            chosen.append((s, e))\n            end = e\n    return chosen\n\nprint(schedule([(1,3),(2,4),(3,5),(4,6)]))\n# [(1,3),(3,5)] یا بهتر [(1,3),(4,6)]... → [(1,3),(3,5)] درست است: ۲ جلسه"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["مسئله سکه با سکه‌های استاندارد با حریصانه حل می‌شود","زمان‌بندی فعالیت‌ها: همیشه اولین که تمام می‌شود","حریصانه همیشه درست نیست؛ صحت باید اثبات شود"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"greedy.py","code":"def min_coins(coins, amount):\n    coins.sort(reverse=True)\n    count = 0\n    for c in coins:\n        count += amount // c\n        amount %= c\n    return count if amount == 0 else -1"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: مسئله سکه با سکه‌های استاندارد با حریصانه حل می‌شود بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا حریصانه همیشه جواب بهینه نمی‌دهد؟","opts":["کند است","انتخاب محلیِ بهینه ممکن است راهِ بهترِ کلی را ببندد","حافظه ندارد","ممکن نیست"],"ans":1,"why":"در برخی مسائل (مثل سکه‌های دلخواه) انتخاب بزرگ‌ترین سکه اول، جلوی ترکیب بهتر را می‌گیرد."},{"q":"چرا «زودترین پایان» برای زمان‌بندی فعالیت‌ها حریصانه درست است؟","opts":["تصادفی","چون تمام‌کردن زودتر، بیشترین زمان باقی‌مانده را برای فعالیت‌های بعدی آزاد می‌کند — هیچ انتخاب دیگری فضای بیشتری باز نمی‌کند","سریع‌تر","قرارداد"],"ans":1,"why":"این همان اثبات حریصانه است: اگر جلسه‌ای زودتر تمام شود، هر مجموعه جلسه سازگار با یک جلسه دیرتر، با این هم سازگار است — پس انتخاب زودترین پایان هرگز جواب را بدتر نمی‌کند."},{"q":"چرا حریصانه برای مسئله سکه با denominations دلخواه جواب بهینه نمی‌دهد؟","opts":["کند است","چون انتخاب بزرگ‌ترین سکه می‌تواند ترکیب بهینه‌ای را که با سکه‌های کوچک‌تر ساخته می‌شود ببندد — ساختار حریصانه ندارد","حافظه","ممکن نیست"],"ans":1,"why":"حریصانه برمی‌نگردد و انتخابش را عوض نمی‌کند؛ پس اگر انتخاب اول به بن‌بستِ زیربهینه برسد، همان می‌ماند. مسائلی که نیاز به «بررسی ترکیب‌ها» دارند، باید با برنامه‌ریزی پویا حل شوند."}]'::jsonb),
('algo-b7', 'algo', 'مقدمه برنامه‌ریزی پویا', 63, 15, '[{"k":"p","t":"برنامه‌ریزی پویا برای مسائل با زیرساختار بهینه و زیرمسئله‌های همپوشان است؛ جواب زیرمسئله‌ها را ذخیره می‌کند تا دوباره حساب نشوند."},{"k":"h","t":"دو شرط لازم"},{"k":"p","t":"برنامه‌ریزی پویا برای مسائلی است که دو ویژگی دارند: زیرمسئله‌های همپوشان (جواب یک زیرمسئله چندبار لازم می‌شود، مثل fib که fib(n-2) را از دو راه حساب می‌کند) و زیرساختار بهینه (جواب بهینه از ترکیب جواب‌های بهینه زیرمسئله‌ها ساخته می‌شود). اگر همپوشانی نباشد، کش بی‌فایده است؛ و اگر زیرساختار بهینه نباشد، ترکیب جواب‌های جزئی درست نیست. پس اول این دو را تشخیص بده، بعد DP بزن."},{"k":"h","t":"memoization در برابر tabulation"},{"k":"p","t":"دو راه پیاده‌سازی هست: memoization از بالا — همان بازگشت را می‌نویسی و نتیجه هر فراخوان را در یک dict کش می‌کنی تا دوباره حساب نشود؛ ساده و فقط زیرمسئله‌های لازم را حساب می‌کند. tabulation از پایین — یک جدول می‌سازی و از کوچک‌ترین زیرمسئله به بزرگ‌ترین پرش می‌کنی؛ بدون سربار بازگشت و معمولاً سریع‌تر. هر دو O(یکسان)‌اند؛ برای شروع memoization طبیعی‌تر است و برای بهینه‌سازی tabulation."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"fib؛ از نمایی به خطی","code":"from functools import lru_cache\n\n# ❌ بازگشت ساده: O(2^n) — برای n=40 چند ثانیه!\ndef fib(n):\n    return n if n < 2 else fib(n-1) + fib(n-2)\n\n# ✓ memoization: O(n)\n@lru_cache(maxsize=None)\ndef fib_m(n):\n    return n if n < 2 else fib_m(n-1) + fib_m(n-2)\n\n# ✓ tabulation: O(n) و فقط O(1) حافظه\ndef fib_t(n):\n    a, b = 0, 1\n    for _ in range(n): a, b = b, a + b\n    return a"},{"k":"def","term":"حالت (State)","t":"مجموعه متغیرهایی که یک زیرمسئله را منحصربه‌فرد مشخص می‌کنند — مثل (i, w) در کوله‌پشتی. تعریف درست حالت، مهم‌ترین گام DP است؛ چون هم اندازه جدول و هم رابطه بازگشتی از آن می‌آید. اگر حالت را درست تعریف کنی، بقیه تقریباً خودکار است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["memoization از بالا (بازگشت + کش) است","tabulation از پایین (جدول + حلقه) است","حالت را دقیق تعریف کن؛ همه‌چیز از آن می‌آید"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"dp.py","code":"# تعداد راه‌های بالا رفتن از پله (۱ یا ۲ قدم)\ndef ways(n):\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i-1] + (dp[i-2] if i >= 2 else 0)\n    return dp[n]\nprint(ways(5))   # 8"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: memoization از بالا (بازگشت + کش) است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"دو شرط لازم برای برنامه‌ریزی پویا چیست؟","opts":["مرتب‌بودن و کوچکی","زیرساختار بهینه و زیرمسئله همپوشان","بازگشتی و حلقه‌ای","عدد و رشته"],"ans":1,"why":"اگر زیرمسئله‌ها همپوشان نباشند کش بی‌فایده است و اگر زیرساختار بهینه نباشد، ترکیب جواب‌های جزئی درست نیست."},{"q":"چرا fib بدون memo آن‌قدر کند است؟","opts":["بازگشت کند است","چون زیرمسئله‌ها را نمادین و بازگشتی حساب می‌کند؛ fib(n-2) از دو مسیر مختلف دوباره حساب می‌شود و تعداد فراخوانی‌ها نمایی می‌شود","حافظه","نوع داده"],"ans":1,"why":"درخت فراخوانی fib پر از تکرار است؛ بدون کش، هر زیرمسئله بارها از نو حساب می‌شود که O(2^n) است. با memo هر زیرمسئله فقط یک‌بار حساب و بعد خوانده می‌شود — پس O(n)."},{"q":"چه فرقی بین memoization و tabulation هست و کی کدام؟","opts":["هیچ","memoization از بالا با بازگشت+کش و فقط زیرمسئله‌های لازم؛ tabulation از پایین با جدول و بدون سربار بازگشت — برای شروع اولی ساده‌تر، برای بهینه دومی","سرعت یکی است همیشه","فقط یکی درست است"],"ans":1,"why":"هر دو از دوباره‌کاری جلوگیری می‌کنند ولی جهت‌شان فرق دارد. memoization طبیعی‌تر و lazy است؛ tabulation کنترل بیشتری دارد، حافظه‌اش قابل‌کاهش است و از محدودیت عمق بازگشت هم فرار می‌کند."}]'::jsonb),
('algo-b8', 'algo', 'مسائل کلاسیک DP', 63, 16, '[{"k":"p","t":"کوله‌پشتی، بلندترین زیردنباله مشترک و کمترین ویرایش، سه مسئله مرجع DP‌اند که الگوهایشان در صدها مسئله دیگر تکرار می‌شود."},{"k":"h","t":"کوله‌پشتی؛ الگوی انتخاب با ظرفیت"},{"k":"p","t":"کوله‌پشتی ۰/۱ می‌گوید: n قلم با وزن و ارزش داری و ظرفیت W؛ هر قلم یا برمی‌دار یا نه، و می‌خواهی بیشترین ارزش را ببری. حالت DP می‌شود dp[i][w]: بیشترین ارزش با i قلم اول و ظرفیت w. رابطه: یا قلم i را برنمی‌داری (dp[i-1][w]) یا برمی‌داری (dp[i-1][w-wt] + val) — و بیشینه‌اش را می‌گیری. این الگوی «انتخاب یا عدم انتخاب» در صدها مسئله تکرار می‌شود."},{"k":"h","t":"LCS؛ هم‌ترازی دو دنباله"},{"k":"p","t":"بلندترین زیردنباله مشترک، طول بلندترین دنباله‌ای را می‌خواهد که در هر دو رشته (با حفظ ترتیب، نه لزوماً پشت‌سرهم) ظاهر شود — پایه الگوریتم‌های diff و هم‌ترازی DNA. حالت dp[i][j] یعنی LCS پیشوندهای i و j ام. اگر کاراکترها برابر باشند، ۱ + dp[i-1][j-1]؛ وگرنه بیشینه dp[i-1][j] و dp[i][j-1]. فاصله ویرایش هم همین ساختار را دارد با هزینه برای درج/حذف/جایگزینی."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"LCS با جدول","code":"def lcs(a, b):\n    m, n = len(a), len(b)\n    dp = [[0]*(n+1) for _ in range(m+1)]\n    for i in range(1, m+1):\n        for j in range(1, n+1):\n            if a[i-1] == b[j-1]:\n                dp[i][j] = dp[i-1][j-1] + 1   # کاراکتر مشترک\n            else:\n                dp[i][j] = max(dp[i-1][j], dp[i][j-1])\n    return dp[m][n]\n\nprint(lcs(''ABCBDAB'', ''BDCABA''))   # 4 → مثلاً ''BCBA''"},{"k":"tip","title":"نکته منتور","t":"برای کوله‌پشتی ۰/۱ می‌توانی جدول دوبعدی را به یک بعد تقلیل بدهی — به‌شرطی که حلقه وزن را از بالا به پایین بپیمایی تا از مقدار به‌روز‌نشده همان سطر قبلی استفاده کنی. این کاهش حافظه از O(nW) به O(W) در مصاحبه امتیاز دارد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["کوله‌پشتی: dp[i][w] بهترین سود با i قلم و ظرفیت w","LCS: اگر کاراکترها برابر، ۱+قطری؛ وگرنه بیشینه بالا/چپ","فاصله ویرایش مشابه LCS با هزینه عملیات"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"knapsack.py","code":"def knapsack(wt, val, W):\n    dp = [0] * (W + 1)\n    for i in range(len(wt)):\n        for w in range(W, wt[i] - 1, -1):\n            dp[w] = max(dp[w], dp[w - wt[i]] + val[i])\n    return dp[W]"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: کوله‌پشتی: dp[i][w] بهترین سود با i قلم و ظرفیت w بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"در LCS اگر دو کاراکتر برابر باشند چه می‌شود؟","opts":["صفر می‌شود","۱ به‌علاوه جواب قطری (بدون این دو کاراکتر)","بیشینه بالا و چپ","جواب قبلی"],"ans":1,"why":"برابری یعنی این جفت بخشی از زیردنباله مشترک است؛ پس ۱ به جوابِ بدون هر دو اضافه می‌شود."},{"q":"در LCS اگر دو کاراکتر برابر باشند چرا از dp[i-1][j-1] استفاده می‌کنیم؟","opts":["تصادفی","چون این جفت کاراکتر مشترک به انتهای یک زیردنباله مشترکِ پیشوندهای قبلی اضافه می‌شود — پس ۱ به جوابِ بدون هر دو کاراکتر اضافه می‌کنیم","بزرگ‌تر است","قرارداد"],"ans":1,"why":"وقتی a[i]==b[j]، می‌توانیم این کاراکتر را به LCS پیشوندهای i-1 و j-1 بچسبانیم. dp[i-1][j-1] دقیقاً جواب آن زیرمسئله است؛ پس ۱ + آن، جواب جدید است."},{"q":"چرا در کوله‌پشتی ۰/۱، رابطه بازگشتی «بیشینه برداشتن و برنداشتن» است؟","opts":["قرارداد","چون برای هر قلم دقیقاً دو انتخاب داریم و نمی‌دانیم کدام به جواب بهینه می‌رسد — پس بهترینِ هر دو حالت را نگه می‌داریم و DP بقیه را حل می‌کند","سرعت","حافظه"],"ans":1,"why":"ماهیت مسئله انتخاب دوتایی است؛ چون نمی‌دانیم برداشتن قلم i در نهایت بهتر است یا نه، DP هر دو شاخه را به‌طور بهینه ارزیابی و بیشینه را برمی‌گرداند — بدون اینکه واقعاً هر ترکیب را جدا امتحان کند."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('algo-b9', 'algo', 'پس‌گرد و جست‌وجوی کامل', 63, 17, '[{"k":"p","t":"پس‌گرد همه جواب‌های ممکن را سیستماتیک می‌سازد و به‌محض نقض شرط، شاخه را رها می‌کند — برای جایگشت، زیرمجموعه و سودوکو."},{"k":"h","t":"ساختن سیستماتیک همه جواب‌ها"},{"k":"p","t":"پس‌گرد الگوریتمی برای مسائل «همه جواب‌های ممکن را پیدا کن» یا «آیا جوابی هست» است: جواب را قدم‌به‌قدم می‌سازد و در هر قدم یک انتخاب می‌کند، بازگشتی ادامه می‌دهد، و وقتی برگشت انتخاب را برمی‌گرداند تا شاخه بعدی را امتحان کند. این همان «انتخاب کن، بازگشت کن، برگردان» است. برای جایگشت، زیرمجموعه، و سودوکو ابزار طبیعی است."},{"k":"h","t":"هرس؛ تفاوت با جست‌وجوی کور"},{"k":"p","t":"قدرت پس‌گرد در هرس است: به‌محض اینکه یک شاخه نمی‌تواند به جواب برسد (نقض شرط)، آن را رها می‌کند و بقیه‌اش را نمی‌سازد — برخلاف جست‌وجوی کور که همه را می‌سازد و بعد چک می‌کند. مثلاً در سودوکو، اگر عددی در سطر تکراری شد همان لحظه برمی‌گردی. هرسِ خوب می‌تواند فضای جست‌وجو را از نماییِ کامل به قابل‌حل برساند، ولی در بدترین حالت همچنان نمایی است — پس برای n بزرگ مناسب نیست."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"جایگشت‌ها با پس‌گرد","code":"def permutations(nums):\n    out, path, used = [], [], [False]*len(nums)\n    def go():\n        if len(path) == len(nums):\n            out.append(list(path)); return\n        for i, x in enumerate(nums):\n            if used[i]: continue        # این انتخاب قبلاً شده\n            used[i] = True              # انتخاب کن\n            path.append(x)\n            go()                        # بازگشت\n            path.pop(); used[i] = False # برگردان\n    go()\n    return out\n\nprint(permutations([1,2,3]))  # ۶ جایگشت"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["انتخاب کن، بازگشت کن، برگردان — سه‌گانه پس‌گرد","هرس زودهنگام، شاخه‌های بن‌بست را نمی‌سازد","برای مسائل NP بدون راه بهتر شناخته‌شده"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"backtrack.py","code":"def subsets(nums):\n    out = []\n    def go(i, cur):\n        out.append(list(cur))\n        for j in range(i, len(nums)):\n            cur.append(nums[j])\n            go(j + 1, cur)\n            cur.pop()        # برگرداندن انتخاب\n    go(0, [])\n    return out"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: انتخاب کن، بازگشت کن، برگردان — سه‌گانه پس‌گرد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"نقش cur.pop() در پس‌گرد چیست؟","opts":["حافظه را خالی می‌کند","انتخاب را برمی‌گرداند تا شاخه بعدی با حالت تمیز ادامه دهد","جواب را چاپ می‌کند","حلقه را می‌شکند"],"ans":1,"why":"پس از بازگشت از یک شاخه، باید اثر انتخاب حذف شود تا شاخه بعدی از همان حالت شروع شود."},{"q":"نقش path.pop() و used[i]=False بعد از فراخوانی بازگشتی چیست؟","opts":["حافظه را خالی می‌کند","انتخاب را برمی‌گرداند تا وقتی از یک شاخه برگشتیم، حالت تمیز باشد و شاخه بعدی از همان نقطه شروع شود — ذات پس‌گرد","جواب را چاپ می‌کند","اختیاری است"],"ans":1,"why":"پس‌گرد یعنی امتحان‌کردن همه انتخاب‌ها با حالت مشترک؛ اگر بعد از هر شاخه انتخاب را برنگردانی، شاخه‌های بعدی با حالت آلوده شروع می‌شوند و جواب‌ها غلط یا ناقص می‌شوند."},{"q":"چرا پس‌گرد برای n بزرگ مناسب نیست؟","opts":["کند می‌شود کمی","چون در بدترین حالت فضای جست‌وجو نمایی است (مثل n! برای جایگشت) و هرس فقط شاخه‌های بن‌بست را حذف می‌کند، نه همه — پس مقیاس‌پذیر نیست","حافظه","ممکن نیست"],"ans":1,"why":"پس‌گرد همه جواب‌ها را می‌سازد؛ اگر تعدادشان نمایی باشد، حتی با هرس هم از پسش برنمی‌آیی. برای n بزرگ باید به فکر الگوریتم چندجمله‌ای یا تقریبی باشی، نه جست‌وجوی کامل."}]'::jsonb),
('algo-b10', 'algo', 'کوتاه‌ترین مسیر: دایکسترا', 63, 18, '[{"k":"p","t":"دایکسترا کوتاه‌ترین مسیر از یک مبدأ را در گراف با وزن نامنفی پیدا می‌کند؛ با هیپ، پیچیدگی آن O((V+E) log V) است."},{"k":"h","t":"ایده؛ تثبیت تدریجی نزدیک‌ترین"},{"k":"p","t":"دایکسترا کوتاه‌ترین مسیر از یک مبدأ را در گراف با وزن نامنفی پیدا می‌کند. ایده: در هر گام، نزدیک‌ترین گره‌ای که هنوز فاصله‌اش نهایی نشده را انتخاب و «تثبیت» کن، بعد فاصله همسایه‌هایش را از راه آن به‌روز کن. چون وزن‌ها نامنفی‌اند، وقتی گره‌ای به‌عنوان نزدیک‌ترین انتخاب شد، هیچ مسیر کوتاه‌تری بعداً پیدا نمی‌شود — پس تثبیتش امن است. با هیپ، انتخاب نزدیک‌ترین O(log V) و کل الگوریتم O((V+E) log V) است."},{"k":"h","t":"چرا وزن منفی آن را می‌شکند"},{"k":"p","t":"امنیت تثبیت به نامنفی‌بودن وزن وابسته است: اگر یال منفی باشد، ممکن است بعداً مسیری پیدا شود که از یک گره تثبیت‌شده رد می‌شود و فاصله‌اش را کمتر کند — ولی دایکسترا دیگر برنمی‌گردد و آن را به‌روز نمی‌کند، پس جواب غلط می‌شود. برای وزن منفی باید Bellman-Ford بزنی که چند دور همه یال‌ها را آرام می‌کند و حتی حلقه منفی را تشخیص می‌دهد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"دایکسترا با هیپ","code":"import heapq\n\ndef dijkstra(graph, src):\n    dist = {v: float(''inf'') for v in graph}\n    dist[src] = 0\n    pq = [(0, src)]\n    while pq:\n        d, u = heapq.heappop(pq)\n        if d > dist[u]:           # ورودی کهنه — بپر\n            continue\n        for v, w in graph[u]:\n            nd = d + w\n            if nd < dist[v]:      # مسیر بهتر پیدا شد\n                dist[v] = nd\n                heapq.heappush(pq, (nd, v))\n    return dist"},{"k":"tip","title":"نکته منتور","t":"چک if d > dist[u]: continue حیاتی است؛ چون ممکن است یک گره چندبار با فاصله‌های مختلف وارد هیپ شود و فقط اولین (کوچک‌ترین) معتبر است. بدون این چک، همسایه‌ها را با فاصله کهنه به‌روز می‌کنی و جواب غلط یا کند می‌شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هر گام نزدیک‌ترین گره تثبیت‌نشده را انتخاب می‌کند","با وزن منفی درست نیست — برای آن Bellman-Ford","فاصله‌ها فقط کوچک‌تر می‌شوند تا تثبیت شوند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"dijkstra.py","code":"import heapq\ndef dijkstra(g, src):\n    dist = {v: float(''inf'') for v in g}\n    dist[src] = 0\n    pq = [(0, src)]\n    while pq:\n        d, u = heapq.heappop(pq)\n        if d > dist[u]: continue\n        for v, w in g[u]:\n            if d + w < dist[v]:\n                dist[v] = d + w\n                heapq.heappush(pq, (dist[v], v))\n    return dist"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هر گام نزدیک‌ترین گره تثبیت‌نشده را انتخاب می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا دایکسترا با وزن منفی کار نمی‌کند؟","opts":["کند می‌شود","گره تثبیت‌شده دیگر بازبینی نمی‌شود ولی وزن منفی می‌تواند فاصله‌اش را کم کند","حافظه ندارد","نیاز به صف دارد"],"ans":1,"why":"دایکسترا فرض می‌کند فاصله تثبیت‌شده نهایی است؛ وزن منفی این فرض را می‌شکند."},{"q":"چرا if d > dist[u]: continue را در دایکسترا با هیپ لازم داریم؟","opts":["برای سرعت فقط","چون یک گره ممکن است چندبار با فاصله‌های مختلف وارد هیپ شود؛ فقط کوچک‌ترین معتبر است و بقیه ورودی‌های کهنه‌اند","اختیاری است","برای حافظه"],"ans":1,"why":"وقتی فاصله یک گره بهتر می‌شود، دوباره pushش می‌کنیم ولی ورودی قبلی هنوز در هیپ است. پس هنگام pop ممکن است یک نسخه قدیمی بیرون بیاید؛ این چک آن را دور می‌ریزد تا با داده کهنه کار نکنیم."},{"q":"چرا دایکسترا با وزن منفی جواب غلط می‌دهد؟","opts":["کند می‌شود","چون گره‌ای که به‌عنوان نزدیک‌ترین تثبیت شده، ممکن است با یک یال منفی بعداً فاصله‌اش کمتر شود — ولی الگوریتم دیگر برنمی‌گردد و به‌روزش نمی‌کند","حافظه","ممکن نیست"],"ans":1,"why":"اثبات درستی دایکسترا به نامنفی‌بودن وزن متکی است: تثبیت یعنی «دیگر بهتر نمی‌شود». وزن منفی این تضمین را می‌شکند؛ پس برای آن باید از Bellman-Ford استفاده کرد که چند پاس آرام‌سازی دارد."}]'::jsonb),
('algo-b11', 'algo', 'دو اشاره‌گر و پنجره کشویی', 63, 19, '[{"k":"p","t":"دو اشاره‌گر و پنجره کشویی الگوهایی O(n) برای مسائل زیررشته و زیرآرایه‌اند — جایگزین هوشمندانه حلقه‌های تو در توی O(n²)."},{"k":"h","t":"دو اشاره‌گر؛ حذف حلقه تو در تو"},{"k":"p","t":"خیلی مسائل «جفتی» با دو حلقه تو در تو O(n²) حل می‌شوند، ولی با دو اشاره‌گر که از دو سر یا با سرعت متفاوت حرکت می‌کنند به O(n) می‌رسند. مثلاً برای پیدا کردن جفتی که مجموعش هدف است در آرایه مرتب: یکی از ابتدا و یکی از انتها؛ اگر مجموع کم بود، اشاره چپ را جلو ببر (بزرگ‌تر کن) و اگر زیاد بود، راست را عقب (کوچک‌تر کن). چون آرایه مرتب است، هر حرکت جهت‌دار است و هر عنصر حداکثر یک‌بار دیده می‌شود."},{"k":"h","t":"پنجره کشویی؛ بازه متغیر در یک پاس"},{"k":"p","t":"برای مسائل «بلندترین/کوتاه‌ترین زیرآرایه با شرط»، پنجره کشویی یک بازه [left, right] را در یک پاس حرکت می‌دهد: right جلو می‌رود و عنصر را وارد پنجره می‌کند؛ تا وقتی شرط نقض شد، left جلو می‌رود و عنصرها را خارج می‌کند تا شرط دوباره برقرار شود. چون هر عنصر حداکثر یک‌بار وارد و یک‌بار خارج می‌شود، کل عملیات O(n) است — جایگزین هوشمندانه O(n²)ِ «همه زیرآرایه‌ها را امتحان کن»."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"بلندترین زیررشته بدون کاراکتر تکراری","code":"def longest_unique(s):\n    seen = {}                # کاراکتر → آخرین ایندکسش\n    left = best = 0\n    for right, c in enumerate(s):\n        if c in seen and seen[c] >= left:\n            left = seen[c] + 1      # پنجره را از بعدِ تکراری ببر\n        seen[c] = right\n        best = max(best, right - left + 1)\n    return best\n\nprint(longest_unique(''abcabcbb''))   # 3 → ''abc''"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["پنجره کشویی بازه‌ای متغیر را در یک پاس حرکت می‌دهد","برای «بلندترین زیررشته با شرط» عالی است","دو اشاره‌گر از دو سر برای جفت‌های مجموع هدف"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"sliding.py","code":"# بلندترین زیرآرایه با مجموع ≤ k\ndef longest(a, k):\n    s = left = best = 0\n    for right, x in enumerate(a):\n        s += x\n        while s > k:\n            s -= a[left]; left += 1\n        best = max(best, right - left + 1)\n    return best"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: پنجره کشویی بازه‌ای متغیر را در یک پاس حرکت می‌دهد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا پنجره کشویی O(n) است نه O(n²)؟","opts":["چون داده کوچک است","چون هر عنصر حداکثر یک‌بار وارد و یک‌بار از پنجره خارج می‌شود","چون موازی است","کش دارد"],"ans":1,"why":"اشاره چپ فقط جلو می‌رود و جمع پنجره افزایشی نگه داشته می‌شود؛ پس کل عملیات خطی است."},{"q":"چرا پنجره کشویی O(n) است نه O(n²)؟","opts":["چون داده کوچک","چون هر عنصر حداکثر یک‌بار وارد و یک‌بار از پنجره خارج می‌شود — left فقط جلو می‌رود، پس کل عملیات خطی است","موازی است","کش دارد"],"ans":1,"why":"اگرچه دو حلقه به‌نظر می‌رسد، left هیچ‌وقت عقب نمی‌رود؛ پس مجموع حرکت‌های left در کل اجرا حداکثر n است. این یعنی کار کل متناسب با n است نه n²."},{"q":"در مسئله جفت با مجموع هدف، چرا حرکت اشاره‌گرها جهت‌دار است؟","opts":["تصادفی","چون آرایه مرتب است: اگر مجموع کم باشد فقط جلوبردنِ اشاره چپ آن را بزرگ می‌کند و عقب‌بردن راست بی‌فایده است — پس هر مقایسه یک جهت قطعی دارد","قرارداد","سرعت"],"ans":1,"why":"مرتب‌بودن جهت می‌دهد: مجموعِ کم یعنی به عدد بزرگ‌تر نیاز داری (چپ را جلو)، مجموعِ زیاد یعنی به کوچک‌تر (راست را عقب). پس هیچ حالتی را لازم نیست دوباره بررسی کنی و الگوریتم O(n) می‌شود."}]'::jsonb),
('algo-b12', 'algo', 'کران پایین مرتب‌سازی و پایداری', 56, 20, '[{"k":"p","t":"هر مرتب‌سازی مقایسه‌ای حداقل Ω(n log n) است چون n! ترتیب ممکن باید با مقایسه تفکیک شود؛ مرتب‌سازی‌های غیرمقایسه‌ای مثل شمارشی می‌توانند O(n) باشند."},{"k":"h","t":"کران پایین؛ چرا n log n"},{"k":"p","t":"هر الگوریتم مرتب‌سازی که فقط با مقایسه کار می‌کند، نمی‌تواند بهتر از Ω(n log n) باشد. دلیل: n عنصر می‌توانند n! ترتیب مختلف داشته باشند و الگوریتم باید با مقایسه‌ها یکی را تشخیص دهد؛ هر مقایسه حداکثر دو شاخه می‌سازد، پس حداقل log(n!) مقایسه لازم است که با تقریب استرلینگ Θ(n log n) می‌شود. این یک حد نظری است — یعنی مرج‌سورت و هیپ‌سورت از نظر مقایسه‌ای بهینه‌اند و بهتر از این با مقایسه ممکن نیست."},{"k":"h","t":"راه فرار؛ مرتب‌سازی غیرمقایسه‌ای"},{"k":"p","t":"کران n log n فقط برای الگوریتم‌های مقایسه‌ای است. اگر از ساختار داده‌ها استفاده کنی، می‌توانی بهتر شوی: شمارشی برای اعداد در بازه محدود، O(n+k) است چون اصلاً مقایسه نمی‌کند — فقط تعداد هر مقدار را می‌شمارد و بازپخش می‌کند. سطلی و مبنایی هم همین ایده را دارند. شرطش این است که درباره مقادیر اطلاعات بیشتری داشته باشی (بازه محدود، تعداد رقم کم) — وگرنه همان مقایسه‌ای‌ها انتخاب درست‌اند."},{"k":"def","term":"پایداری (Stability)","t":"خاصیتی که عناصر با کلید برابر، بعد از مرتب‌سازی ترتیب نسبی اولیه‌شان را حفظ می‌کنند. وقتی چندبار با کلیدهای مختلف مرتب می‌کنی (مثل اول بر اساس نام، بعد بر اساس سن) پایداری لازم است تا مرتب‌سازی قبلی به‌هم نریزد — مرج‌سورت پایدار است ولی هیپ‌سورت و کوییک‌سورت نیستند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["الگوریتم","زمان","پایدار","مقایسه‌ای"],"rows":[["مرج‌سورت","O(n log n)","بله","بله"],["هیپ‌سورت","O(n log n)","خیر","بله"],["کوییک‌سورت","O(n log n) میانگین","خیر","بله"],["شمارشی","O(n+k)","بله","خیر"],["مبنا (Radix)","O(d·n)","بله","خیر"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["درخت تصمیم n! برگ دارد و ارتفاعش log(n!) = Ω(n log n)","شمارشی و سطلی وقتی بازه اعداد محدود است O(n)‌اند","پایداری یعنی عناصر برابر ترتیب نسبی‌شان حفظ شود"]},{"k":"h","t":"کاربرد و مقایسه"},{"k":"table","head":["الگوریتم","زمان","پایدار"],"rows":[["مرج‌سورت","O(n log n)","بله"],["کوییک‌سورت","O(n log n) میانگین","خیر"],["شمارشی","O(n+k)","بله"],["حبابی","O(n²)","بله"]]},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: درخت تصمیم n! برگ دارد و ارتفاعش log(n!) = Ω(n log n) بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا مرتب‌سازی مقایسه‌ای نمی‌تواند بهتر از O(n log n) باشد؟","opts":["ممکن نیست سریع‌تر باشد چون باید بین n! ترتیب ممکن با مقایسه تصمیم گرفت","چون کامپیوتر کند است","چون حافظه محدود است","می‌شود با کش"],"ans":0,"why":"هر مقایسه دو شاخه می‌سازد؛ برای تشخیص یکی از n! ترتیب، حداقل log(n!) مقایسه لازم است که Θ(n log n) است."},{"q":"چرا شمارشی می‌تواند O(n) باشد درحالی‌که مرج‌سورت نمی‌تواند؟","opts":["جدیدتر است","چون شمارشی مقایسه نمی‌کند — با شمردن تعداد هر مقدار در بازه محدود کار می‌کند، پس از کران پایینِ مرتب‌سازی‌های مقایسه‌ای معاف است","سریع‌تر همیشه","حافظه بیشتر"],"ans":1,"why":"کران n log n فقط برای الگوریتم‌هایی ثابت شده که با مقایسه تصمیم می‌گیرند. شمارشی از اطلاعات ساختاری (بازه محدود مقادیر) استفاده می‌کند و اصلاً مقایسه ندارد — پس این محدودیت برایش نیست."},{"q":"چه زمانی پایداری مرتب‌سازی واقعاً مهم می‌شود؟","opts":["همیشه","وقتی چند مرحله‌ای با کلیدهای مختلف مرتب می‌کنی — اگر مرحله دوم پایدار نباشد، ترتیبِ مرحله اول بین کلیدهای برابر به‌هم می‌ریزد","هیچ‌وقت","فقط در مرج"],"ans":1,"why":"مثلاً اگر اول بر اساس نام و بعد بر اساس سن مرتب کنی، می‌خواهی هم‌سن‌ها هنوز بر اساس نام مرتب باشند. فقط مرتب‌سازی پایدار این ترتیب قبلی را حفظ می‌کند؛ ناپایدار ممکن است آن را به‌هم بریزد."}]'::jsonb),
('se-r1', 'se', 'نیازمندی‌ها: ساختنِ چیزِ درست، قبل از ساختنِ درستِ چیز', 55, 1, '[{"k":"p","t":"بیشتر پروژه‌های نرم‌افزاری نه به‌خاطر کدِ بد، که به‌خاطر «ساختن چیز اشتباه» شکست می‌خورند. مهندسی نیازمندی‌ها همان مهارتی است که فاصله بین «مشتری این را می‌خواست» و «ما این را ساختیم» را پر می‌کند — و ارزان‌ترین جای اصلاح باگ، دقیقاً همین‌جاست: قبل از نوشتن حتی یک خط کد."},{"k":"h","t":"دو جنس نیازمندی"},{"k":"p","t":"نیازمندی کارکردی می‌گوید سیستم «چه کاری» انجام دهد: «کاربر بتواند رمز عبورش را بازیابی کند.» نیازمندی غیرکارکردی می‌گوید آن کار «چقدر خوب» انجام شود: «بازیابی رمز در کمتر از ۲ ثانیه و با امنیت کافی.» تیم‌های بی‌تجربه فقط اولی را می‌نویسند و دومی را به شانس می‌سپارند — و بعد در Production کشف می‌کنند که سیستم کند، ناامن یا غیرقابل‌نگهداری است. نیازمندی‌های غیرکارکردی (سرعت، امنیت، دسترس‌پذیری، مقیاس‌پذیری) معمولاً همان‌هایی‌اند که معماری را تعیین می‌کنند، نه فیچرها."},{"k":"h","t":"User Story: نیاز از چشم کاربر"},{"k":"p","t":"قالب استاندارد صنعت: «به‌عنوان [نقش]، می‌خواهم [کار]، تا [ارزش]». مثال: «به‌عنوان مشتری، می‌خواهم سفارش‌های قبلی‌ام را ببینم، تا بدون تماس با پشتیبانی وضعیت را پیگیری کنم.» بخش سوم («تا...») مهم‌ترین بخش است و معمولاً جا می‌افتد — چون ارزش است که اولویت را تعیین می‌کند و جلوی فیچرهای بیهوده را می‌گیرد. هر Story باید INVEST باشد: مستقل، قابل‌مذاکره، ارزشمند، برآوردپذیر، کوچک و تست‌پذیر. Story که این ویژگی‌ها را ندارد، هنوز آماده Sprint نیست."},{"k":"h","t":"معیار پذیرش: قراردادِ «تمام شد»"},{"k":"p","t":"هر Story با معیارهای پذیرش (Acceptance Criteria) کامل می‌شود — شرایطی که اگر برقرار باشند، کار تمام است: «رمز جدید باید حداقل ۸ کاراکتر باشد؛ لینک بازیابی بعد از ۱۵ دقیقه منقضی شود؛ بعد از سه تلاش ناموفق، ۱۰ دقیقه قفل شود.» این معیارها سه کار می‌کنند: ابهام را قبل از توسعه می‌کشند، مبنای تست می‌شوند و جلوی «Scope Creep» را می‌گیرند. تیم‌هایی که بدون معیار پذیرش کار می‌کنند، هر فیچر را دو بار تحویل می‌دهند: یک بار کد، یک بار بحث درباره اینکه منظور چه بود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"user-story.md","code":"# Story: بازیابی رمز عبور\nبه‌عنوان کاربری که رمز را فراموش کرده،\nمی‌خواهم با ایمیل رمز جدید بگیرم،\nتا بدون تماس با پشتیبانی وارد شوم.\n\n## معیارهای پذیرش\n- [ ] لینک بازیابی فقط ۱۵ دقیقه اعتبار دارد\n- [ ] لینک بعد از اولین استفاده باطل می‌شود (one-time)\n- [ ] بعد از ۳ تلاش ناموفق، ۱۰ دقیقه قفل\n- [ ] ایمیل حداکثر ۲ دقیقه بعد می‌رسد\n- [ ] کاربرِ ناموجود هم همان پاسخ «اگر حسابی\n      با این ایمیل باشد، لینک فرستادیم» می‌گیرد\n      (جلوگیری از شمارش کاربران واقعی)\n\n## ارزش: کاهش ۴۰٪ تیکت‌های پشتیبانی"},{"k":"list","items":["نقش و کار و ارزش در سه خط اول — هر سه لازم‌اند؛ بدون «ارزش» اولویت‌بندی ممکن نیست.","معیارها قابل‌تست‌اند: هر کدام را می‌توان با یک تست خودکار یا دستی بررسی کرد.","معیار one-time و انقضا، نیازمندی‌های امنیتی‌اند که «غیرکارکردی» را به «قابل‌سنجش» تبدیل کرده‌اند.","معیار آخر یک نکته ظریف امنیتی را به قرارداد محصول تبدیل کرده — این یعنی مهندسی نیازمندی‌های بالغ."]},{"k":"def","term":"Definition of Done","t":"فهرست مشترک تیم از معنای «تمام»: کد نوشته شد، تست‌ها پاس شدند، ریویو شد، مستند شد و Deploy شد. DoD برای همه Storyها یکی است؛ معیار پذیرش برای هر Story جدا. تیمی که این دو را قاطی کند، هم فیچر ناقص تحویل می‌دهد هم بحث بی‌پایان می‌کند."},{"k":"table","head":["","بدون مهندسی نیازمندی","با مهندسی نیازمندی"],"rows":[["ابهام","وسط توسعه کشف می‌شود (۱۰ برابر گران‌تر)","قبل از توسعه، روی کاغذ حل می‌شود"],["اولویت","هرکس بلندتر فریاد بزند","ارزشِ User Story تعیین می‌کند"],["تست","بعد از کد، سلیقه‌ای","از معیار پذیرش مشتق می‌شود"],["محدوده","هر روز بزرگ‌تر می‌شود","با INVEST و معیارها ثابت می‌ماند"]]},{"k":"warn","title":"دام رایج","t":"نوشتن نیازمندی به‌صورت «راه‌حل فنی» به‌جای «نیاز کاربر»: «یک جدول Redis برای Session بسازیم» نیازمندی نیست؛ «کاربر بعد از بستن مرورگر هم لاگین بماند» نیازمندی است. اولی دست توسعه‌دهنده را می‌بندد؛ دومی راه را باز می‌گذارد و اجازه می‌دهد بهترین راه‌حل فنی انتخاب شود."},{"k":"tip","title":"نکته حرفه‌ای","t":"هر Story را قبل از Sprint با سه سوال بازجویی کن: آیا کاربر واقعاً این را می‌خواهد یا حدس ماست؟ آیا می‌توانیم کوچک‌ترش کنیم؟ و «تستش» چه شکلی است؟ Story که از این سه سوال رد شود، آماده است — بقیه هنوز «ایده»‌اند، نه کار."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["نیازمندی کارکردی = چه کاری؛ غیرکارکردی = چقدر خوب؛ دومی معماری را می‌سازد.","User Story بدون بخش «تا...» ناقص است؛ معیار پذیرش آن را تست‌پذیر می‌کند.","ابهام را قبل از کد بکش — ارزان‌ترین جا همین‌جاست."]}]'::jsonb, '[{"q":"چرا بخش «تا...» در User Story مهم‌ترین بخش است؟","opts":["قشنگ‌ترش می‌کند","چون ارزشِ واقعی را بیان می‌کند و مبنای اولویت‌بندی و حذف فیچرهای بیهوده است","برای مستندات","اجباری نیست"],"ans":1,"why":"بدون دانستن ارزش، نمی‌شود تصمیم گرفت این Story مهم‌تر از آن یکی است یا اصلاً لازم است؛ ارزش، قطب‌نمای محصول است."},{"q":"تفاوت معیار پذیرش با Definition of Done چیست؟","opts":["فرقی ندارند","معیار پذیرش برای هر Story جدا و مشخص‌کننده رفتار آن است؛ DoD برای همه Storyها یکی و مشخص‌کننده کیفیت تحویل است","DoD مهم‌تر است","معیار پذیرش فنی است"],"ans":1,"why":"DoD می‌گوید «تحویل یعنی چه» (تست، ریویو، Deploy)؛ معیار پذیرش می‌گوید «این فیچر خاص یعنی چه». یکی افقی است و یکی عمودی."},{"q":"کدام‌یک نیازمندی «واقعی» است؟","opts":["یک کش Redis بسازیم","کاربر بعد از بستن مرورگر هم لاگین بماند","از JWT استفاده کنیم","جدول Session اضافه کنیم"],"ans":1,"why":"سه تای دیگر راه‌حل فنی‌اند؛ فقط دومی نیاز کاربر را بیان می‌کند و دست تیم را برای انتخاب بهترین راه‌حل باز می‌گذارد."}]'::jsonb),
('se-r2', 'se', 'SOLID: پنج اصل برای کدی که ۵ سال دیگر هم زنده است', 60, 2, '[{"k":"p","t":"کد یک‌بار نوشته می‌شود و صدها بار خوانده و تغییر داده می‌شود. SOLID حفظیات مصاحبه نیست؛ فهرست پنج بوی بدِ طراحی است که هرکدام با یک اصل خنثی می‌شود. در این درس هر پنج را روی یک مثال واقعی — سیستم صدور فاکتور — پیاده می‌کنیم تا از شعار به ابزار تبدیل شوند."},{"k":"h","t":"S و O: یک دلیل برای تغییر، باز بدون دست‌زدن"},{"k":"p","t":"اصل مسئولیت واحد (SRP): هر کلاس دقیقاً یک دلیل برای تغییر داشته باشد. کلاسی که هم فاکتور را حساب می‌کند هم PDF می‌سازد هم ایمیل می‌فرستد، با هر تغییر در هر سه حوزه تغییر می‌کند — و هر تغییر، ریسک شکستن بقیه. اصل باز-بسته (OCP): موجودیت‌ها برای گسترش باز و برای تغییر بسته باشند؛ یعنی افزودن رفتار جدید بدون دست‌زدن به کد قدیمی. وقتی افزودن یک نوع تخفیف جدید یعنی تغییر دادن تابع if/else موجود، OCP نقض شده — و باگ‌ها دقیقاً از همان دست‌زدن‌ها می‌آیند."},{"k":"h","t":"L و I: قول‌هایی که می‌شکنند"},{"k":"p","t":"اصل جایگزینی لیسکوف (LSP): زیرکلاس باید بتواند بدون غافلگیری جای والدش را بگیرد. کلاسیک‌ترین نقض: Square که از Rectangle ارث می‌برد ولی invariantِ «عرض و طول مستقل‌اند» را می‌شکند — کدی که با Rectangle کار می‌کند، با Square می‌شکند. اصل جداسازی رابط (ISP): هیچ کلاینتی نباید مجبور به وابستگی به متدهایی باشد که استفاده نمی‌کند؛ یک Interface چاق را به چند Interface لاغر بشکن. در عمل، LSP و ISP هر دو می‌گویند: «قراردادها را دقیق و کوچک نگه دار»."},{"k":"h","t":"D: وابستگی به قرارداد، نه به جزئیات"},{"k":"p","t":"اصل وارونگی وابستگی (DIP): ماژول‌های رده‌بالا نباید به ماژول‌های رده‌پایین وابسته باشند؛ هر دو باید به انتزاع وابسته باشند. به‌جای اینکه OrderService مستقیماً new MySqlInvoiceRepository() بسازد، یک Interface می‌گیرد و در زمان اجرا (Dependency Injection) پیاده‌سازی تزریق می‌شود. نتیجه عملی: تست بدون دیتابیس، تعویض دیتابیس بدون تغییر سرویس، و کدی که لایه‌هایش واقعاً جداست. DI فریم‌ورک جادویی نیست — همین یک خط: وابستگی را از بیرون بگیر، از درون نساز."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"solid_invoice.py","code":"from abc import ABC, abstractmethod\n\n# SRP: محاسبه فقط محاسبه؛ چاپ فقط چاپ\n# OCP: تخفیف جدید = کلاس جدید، بدون تغییر DiscountRule\nclass DiscountRule(ABC):\n    @abstractmethod\n    def apply(self, total: float) -> float: ...\n\nclass SeasonalDiscount(DiscountRule):\n    def apply(self, total):\n        return total * 0.9\n\nclass VipDiscount(DiscountRule):            # ← افزودن، نه تغییر\n    def apply(self, total):\n        return total * 0.8\n\nclass InvoiceCalculator:\n    def __init__(self, rule: DiscountRule):  # DIP: وابستگی به قرارداد\n        self.rule = rule\n\n    def final(self, total: float) -> float:\n        return self.rule.apply(total)\n\n# تزریق از بیرون:\ncalc = InvoiceCalculator(VipDiscount())\nprint(calc.final(1000))   # 800.0"},{"k":"list","items":["InvoiceCalculator فقط «محاسبه با یک قانون» را بلد است — چاپ PDF و ایمیل جای دیگرند (SRP).","افزودن تخفیف وفاداری یعنی یک کلاس جدید؛ هیچ خطی از کد قبلی تغییر نکرد (OCP).","سازنده به‌جای ساختن تخفیف، آن را می‌گیرد — پس در تست می‌توان تخفیف ساختگی تزریق کرد (DIP).","همین تزریق ساده، ریشه تست‌پذیری و معماری لایه‌ای مدرن است."]},{"k":"def","term":"بوی کد (Code Smell)","t":"نشانه ظاهری در کد که خبر از مشکل عمیق‌تر طراحی می‌دهد — مثل کلاس خدا (همه‌چیزدان)، زنجیره if/else که با هر نوع جدید بلندتر می‌شود، یا پارامترهای زیاد. SOLID را حفظ نکن؛ یاد بگیر این بوها را وسط کد معمولی «ببویی» و اصلِ مربوط را به‌عنوان درمان به کار ببری."},{"k":"table","head":["اصل","بوی بدی که درمان می‌کند","مثال عملی"],"rows":[["SRP","کلاس خدا","InvoiceCalculator فقط محاسبه می‌کند"],["OCP","if/else فزاینده","افزودن DiscountRule جدید بدون تغییر"],["LSP","زیرکلاسِ قول‌شکن","Square از Rectangle ارث نبرد"],["ISP","Interface چاق","ReadableWritable را بشکن"],["DIP","newِ مستقیمِ جزئیات","تزریق Interface از بیرون"]]},{"k":"warn","title":"دام رایج","t":"زیاده‌روی در SOLID خودش بوی بد است: برای یک اسکریپت ۵۰ خطی، سه Interface و دو Factory نساز. اصول برای «کدی که قرار است رشد کند و چند نفر رویش کار کنند»‌اند — نه همه کد. هنر، تشخیص مرز بین مهندسی و تشریفات است."},{"k":"tip","title":"نکته حرفه‌ای","t":"در Code Review بعدی، به‌جای بحث سلیقه‌ای، یکی از این سوالات را بپرس: «این کلاس چند دلیل برای تغییر دارد؟» یا «افزودن نوع جدید اینجا چند فایل را عوض می‌کند؟» — SOLID وقتی زبانی مشترک برای ریویو شود، کیفیت تیم پله‌ای بالا می‌رود."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["هر کلاس یک دلیل تغییر؛ رفتار جدید بدون دست‌زدن به قدیم.","قراردادها کوچک و صادق؛ زیرکلاس نباید قول والد را بشکند.","وابستگی به Interface + تزریق از بیرون = تست‌پذیری و تعویض‌پذیری."]}]'::jsonb, '[{"q":"کلاسی که هم فاکتور حساب می‌کند هم PDF می‌سازد، کدام اصل را نقض کرده؟","opts":["OCP","SRP — چون سه دلیل مختلف برای تغییر دارد","LSP","DIP"],"ans":1,"why":"تغییر قالب PDF، قانون مالیات یا قالب ایمیل، هرکدام این کلاس را تغییر می‌دهند؛ سه دلیل تغییر یعنی سه برابر ریسک در هر ویرایش."},{"q":"افزودن نوع تخفیف جدید بدون تغییر کد موجود، کدام اصل است؟","opts":["SRP","ISP","OCP — گسترش با افزودن، نه با تغییر دادن","LSP"],"ans":2,"why":"وقتی توسعه یعنی فقط «افزودن کلاس جدید» و کد قدیمی دست‌نخورده می‌ماند، باگ‌های ناشی از تغییر از بین می‌روند — این قول Open/Closed است."},{"q":"تزریق وابستگی (DI) در عمل یعنی چه؟","opts":["استفاده از فریم‌ورک Spring","وابستگی‌ها را از بیرون بگیر، نه اینکه داخل کلاس با new بسازی","هر کلاس یک Interface","وارونگی کنترل کامل"],"ans":1,"why":"در ساده‌ترین شکل، همان سازنده‌ای است که Interface را می‌گیرد؛ فریم‌ورک‌ها فقط این کار را در مقیاس بزرگ خودکار می‌کنند."}]'::jsonb),
('c5-l1', 'se', 'چرخه حیات و مدل‌های توسعه', 50, 3, '[{"k":"p","t":"هر نرم‌افزاری از ایده تا بازنشستگی مسیری دارد که به آن چرخه حیات (SDLC) می‌گویند: تحلیل نیازمندی‌ها، طراحی، پیاده‌سازی، تست، استقرار و نگهداری. مدل‌های توسعه، ترتیب و تکرار این مراحل را مشخص می‌کنند و انتخاب مدل اشتباه می‌تواند پروژه را بکشد."},{"k":"table","head":["مدل","ویژگی","مناسب برای"],"rows":[["آبشاری","مراحل پشت‌سرهم و بدون بازگشت","پروژه‌های با نیازمندی ثابت مثل سیستم‌های حیاتی"],["اجایل","تحویل تکرارشونده در اسپرینت‌های کوتاه","محصولاتی که نیازمندی‌شان تغییر می‌کند"],["اسکرام","چارچوب اجایل با نقش‌ها و جلسات مشخص","تیم‌های محصول ۳ تا ۹ نفره"],["کنبان","جریان پیوسته با محدودیت کار در حال انجام","تیم‌های پشتیبانی و DevOps"]]},{"k":"visual","visual":"sdlc","title":"شبیه‌ساز: چرخه حیات نرم‌افزار"},{"k":"def","term":"Sprint","t":"بازه زمانی ثابت (معمولاً ۲ هفته) که تیم در آن یک قطعه قابل‌تحویل از محصول می‌سازد؛ در پایان، دموی واقعی به ذی‌نفعان نشان داده می‌شود نه گزارش وضعیت."},{"k":"warn","title":"اشتباه رایج","t":"اجایل به معنی «بدون مستندات و طراحی» نیست! مانیفست اجایل می‌گوید مستندات ارزشمند است، فقط نرم‌افزارِ کارکردی ارزشمندتر. تیم‌هایی که طراحی را کلاً حذف می‌کنند، به بدهی فنی غرق می‌شوند."},{"k":"tip","title":"نکته منتور","t":"به‌عنوان مهندس تازه‌کار لازم نیست مدل را انتخاب کنی، اما باید بفهمی تیمت چرا اسپرینت دارد، چرا هر روز Daily برگزار می‌شود و Definition of Done یعنی چه — این‌ها زبان مشترک توست."},{"k":"h","t":"عمیق‌تر: چرا مدل‌ها شکست می‌خورند و چطور انتخاب کنیم"},{"k":"p","t":"هیچ پروژه‌ای دقیقاً طبق برنامه پیش نمی‌رود؛ سوال این است که «وقتی برنامه شکست خورد، چه کسی و چطور تصمیم می‌گیرد؟» آبشاری این سوال را به ابتدای پروژه می‌برد و فرض می‌کند همه‌چیز از اول مشخص است — فرضی که برای پل و ساختمان صادق است، برای نرم‌افزار نه. نرم‌افزار را نمی‌سازیم تا بفهمیم چه می‌خواهیم؛ فهمیدن، بخشی از ساختن است. اسکرام این واقعیت را پذیرفته و به‌جای یک برنامه بزرگ، ده‌ها تصمیم کوچک و قابل‌بازگشت می‌گیرد؛ هر اسپرینت یک آزمایش است، نه یک تعهد."},{"k":"p","t":"اما اسکرام هم وقتی بد اجرا شود، فقط جلسات اضافه است. نشانه‌های اسکرام سالم: بک‌لاگ واقعاً اولویت‌بندی شده، دمو هر دو هفته واقعاً چیزی کارآمد نشان می‌دهد (نه اسلاید)، و تیم اجازه دارد بگوید «نه». نشانه‌های بیمار: دمو اسلایدی، Daily که به جلسه گزارش‌دهی به مدیر تبدیل شده و اسپرینت‌هایی که همیشه «۹۵٪ تمام»‌اند. بین این دو طیف، مدل‌های هیبریدی هم هستند: شرکت‌های بزرگ اغلب برای زیرساخت Waterfall-ish و برای محصول Agile کار می‌کنند — مهندسی یعنی شناختن بافت، نه وفاداری به یک مذهب."},{"k":"table","head":["بافت پروژه","مدل پیشنهادی","چرا"],"rows":[["سیستم حیاتی با الزامات ثابت (پزشکی، هوافضا)","آبشاری / V-Model","مستندات و تأیید مرحله‌به‌مرحله قانوناً لازم است"],["محصول با بازار ناشناخته","اسکرام / Lean","یادگیری سریع از کاربر مهم‌تر از نقشه کامل است"],["تیم کوچک با بلوغ بالا","Kanban","مراسم حداقلی؛ جریان کار مهم است نه تشریفات"],["پروژه تحقیقاتی / PoC","Spike + Prototype","هدف یادگیری است، نه تحویل — زود دور بریز"]]},{"k":"p","t":"یک مفهوم که همه مدل‌ها را زیر سوال می‌برد: «بدهی فنی» — انتخاب‌های سریعِ امروز که بهره‌اش را فردا می‌پردازیم. هر مدلی که بدهی فنی را نبیند (آبشاری) یا جدی نگیرد (اسکرام بی‌انضباط)، دیر یا زود سرعت تیم را به صفر می‌رساند. تیم‌های بالغ در هر اسپرینت سهمی برای بازپرداخت بدهی کنار می‌گذارند و آن را در دمو به ذی‌نفعان نشان می‌دهند؛ چون ریفکتور دیده نمی‌شود مگر اینکه عمداً مرئی‌اش کنی."},{"k":"tip","title":"نکته منتور","t":"در مصاحبه‌های موقعیت‌های ارشد، تقریباً همیشه می‌پرسند «یک بارت اسکرام جواب نداد؛ چه کردی؟» جواب قوی ساختار دارد: تشخیص علامت (Velocity جعلی، اسپرینت همیشه باز)، آزمایش کوچک (کوتاه‌کردن اسپرینت به یک هفته برای مرئی‌شدن مشکل)، و اندازه‌گیری نتیجه. این یعنی تفکر مهندسی درباره خودِ فرایند."}]'::jsonb, '[{"q":"برای پروژه‌ای که نیازمندی‌هایش هر ماه عوض می‌شود کدام مدل مناسب‌تر است؟","opts":["آبشاری","اسپایک","اجایل","V-Model"],"ans":2,"why":"اجایل با تحویل‌های کوتاه و بازخورد مداوم، تغییر نیازمندی را به‌جای مبارزه با آن، در آغوش می‌گیرد."},{"q":"Definition of Done چیست؟","opts":["تاریخ پایان پروژه","چک‌لیست مشترک تیم برای «تمام‌شده» بودن یک کار","مستندات نهایی","تأیید مدیر پروژه"],"ans":1,"why":"مثلاً «کد نوشته شد + تست نوشت + مرور شد + در staging استقرار یافت». بدون آن، هر کس تعریف خودش را از تمام‌شدن دارد."}]'::jsonb),
('c5-l2', 'se', 'نیازمندی‌ها و User Story', 55, 4, '[{"k":"p","t":"بیشتر شکست پروژه‌ها نه به‌خاطر کد بد، که به‌خاطر ساختن چیز اشتباه است. نیازمندی‌ها دو دسته‌اند: کارکردی (سیستم چه کاری انجام دهد) و غیرکارکردی (چقدر خوب انجام دهد؛ مثل سرعت، امنیت و دسترس‌پذیری). User Story قالب استاندارد بیان نیاز از دید کاربر است."},{"k":"code","lang":"txt","title":"user-story.example","code":"عنوان: سبد خرید مهمان\n\nبه‌عنوان [کاربر مهمان]\nمی‌خواهم [بدون ثبت‌نام محصول را به سبد اضافه کنم]\nتا [خریدم را سریع‌تر شروع کنم]\n\nمعیارهای پذیرش:\n- با کلیک «افزودن»، نشانگر سبد به‌روز شود\n- سبد مهمان با ورود کاربر ادغام شود\n- اگر کالا ناموجود شد، هشدار نمایش داده شود"},{"k":"def","term":"INVEST","t":"ویژگی‌های یک User Story خوب: مستقل، قابل‌مذاکره، ارزشمند، قابل‌برآورد، کوچک و قابل‌تست. داستانی که این ویژگی‌ها را ندارد، هنوز آماده اسپرینت نیست."},{"k":"list","items":["نیازمندی کارکردی: «کاربر بتواند رمز عبور را بازیابی کند»","نیازمندی غیرکارکردی: «صفحه ورود در کمتر از ۲ ثانیه بارگذاری شود»","معیار پذیرش، داستان را تست‌پذیر و ابهام را حذف می‌کند","Story Point برآورد نسبی پیچیدگی است، نه ساعت کار"]},{"k":"warn","title":"خطر ابهام","t":"جمله «سیستم باید سریع باشد» نیازمندی نیست؛ چون تست‌پذیر نیست. همیشه بپرس: سریع یعنی چه؟ برای چه درصدی از درخواست‌ها؟ با چه سخت‌افزاری؟ عدد بنویس: P95 < 200ms."},{"k":"h","t":"عمیق‌تر: از Use Case تا قرارداد — پلی که تیم‌ها را نجات می‌دهد"},{"k":"p","t":"بزرگ‌ترین ارزش Use Case در نگارش «جریان اصلی» نیست؛ در وادار کردنت به نوشتن «جریان‌های فرعی» است: اگر کاربر اشتباه زد چه؟ اگر سیستم پرداخت پاسخ نداد چه؟ اگر همزمان دو نفر ویرایش کردند چه؟ این سناریوها دقیقاً همان‌هایی‌اند که در پیاده‌سازی به باگ تبدیل می‌شوند — چون هنگام کدنویسی کسی به آن‌ها فکر نکرده. یک Use Case کامل برای هر سناریو سه بخش دارد: پیش‌شرط (چه چیزی باید برقرار باشد)، جریان (قدم‌های کاربر و پاسخ سیستم) و پس‌شرط (وضعیت نهایی). وقتی این سه را داری، تست‌نویسی فقط ترجمه است."},{"k":"p","t":"و وقتی Use Case به API می‌رسد، باید به «قرارداد» تبدیل شود: چه مسیری، چه متدی، چه ورودی با چه محدودیت‌هایی، چه خروجی و چه کدهای خطایی. تیم‌هایی که اول قرارداد را می‌نویسند و بعد فرانت و بک موازی کار می‌کنند، چند برابر سریع‌تر از تیم‌هایی‌اند که «اول بک را بسازیم بعد فرانت وصل شود». ابزارهایی مثل OpenAPI همین قرارداد را ماشین‌خوان می‌کنند تا از همان قرارداد، مستندات، اعتبارسنجی و حتی کد کلاینت تولید شود — یعنی قرارداد فقط کاغذ نیست، یک منبع حقیقت اجراشونده است."},{"k":"code","lang":"yaml","title":"قرارداد کوچک ولی کامل","code":"# ثبت سفارش — قرارداد قبل از هر خط کد\nPOST /orders\nورودی:\n  items: آرایه‌ای غیرخالی از {sku: رشته، qty: عدد ۱ تا ۱۰۰}\nخروجی‌ها:\n  201  {order_id, total}      # ساخته شد\n  400  {error: ''INVALID_ITEMS''}  # ورودی نامعتبر\n  409  {error: ''OUT_OF_STOCK'', sku}  # موجودی کافی نیست\nپیش‌شرط: کاربر احراز هویت شده\nپس‌شرط: موجودی skuها به‌اندازه qty کم شده"}]'::jsonb, '[{"q":"«سیستم باید ۹۹.۹٪ مواقع در دسترس باشد» چه نوع نیازمندی‌ای است؟","opts":["کارکردی","غیرکارکردی","User Story","معیار پذیرش"],"ans":1,"why":"دسترس‌پذیری کیفیت کارکرد سیستم را بیان می‌کند نه خود کارکرد؛ از خانواده نیازمندی‌های غیرکارکردی است."},{"q":"در قالب User Story، بخش «تا ...» چه چیزی را بیان می‌کند؟","opts":["جزئیات فنی","ارزش و انگیزه کاربر","معیار پذیرش","برآورد زمانی"],"ans":1,"why":"این بخش چرا را روشن می‌کند؛ بدون دانستن ارزش، تیم نمی‌تواند راه‌حل‌های ساده‌تر و بهتر پیشنهاد بدهد."}]'::jsonb),
('c5-l3', 'se', 'UML؛ زبان مشترک طراحی', 65, 5, '[{"k":"p","t":"قبل از ساختن پل، نقشه می‌کشند؛ قبل از کد هم طراحی لازم است. UML مجموعه‌ای از دیاگرام‌های استاندارد است که ساختار و رفتار سیستم را بدون وابستگی به زبان برنامه‌نویسی نشان می‌دهد. سه پرکاربردترین: Use Case برای محدوده سیستم، Class برای ساختار و Sequence برای رفتار."},{"k":"code","lang":"txt","title":"use-case (متنی)","code":"سیستم: فروشگاه آنلاین\n\n[مشتری] ── (مشاهده محصول)\n[مشتری] ── (افزودن به سبد)\n[مشتری] ── (پرداخت) ──include──> (اعتبارسنجی آدرس)\n[مدیر]  ── (تعریف تخفیف)\n(پرداخت) ──extend──> (پرداخت اقساطی)  [فقط برای سبد بالای ۵ میلیون]"},{"k":"def","term":"رابطه‌های کلاس‌دیاگرام","t":"Association (همکاری ساده)، Aggregation (کل‌جزءِ قابل‌جدایی؛ کلاس و دانشجو)، Composition (کل‌جزءِ وابسته؛ خانه و اتاق) و Inheritance (ارث‌بری). جهت فلش و شکل لوزی، نوع رابطه را مشخص می‌کند."},{"k":"code","lang":"txt","title":"sequence (متنی)","code":"User ->> UI : کلیک «پرداخت»\nUI ->> API : POST /orders\nAPI ->> Payment : charge(amount)\nPayment -->> API : success + ref_id\nAPI ->> DB : INSERT order\nAPI -->> UI : 201 Created\nUI -->> User : نمایش رسید"},{"k":"tip","title":"نکته منتور","t":"دیاگرام را برای فکرکردن بکش، نه برای آرشیو. یک کلاس‌دیاگرام روی تخته قبل از کد، ساعت‌ها ریفکتور بعدی را حذف می‌کند؛ و همیشه از ابزارهایی مثل PlantUML یا Mermaid استفاده کن تا دیاگرام کنار کد و تحت نسخه‌کنترل بماند."},{"k":"h","t":"عمیق‌تر: UML کی بکشیم، کی نکشیم"},{"k":"p","t":"UML ۱۴ نوع نمودار دارد ولی مهندسان واقعاً سه‌تایش را استفاده می‌کنند: کلاس (ساختار ایستا)، Sequence (رفتار در زمان) و Activity (جریان کار). قانون طلایی: نمودار برای «گفتگو» است نه برای «بایگانی». نموداری که بعد از جلسه به‌روز نمی‌شود، بعد از یک ماه دروغ می‌گوید و خطرناک‌تر از نبودنش است. پس: روی تخته بکش، عکس بگیر، دور بینداز — مگر نمودارهایی که تصمیم معماری را ثبت می‌کنند و کنار کد، در ریپازیتوری زنده می‌مانند (ترجیحاً به‌صورت متن، مثل PlantUML یا Mermaid که با کد Diff می‌خورند)."},{"k":"p","t":"در کلاس‌دیاگرام، چهار رابطه را به ترتیب قدرت بشناس: وابستگی (استفاده گذرا — یک متد)، Association (ارتباط پایدار — فیلد)، Aggregation (مالکیت ضعیف — تیم و عضو؛ عضو بدون تیم هم معنا دارد) و Composition (مالکیت قوی — خانه و اتاق؛ اتاق بدون خانه نیست). تفاوت Composition و Aggregation در کد یعنی: آیا فرزند را خودم می‌سازم و نابود می‌کنم یا از بیرون می‌گیرم؟ همین یک سوال، مالکیت داده و مسئولیت پاک‌سازی را در طراحی مشخص می‌کند و جلوی باگ‌های «شیء یتیم» را می‌گیرد."},{"k":"code","lang":"txt","title":"sequence — سناریوی خرید (Mermaid)","code":"sequenceDiagram\n  کاربر->>سبد خرید: افزودن کالا\n  سبد خرید->>موجودی: بررسی تعداد\n  موجودی-->>سبد خرید: ۳ عدد باقی‌مانده\n  کاربر->>پرداخت: ثبت سفارش\n  پرداخت->>درگاه بانکی: درخواست کسر\n  درگاه بانکی-->>پرداخت: موفق\n  پرداخت->>سفارش: ساخت سفارش (اتمیک با کسر)\n  سفارش-->>کاربر: کد پیگیری\n  Note over پرداخت,سفارش: اگر درگاه قطع شود؟\n  Note right of سفارش: Saga: جبران‌کننده تعریف شده"},{"k":"p","t":"نمودار Sequence برای یک چیز بی‌نظیر است: پیدا کردن جاهایی که «همه‌چیز خوب پیش نمی‌رود». وقتی فلش‌ها را می‌کشی، مجبوری بپرسی: اگر این فراخوانی timeout شود چه؟ اگر این پاسخ خطا باشد چه؟ و این سوال‌ها دقیقاً همان‌هایی‌اند که کدریوی و تست بعداً پیدایشان می‌کنند — با این تفاوت که روی تخته، قیمت‌شان صفر است. قانون سرانگشتی: برای هر سناریوی اصلی محصول، یک Sequence بکش که شامل حداقل دو مسیر خطا باشد."},{"k":"tip","title":"نکته منتور","t":"Mermaid را یاد بگیر — نمودار به‌صورت متن داخل فایل Markdown ریپازیتوری می‌ماند، با کد نسخه‌بندی می‌شود و در GitHub هم رندر می‌شود. یک پوشه docs/diagrams در پروژه‌ات بساز و هر تصمیم معماری را با یک نمودار + چند خط «چرا» ثبت کن؛ شش ماه بعد، خودت اولین کسی خواهی بود که تشکر می‌کند."}]'::jsonb, '[{"q":"رابطه «دانشگاه و دانشجو» از چه نوعی است؟","opts":["Composition","Aggregation","Inheritance","Association ساده"],"ans":1,"why":"دانشجو بدون دانشگاه هم وجود دارد؛ رابطه کل‌جزء قابل‌جدایی است. برخلاف خانه و اتاق که با هم ساخته و با هم نابود می‌شوند."},{"q":"کدام دیاگرام برای نمایش ترتیب پیام‌ها بین اجزا مناسب است؟","opts":["Use Case","Class","Sequence","Deployment"],"ans":2,"why":"Sequence Diagram تعاملات را در محور زمان و به ترتیب رخ‌دادن نشان می‌دهد؛ ایده‌آل برای سناریوهایی مثل فرایند پرداخت."}]'::jsonb),
('se-x1', 'se', 'اسکرام در عمل — از بک‌لاگ تا رترو', 40, 6, '[{"k":"p","t":"اسکرام یک متدولوژی سنگین نیست؛ یک «چرخه بازخورد کوتاه» است: به‌جای یک سال برنامه‌ریزی و یک تحویل بزرگ، هر دو هفته یک نسخه قابل‌ارائه می‌سازی و از بازار یاد می‌گیری. همه مراسم‌هایش برای همین هدف‌اند: شفافیت، بازرسی و سازگاری."},{"k":"visual","visual":"sdlc","title":"چرخه‌ای که هر اسپرینت تکرار می‌شود"},{"k":"h","t":"چهار مراسم، سه نقش، دو محصول"},{"k":"table","head":["مراسم","کی؟","هدف","مدت (اسپرینت ۲ هفته)"],"rows":[["برنامه‌ریزی اسپرینت","اول اسپرینت","انتخاب آیتم‌های بک‌لاگ و تعهد تیم","۴ ساعت"],["اسکرام روزانه","هر روز","هماهنگی: دیروز، امروز، مانع","۱۵ دقیقه"],["بازبینی (Review)","آخر اسپرینت","نمایش محصول واقعی به ذی‌نفعان","۲ ساعت"],["بازنگری (Retro)","بعد از Review","بهبود فرایند: چه چیزی را عوض کنیم؟","۱٫۵ ساعت"]]},{"k":"def","term":"Definition of Done","t":"چک‌لیست مشترک و غیرقابل‌مذاکره برای «تمام‌شدن»: کد نوشته شد، تست نوشت و پاس شد، مرور شد، مستند شد، در محیط آزمایش استقرار یافت. بدون DoD، «تموم شد» یعنی هر چیزی که هر کس دلش بخواهد — و اسپرینت بعدی با بدهی شروع می‌شود."},{"k":"code","lang":"txt","title":"ساختار یک User Story خوب","code":"به‌عنوان [کاربر لاگین‌کرده]\nمی‌خواهم [تاریخچه سفارش‌هایم را ببینم]\nتا [بتوانم خرید قبلی‌ام را دوباره تکرار کنم]\n\nمعیارهای پذیرش:\n  ✓ لیست ۱۰ سفارش آخر با تاریخ و مبلغ\n  ✓ کلیک روی هر سفارش → جزئیات اقلام\n  ✓ حالت خالی: پیام راهنما + دکمه خرید اول\n  ✓ زمان بارگذاری زیر ۲ ثانیه\n\nامتیاز: ۵ | اولویت: بالا | اسپرینت: ۱۴"},{"k":"list","items":["بک‌لاگ محصول: لیست زنده و اولویت‌بندی‌شده همه آرزوها — صاحب: Product Owner","بک‌لاگ اسپرینت: تعهد این دو هفته — صاحب: تیم توسعه","Velocity: میانگین امتیاز اسپرینت‌های قبل — برای پیش‌بینی، نه برای مقایسه تیم‌ها!","Burndown: نمودار سوختن کار باقی‌مانده در طول اسپرینت"]},{"k":"warn","title":"اسکرام شکلی","t":"ایستادن در جلسه روزانه، اسکرام نیست! ضدالگوها: جلسات طولانی، تغییر هدف وسط اسپرینت، Retro بدون خروجی اجرایی، و Velocity به‌عنوان معیار بهره‌وری فردی. اسکرام بدون شجاعت تغییر، فقط بوروکراسی سریع‌تر است."},{"k":"tip","title":"نکته منتور","t":"اگر تازه شروع کردی، فقط سه چیز را جدی بگیر: بک‌لاگ اولویت‌بندی‌شده و شفاف، اسپرینت کوتاه با هدف مشخص، و رترویی که هر جلسه حداقل یک بهبود واقعی اجرا کند. بقیه جزئیات است."}]'::jsonb, '[{"q":"هدف اصلی جلسه Retrospective چیست؟","opts":["نمایش محصول به مشتری","شناسایی و اجرای بهبود در فرایند کار تیم","برآورد اسپرینت بعد","تقسیم وظایف"],"ans":1,"why":"Review درباره محصول است، Retro درباره فرایند: چه چیزی خوب بود، چه چیزی را تغییر دهیم — و مهم‌تر، اجرای همان تغییر در اسپرینت بعد."},{"q":"Velocity برای چه چیزی مفید است؟","opts":["سنجش بهره‌وری افراد","پیش‌بینی ظرفیت تیم برای برنامه‌ریزی اسپرینت‌های بعد","مقایسه دو تیم","تعیین حقوق"],"ans":1,"why":"Velocity یک دماسنج داخلی است: تیمِ خودت با تاریخچه خودش مقایسه می‌شود تا بداند چقدر کار می‌تواند بردارد. مقایسه بین‌تیمی آن را فاسد می‌کند."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('se-b1', 'se', 'چرخه حیات نرم‌افزار', 63, 7, '[{"k":"p","t":"چرخه حیات، مراحل از ایده تا بازنشستگی است؛ مدل آبشاری ترتیبی و صلب، چابک تکراری و منعطف — انتخاب به قطعیت نیازمندی‌ها وابسته است."},{"k":"h","t":"چرا مدل آبشاری شکست خورد؛ درس تاریخ"},{"k":"p","t":"مدل آبشاری (نیازمندی‌ها → طراحی → کد → تست → تحویل) منطقی به نظر می‌رسید — مثل ساخت پل، که اول نقشه کامل و بعد بتن‌ریزی. ولی نرم‌افزار پل نیست: در ساخت پل، خاک و فیزیک ثابت‌اند؛ در نرم‌افزار، نیازها درست وقتی که محصول را می‌بینی تغییر می‌کنند، چون ذی‌نفعان تا نبینند نمی‌دانند چه می‌خواهند. آبشاری این تغییر را «نقص فرایند» می‌دید و با «مدیریت تغییر» می‌جنگید؛ پروژه‌ها ماه‌ها کد می‌زدند و روز تحویل می‌فهمیدند چیز دیگری لازم بوده. مانیفست چابک (۲۰۰۱) جهت را عوض کرد: به‌جای یک تحویل بزرگ در انتها، تحویل‌های کوچک و واقعیِ هر چند هفته — که هرکدام بازخورد بگیرد و جهت را اصلاح کند. چابکی یعنی پذیرش اینکه «نمی‌دانیم» — و ساختن فرایندی که یاد گرفتن را سریع کند، نه اینکه وانمود کند می‌داند."},{"k":"h","t":"Scrum در عمل؛ سه نقش، پنج مراسم"},{"k":"p","t":"اسکرام ساده‌ترین قاب چابک است: تیم کوچک (۵ تا ۹ نفر) با سه نقش — Product Owner (صاحب «چه چیزی»، اولویت‌بندی Backlog)، Scrum Master (صاحب «چطورِ فرایند»، رفع موانع — نه مدیر تیم!) و توسعه‌دهندگان. و پنج مراسم با زمان‌بندی سفت: Sprint Planning (اول اسپرینت: چه چیزی از Backlog در این دو هفته جا می‌شود)، Daily Standup (۱۵ دقیقه: چه کردم، چه می‌کنم، چه مانعی دارم — گزارش به تیم، نه به مدیر)، Sprint Review (انتهای اسپرینت: دمو محصول واقعی به ذی‌نفعان — نه پاورپوینت) و Retrospective (بهبود خودِ فرایند). قلبش یک اصل است: در پایان هر اسپرینت، یک تکه نرم‌افزار «واقعاً قابل‌تحویل» وجود دارد — بالقوه قابل‌انتشار — و این معیار واقعی پیشرفت است، نه درصدِ تکمیلِ کارها روی کاغذ."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"یک User Story از Backlog تا Done","code":"### User Story (صاحب: Product Owner)\nبه‌عنوان «خریدار» می‌خواهم «درگاه پرداخت آنلاین داشته باشم»\nتا «بدون واریز دستی، لحظه‌ای خرید کنم».\n\n### معیارهای پذیرش (Acceptance Criteria)\n- [ ] پرداخت با کارت شتابی موفق شود و رسید بدهد\n- [ ] پرداخت ناموفق، پیام مشخص و بدون کسر پول بدهد\n- [ ] قطع اتصال وسط پرداخت، سفارش را «در انتظار» نگه دارد\n\n### تعریف انجام (Definition of Done) — برای همه Storyها\n- [ ] کد نوشته و توسط یک نفر دیگر Review شد\n- [ ] تست خودکار نوشتن و همه سبزند\n- [ ] روی محیط Staging دمو شد"},{"k":"def","term":"Definition of Done (تعریف انجام)","t":"چک‌لیست مشترک و صریح تیم برای «یعنی چه که این کار تمام است» — بدون آن، «تمام شد» برای هرکس معنی متفاوتی دارد و کارها نیمه‌تمام انباشته می‌شوند. DoD مال کیفیت است (همه کارها) و معیار پذیرش مال همان یک Story."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["مراحل: نیازمندی، طراحی، پیاده‌سازی، تست، استقرار، نگهداری","آبشاری برای نیازهای ثابت؛ چابک برای نیازهای در حال تغییر","نگهداری معمولاً پرهزینه‌ترین مرحله است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"آبشاری در برابر چابک","code":"آبشاری: نیاز → طراحی → کد → تست → انتشار (یک‌بار)\nچابک:   [نیاز → کد → تست → بازخورد] × تکرار"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: مراحل: نیازمندی، طراحی، پیاده‌سازی، تست، استقرار، نگهداری بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا چابک برای محصول با نیازهای متغیر بهتر است؟","opts":["سریع‌تر کد می‌زند","چون با تکرار کوتاه زود بازخورد می‌گیرد و مسیر را اصلاح می‌کند نه اینکه آخر کار بفهمد اشتباه ساخته","ارزان‌تر همیشه","تست ندارد"],"ans":1,"why":"در چابک هر تکرار یک نسخه قابل‌ارائه است؛ اگر مسیر اشتباه باشد، بعد از چند هفته مشخص می‌شود نه بعد از یک سال."},{"q":"چرا آبشاری در نرم‌افزار خوب جواب نمی‌دهد؟","opts":["کند است","چون نیازها تا دیدن محصول واقعی مشخص نمی‌شوند؛ آبشاری تغییر را استثنا فرض می‌کند ولی در نرم‌افزار، تغییر قاعده است","گران است","قدیمی است"],"ans":1,"why":"ذی‌نفعان تا محصول را نبینند نمی‌دانند چه می‌خواهند — و بازار هم عوض می‌شود. چابکی به‌جای جنگیدن با تغییر، بازخورد زودهنگام را در دل فرایند می‌سازد."},{"q":"مهم‌ترین خروجی پایان هر Sprint چیست؟","opts":["گزارش پیشرفت","یک تکه نرم‌افزار واقعاً قابل‌تحویل و بالقوه قابل‌انتشار — نه برنامه و نه درصد","مستندات","تخمین بعدی"],"ans":1,"why":"درصد تکمیل قابل‌دروغ‌گفتن است؛ نرم‌افزار قابل‌اجرا نه. دمو واقعی به ذی‌نفع، حلقه بازخورد را می‌بندد و «پیشرفت» را اندازه‌پذیر واقعی می‌کند."}]'::jsonb),
('se-b2', 'se', 'مهندسی نیازمندی‌ها', 63, 8, '[{"k":"p","t":"نیازمندی‌های بد، ریشه اکثر شکست‌هاست؛ استخراج با مصاحبه و مشاهده، نوشتن شفاف و تأیید با ذی‌نفع، سه رکن مهندسی نیازمندی‌اند."},{"k":"h","t":"نیازمندی‌ها؛ گران‌ترین اشتباه، ارزان‌ترین اصلاح"},{"k":"p","t":"یک باگ که در مرحله نیازمندی‌ها جا بماند، در طراحی ۱۰ برابر و بعد از انتشار تا ۱۰۰ برابر هزینه دارد — چون هر مرحله بعدی روی آن سوار شده. پس «مهندسی نیازمندی‌ها» یعنی سرمایه‌گذاری روی فهمیدنِ درست، قبل از ساختن. دو نوع را از هم جدا کن: کارکردی (سیستم چه کاری انجام می‌دهد — «کاربر می‌تواند سبد خرید را ببیند») و غیرکارکردی (سیستم چطور انجام می‌دهد — «۹۵٪ درخواست‌ها زیر ۲۰۰ms پاسخ بگیرند»). تازه‌کارها فقط اولی را می‌نویسند؛ ولی اغلب همان دومی‌اند که معماری را شکل می‌دهند و پروژه را شکست می‌دهند: امنیت، مقیاس‌پذیری، دسترس‌پذیری، قابلیت نگهداری. نیازمندی غیرکارکردیِ بدون عدد، نیازمندی نیست — آرزوست."},{"k":"h","t":"از مصاحبه تا User Story؛ هنر بیرون‌کشیدنِ ندانسته‌ها"},{"k":"p","t":"ذی‌نفعان معمولاً نمی‌دانند چه می‌خواهند — یا راه‌حل را جای مسئله می‌گویند («یک فرم اکسل بگذارید»). کار مهندس نیازمندی‌ها، عبور از «درخواست» به «نیاز» است: پنج بار بپرس «چرا؟» تا به ریشه برسی (شاید فرم اکسل لازم نیست و یک گزارش خودکار کافی است). ابزارهای استخراج: مصاحبه با تک‌تک نقش‌ها، مشاهده واقعی کار (نه تعریفش)، و سناریوهای «اگر ... چه؟». خروجی استاندارد، User Story است با قالب سه‌بخشی: نقش («به‌عنوان...»)، خواسته («می‌خواهم...») و ارزش («تا...» — مهم‌ترین بخش که اغلب جا می‌افتد و بدون آن نمی‌شود اولویت‌بندی کرد). و هر Story باید INVEST باشد: مستقل، قابل‌مذاکره، ارزشمند، قابل‌برآورد، کوچک و قابل‌تست — Story‌ای که این‌ها را ندارد، هنوز آماده برنامه‌ریزی نیست."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"از درخواست خام تا Story قابل‌ساخت","code":"درخواست ذی‌نفع:\n«یک دکمه بگذار که ایمیل همه کاربران را بفرستد»\n\nپنج چرا:\n- چرا همه؟ → چون می‌خواهیم از جشنواره خبر بدهیم\n- چرا همه و نه خریداران ماه قبل؟ → ...\n\nUser Storyهای نتیجه:\n۱. به‌عنوان «بازاریاب» می‌خواهم «به بخش خریداران\n   ۳۰ روز اخیر ایمیل بفرستم» تا «جشنواره را به\n   محتمل‌ترین خریداران برسانم»\n   معیار پذیرش: فقط بخش انتخاب‌شده می‌گیرد؛\n   لغو اشتراک در ایمیل هست؛ گزارش ارسال داریم\n\n۲. به‌عنوان «کاربر» می‌خواهم «اشتراک ایمیل را\n   لغو کنم» تا «ایمیل ناخواسته نگیرم»"},{"k":"tip","title":"نکته منتور","t":"هر نیازمندی غیرکارکردی را با عدد بنویس و صاحب بده: «زمان پاسخ ۹۵امک زیر ۲۰۰ms در بار ۱۰۰۰ کاربر همزمان» — قابل‌اندازه‌گیری یعنی قابل‌تست، و قابل‌تست یعنی قابل‌تحقق. «سیستم باید سریع باشد» جمله‌ای است که هیچ‌کس نمی‌تواند برایش مسئولیت بپذیرد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["نیاز عملکردی چه کاری، غیرعملکردی چه کیفیتی (سرعت، امنیت)","User Story: به‌عنوان X می‌خواهم Y تا Z","هر نیاز باید قابل‌آزمون و بدون ابهام باشد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"User Story","code":"به‌عنوان «خریدار»\nمی‌خواهم «سبد خریدم را ذخیره کنم»\nتا «بعداً بدون گشتن دوباره خریدم را کامل کنم»\n\nمعیار پذیرش: بعد از خروج و ورود، سبد همان است."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: نیاز عملکردی چه کاری، غیرعملکردی چه کیفیتی (سرعت، امنیت) بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت نیاز عملکردی و غیرعملکردی چیست؟","opts":["هیچ","عملکردی یک قابلیت را می‌گوید؛ غیرعملکردی کیفیت آن مثل سرعت و امنیت را","اندازه","اولویت"],"ans":1,"why":"«کاربر بتواند جست‌وجو کند» عملکردی است؛ «جست‌وجو زیر ۲۰۰ms جواب بدهد» غیرعملکردی."},{"q":"کدام یک نیازمندی غیرکارکردی است؟","opts":["«کاربر می‌تواند رمز را عوض کند»","«۹۹.۹٪ اوقات سیستم در دسترس باشد» — چگونگی/کیفیت سیستم، نه یک کارکرد","«سبد خرید نمایش داده شود»","«جست‌وجو کار کند»"],"ans":1,"why":"کارکردی می‌گوید سیستم «چه» می‌کند؛ غیرکارکردی «چطور» — سرعت، دسترس‌پذیری، امنیت. این‌ها معمولاً معماری را تعیین می‌کنند و دیر فهمیدن‌شان گران‌ترین اشتباه پروژه است."},{"q":"در قالب User Story، بخش «تا ...» چه نقشی دارد؟","opts":["تزئینی","ارزش و هدف را می‌گوید — بدون آن نمی‌شود اولویت‌بندی کرد و اغلب راه‌حل بهتری جایگزین همان خواسته می‌شود","اجباری نیست","برای تست است"],"ans":1,"why":"اگر بدانیم کاربر «تا» چه هدفی این را می‌خواهد، شاید راه کوتاه‌تری پیدا کنیم؛ و هنگام کم‌آوردن زمان، می‌فهمیم کدام Story ارزشش را دارد. خواسته بدون هدف، قابل‌قضاوت نیست."}]'::jsonb),
('se-b3', 'se', 'UML و دیاگرام کلاس', 63, 9, '[{"k":"p","t":"UML زبان مشترک طراحی است؛ دیاگرام کلاس ساختار را با کلاس‌ها، فیلدها و روابط (وراثت، ترکیب، وابستگی) نشان می‌دهد و پل طراحی به کد است."},{"k":"h","t":"چرا UML هنوز؛ نقشه قبل از سفر"},{"k":"p","t":"UML زبان مشترک تیم برای حرف‌زدن درباره ساختار قبل از نوشتن کد است — مثل نقشه معماری قبل از بتن‌ریزی. ارزشش در سه چیز است: اول، ابهام‌زدایی — جمله‌ای که هرکس یک‌جور می‌فهمد، در دیاگرام یک شکل دارد. دوم، حافظه تیم — دیاگرام کلاس‌ها بعد از شش ماه می‌گوید «چرا این‌طور ساختیم». سوم، و مهم‌تر، وسیله فکرکردن — وقتی مجبور می‌شوی رابطه‌ها را بکشی، ضعف طراحی (مثل کلاسی که ۱۵ وابستگی دارد) قبل از کد خودش را نشان می‌دهد. ولی قانون طلایی: UML سند نیست، گفتگوست — دیاگرامی که بعد از جلسه به‌روز نماند و روی دیوار خاک بخورد، ضرر دارد چون «دروغِ قدیمی» بدتر از «ندانستن» است. دیاگرام‌ها را سبک نگه دار (حتی روی وایت‌برد عکس بگیر) و فقط جایی بکش که واقعاً تصمیمی در کار است."},{"k":"h","t":"دیاگرام کلاس؛ چهار رابطه به ترتیب قدرت"},{"k":"p","t":"دیاگرام کلاس سه‌بخش دارد: نام، صفت‌ها (با نوع و دید) و عملیات‌ها. ولی جانش چهار نوع رابطه است که به ترتیب قدرت باید بشناسی. وابستگی (Dependency — خط‌چین با فلش): «استفاده موقت» — متدی که از کلاس دیگر استفاده می‌کند. انجمن (Association — خط ساده): «ارتباط بلندمدت» — فیلدی از نوع کلاس دیگر (سفارش، مشتری‌اش را می‌شناسد). تجمع (Aggregation — لوزی توخالی): «مالکیت سست» — کلاس از اجزایش استفاده می‌کند ولی آن‌ها بدون او هم معنا دارند (دانشگاه و استاد). ترکیب (Composition — لوزی توپُر): «مالکیت قوی» — جزء بدون کل بی‌معنی است و با آن می‌میرد (سفارش و اقلامش؛ سفارش پاک شود، اقلام هم). و وراثت (فلش توخالی): «هست از جنس». تشخیص درستِ ترکیب در برابر تجمع، مرز طراحی‌کننده دقیق از معمولی است — چون تعیین می‌کند چه کسی مسئول نابودی چیست."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"دیاگرام کلاس یک فروشگاه کوچک","code":"┌─────────────┐        ┌─────────────┐\n│  Customer   │ 1    * │    Order    │\n├─────────────┤◇───────├─────────────┤\n│ -id: long   │  انجمن │ -id: long   │\n│ -name       │(سفارش‌ها)│ -date       │\n│ -email      │        │ -status     │\n├─────────────┤        ├─────────────┤\n│ +getOrders()│        │ +total()    │\n└─────────────┘        └──────┬──────┘\n                              │۱    *  ترکیب\n                              │ (بدون سفارش، قلم بی‌معنی است)\n                       ┌──────┴──────┐\n                       │ OrderItem   │\n                       ├─────────────┤\n                       │ -qty        │\n                       │ -unitPrice  │\n                       └─────────────┘\nOrderItem ◄──── وابستگی ──── Product (کاتالوگ مستقل)"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["رابطه","نماد","معنی","مثال"],"rows":[["وابستگی","خط‌چین + فلش","استفاده موقت","متد از Date استفاده می‌کند"],["انجمن","خط ساده","ارتباط بلندمدت","استاد ↔ دانشجو"],["تجمع","لوزی توخالی","مالکیت سست؛ جزء مستقل","تیم ↔ بازیکن"],["ترکیب","لوزی توپُر","مالکیت قوی؛ مرگ مشترک","سفارش → اقلام"],["وراثت","فلش توخالی","«هست از جنس»","Dog → Animal"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["وراثت با خط و مثلث توخالی، ترکیب با لوزی پر","وابستگی با فلک چین‌دار؛ association با خط ساده","هر رابطه ضربان (cardinality) دارد: ۱، ۰..۱، *"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"دیاگرام کلاس","code":"  ┌──────────┐\n  │  Order   │\n  ├──────────┤\n  │ -id      │      ┌────────┐\n  ├──────────┤ 1   *│ OrderItem\n  │ +total() │◆─────│        │\n  └──────────┘      └────────┘"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: وراثت با خط و مثلث توخالی، ترکیب با لوزی پر بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"ترکیب (composition) چه چیزی را نشان می‌دهد؟","opts":["وراثت","مالکیت قوی که جزء بدون کل معنا ندارد؛ مثل آیتم‌های یک سفارش","وابستگی موقت","اینترفیس"],"ans":1,"why":"در ترکیب اگر Order پاک شود، OrderItemهایش هم بی‌معنا می‌شوند؛ جزء عمرش به کل وابسته است."},{"q":"سفارش و اقلامش (OrderItem) چه رابطه‌ای دارند و چرا؟","opts":["تجمع","ترکیب — چون قلم بدون سفارش بی‌معنی است و با حذف سفارش باید حذف شود؛ مالکیت و طول عمر مشترک","انجمن","وابستگی"],"ans":1,"why":"معیار ترکیب: اگر «کل» نابود شود، «جزء» هم معنا و موجودیتش را از دست می‌دهد. استاد بدون تیم هم استاد است (تجمع) ولی قلم بدون سفارش، داده یتیم است."},{"q":"بزرگ‌ترین سوءاستفاده از UML در تیم‌ها چیست؟","opts":["زیاد کشیدن","تبدیلش به مستندات رسمیِ همیشه‌عقب — دیاگرامی که به‌روز نمی‌ماند، دروغِ قدیمی است و از ندانستن بدتر","کم کشیدن","ابزار گران"],"ans":1,"why":"ارزش UML در گفتگوی هنگام طراحی است نه سند آرشیوی. دیاگرام‌های سنگین و رسمی به‌روز نمی‌مانند و بعداً تیم را به‌اشتباه می‌اندازند؛ سبک و دورریختنی بکش."}]'::jsonb),
('se-b4', 'se', 'دیاگرام Sequence', 63, 10, '[{"k":"p","t":"دیاگرام ترتیبی، تعامل اشیا در طول زمان را نشان می‌دهد؛ هر خط عمودی یک شیء و هر فلک افقی یک پیام — برای طراحی سناریوهای کلیدی."},{"k":"h","t":"Sequence؛ نمایشِ زمان در دنیای بدون زمانِ کلاس‌ها"},{"k":"p","t":"دیاگرام کلاس می‌گوید «چه چیزهایی هست و چطور مرتبط‌اند» — ولی ساکن است؛ زمان و ترتیب را نشان نمی‌دهد. Sequence Diagram بُعد زمان را اضافه می‌کند: هر شیء یک «خط زندگی» عمودی دارد و پیام‌ها فلش‌های افقی‌اند که از یکی به دیگری می‌روند — از بالا (اول) به پایین (بعد). حالا می‌بینی که چه کسی اول صدا می‌شود، کدام فراخوانی همگام است (فلش توپُر، منتظر پاسخ می‌ماند) و کدام ناهمگام (فلش باز، جوابی لازم نیست)، و پاسخ‌ها خط‌چین برمی‌گردند. بزرگ‌ترین کاربردش: طراحی و نقد سناریوهای پیچیده — مثل «پرداخت آنلاین» که بین UI، سرور، درگاه بانکی و دیتابیس می‌پرد. خیلی از باگ‌های معماری (مثل ددلاک‌ها و race conditionها) وقتی روی کاغذ ترتیب را می‌کشی، خودشان را لو می‌دهند — قبل از اینکه ساعت‌ها دیباگ شوند."},{"k":"h","t":"فراتر از فلش‌ها؛ ابزارهای واقعی سناریو"},{"k":"p","t":"سه ابزار که Sequence را از نقاشی به مهندسی می‌برند. Activation Box (مستطیل روی خط زندگی): بازه‌ای که شیء واقعاً «مشغول اجرا» است — وقتی مستطیل‌ها بلند و تو در تو می‌شوند، داری بوی «متد خدای ۵۰۰ خطی» را می‌بینی. Fragmentها: قاب‌هایی که منطق شرطی و تکرار را نشان می‌دهند — alt یعنی «اگر ... / وگرنه»، loop یعنی «به ازای هر ...» و opt یعنی «فقط اگر». و مهم‌تر از همه: کشیدن «مسیر خطا» نه فقط مسیر شاد — Sequence پرداختی که فقط موفقیت را نشان می‌دهد، طراحی نیست؛ قاب alt با شاخه «درگاه خطا داد → جبران → اطلاع کاربر» همان جایی است که معماری واقعی اتفاق می‌افتد. ابزارهای واقعی هم همین را می‌کشند: Mermaid و PlantUML که دیاگرام را از «کد متنی» می‌سازند تا کنار کد در git بماند و به‌روز بماند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"سناریوی پرداخت؛ مسیر شاد و مسیر خطا","code":"User        App         PaymentSvc      Bank\n │  «خرید»   │               │             │\n │──────────>│  createOrder  │             │\n │           │──────────────>│  authorize  │\n │           │               │────────────>│\n │           │               │             │\n │      ┌────┤          alt [موفق]         │\n │      │    │<───── ok ─────┤<────────────┤\n │      │    │  saveReceipt  │             │\n │      │    │───────┐       │             │\n │      │    │<──────┘       │             │\n │      └────┤               │             │\n │      ┌────┤          else [ناموفق]      │\n │      │    │<── declined ──┤<────────────┤\n │      │    │  markPending + retry queue  │\n │      │    │───────┐       │             │\n │      └────┤<──────┘       │             │\n │<─نتیجه────┤               │             │"},{"k":"def","term":"Fragment (قاب کنترل)","t":"قاب‌هایی در Sequence که منطق را نشان می‌دهند: alt (شرطی با چند شاخه)، opt (شرطیِ اختیاری)، loop (تکرار با شرط) و par (اجرای موازی). بدون این‌ها، دیاگرام فقط مسیر شاد را نشان می‌دهد و ارزش مهندسی‌اش نصف می‌شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["lifeline خط عمودی هر شیء","فلک توپر فراخوانی و چین‌دار بازگشت","alt و loop برای شرط و تکرار"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"سناریو خرید","code":"User → Cart:  addItem()\nCart → DB:    save(item)\nDB  --> Cart: ok\nCart --> User: تایید"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: lifeline خط عمودی هر شیء بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"دیاگرام ترتیبی چه چیزی را نشان می‌دهد که دیاگرام کلاس نمی‌دهد؟","opts":["کلاس‌ها","ترتیب زمانی پیام‌ها بین اشیا در یک سناریو","فیلدها","انواع داده"],"ans":1,"why":"دیاگرام کلاس ساختار ایستا است؛ دیاگرام ترتیبی پویایی و زمان‌بندی یک گردش کار را نشان می‌دهد."},{"q":"Sequence Diagram چه چیزی را نشان می‌دهد که Class Diagram نمی‌تواند؟","opts":["صفت‌ها","ترتیب زمانی پیام‌ها بین اشیاء — چه کسی چه موقع چه کسی را صدا می‌زند و چه پاسخی برمی‌گردد","وراثت","نوع داده"],"ans":1,"why":"دیاگرام کلاس ساختار ساکن است؛ Sequence بُعد زمان و ترتیب تعاملات را اضافه می‌کند — برای سناریوهایی مثل پرداخت که بین چند جزء می‌پرد، حیاتی است."},{"q":"فلش توپُر و خط‌چینِ پاسخ، چه چیزی را می‌گویند؟","opts":["تزئین","فراخوانی همگام: فرستنده اجرا را متوقف و منتظر پاسخ می‌ماند؛ پاسخ خط‌چین برمی‌گردد — و زنجیره‌های بلندِ این‌ها نشانه طراحی سفت و سخت است","خطای شبکه","تکرار"],"ans":1,"why":"همگام یعنی «منتظر بمان» — و هر انتظار، یک نقطه توقف. زنجیره‌های عمیق فراخوانی همگام، تأخیرها را جمع می‌کنند؛ طراحی خوب، جاهای ممکن را ناهمگام می‌کند."}]'::jsonb),
('se-b5', 'se', 'اسکرام و اسپرینت', 56, 11, '[{"k":"p","t":"اسکرام چارچوب چابک با اسپرینت‌های زمانی ثابت است؛ سه نقش (مالک محصول، اسکرام مستر، تیم) و چند مراسم برای شفافیت و تطبیق."},{"k":"h","t":"اسپرینت؛ ضربان ثابت تیم"},{"k":"p","t":"اسکرام کار را به بازه‌های زمانی ثابت (معمولاً دو هفته) به نام اسپرینت تقسیم می‌کند که هرکدام یک «افزایش» قابل‌ارائه از محصول تولید می‌کنند. این ریتم ثابت چند کار می‌کند: تمرکز تیم را محدود می‌کند (فقط هدف این اسپرینت)، بازخورد را منظم می‌سازد (هر دو هفته یک خروجی واقعی به ذی‌نفعان نشان می‌دهی) و ریسک را کوچک می‌کند (اگر مسیر اشتباه است، حداکثر دو هفته هدر رفته). در طول اسپرینت، محدوده کار قفل است — چیزی اضافه نمی‌شود مگر با توافق."},{"k":"h","t":"مراسم؛ هرکدام یک دلیل دارد"},{"k":"p","t":"چهار مراسم اصلی، هرکدام یک نیاز را پوشش می‌دهند: برنامه‌ریزی اسپرینت (چه کاری و چطور)، دیلی (هماهنگی روزانه ۱۵ دقیقه‌ای — هرکس چه کرد، چه می‌کند، چه مانعی دارد)، ریویو (نمایش افزایش به ذی‌نفعان و گرفتن بازخورد) و رترو (بهبود خودِ فرایند — چه چیزی خوب بود و چه چیزی باید عوض شود). دیلی جلسه گزارش به مدیر نیست؛ هماهنگی خودِ تیم است. و رترو مهم‌ترین مراسم است چون همان‌جاست که تیم یاد می‌گیرد بهتر کار کند — اگر حذفش کنی، اسکرام به یک چرخه تکراری بی‌جان تبدیل می‌شود."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["مراسم","کی","هدف"],"rows":[["برنامه‌ریزی","شروع اسپرینت","انتخاب و تفکیک کار اسپرینت"],["دیلی","هر روز، ۱۵ دقیقه","هماهنگی و شناسایی موانع"],["ریویو","پایان اسپرینت","نمایش افزایش و گرفتن بازخورد"],["رترو","بعد از ریویو","بهبود فرایند تیم"]]},{"k":"tip","title":"نکته منتور","t":"اگر دیلی‌ها طولانی و خسته‌کننده شده‌اند، یعنی دارد به جلسه حل مسئله تبدیل می‌شود؛ قانون این است: در دیلی فقط موانع اعلام می‌شود، حل‌شان به بعد از جلسه با افراد مربوط موکول می‌شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["اسپرینت ۱ تا ۴ هفته با هدف مشخص","دیلی ۱۵ دقیقه: دیروز چه، امروز چه، مانع چه","اسپرینت ریویو نمایش کار و رترو بهبود فرایند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"مراسم اسکرام","code":"پلنینگ   → هدف و بک‌لاگ اسپرینت\nدیلی      → هماهنگی روزانه ۱۵ دقیقه\nریویو     → نمایش خروجی به ذی‌نفع\nرترو      → بهبود روش کار تیم"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: اسپرینت ۱ تا ۴ هفته با هدف مشخص بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"هدف جلسه رترواسپکتیو چیست؟","opts":["نمایش محصول","بازنگری روش کار تیم و توافق روی بهبودهای کوچک برای اسپرینت بعد","برآورد هزینه","تقسیم وظایف"],"ans":1,"why":"رترو به خود فرایند نگاه می‌کند نه محصول؛ تیم می‌پرسد چه چیزی را بهتر انجام بدهد و یک‌دو بهبود برمی‌دارد."},{"q":"چرا محدوده اسپرینت در طول آن قفل است؟","opts":["چون تیم تنبل است","تا تمرکز حفظ شود و بتوان اعتبار تخمین‌ها را سنجید — تغییر مداوم، اسپرینت را بی‌معنی می‌کند","چون قانون است","چون سخت است"],"ans":1,"why":"اگر وسط اسپرینت مدام کار اضافه شود، هیچ‌وقت نمی‌فهمی تیم واقعاً در دو هفته چقدر کار انجام می‌دهد و برنامه‌ریزی بعدی بی‌پایه می‌شود."},{"q":"هدف اصلی رترو چیست؟","opts":["گزارش به مدیر","شناسایی راه‌های بهبود خودِ فرایند کار تیم","تخمین اسپرینت بعد","نمایش محصول"],"ans":1,"why":"رترو جایی است که تیم درباره «چطور کار می‌کنیم» صحبت می‌کند نه «چه کار کردیم» — و همان بهبودهای کوچک تکرارشونده‌اند که تیم را به‌مرور سریع و کم‌اصطکاک می‌کنند."}]'::jsonb),
('se-b6', 'se', 'بک‌لاگ و اولویت‌بندی', 56, 12, '[{"k":"p","t":"بک‌لاگ لیست زنده همه کارهای محصول است که مالک محصول آن را اولویت‌بندی می‌کند؛ اولویت یعنی بیشترین ارزش با کمترین ریسک، اول."},{"k":"h","t":"بک‌لاگ؛ یک لیست زنده، نه یک قبرستان"},{"k":"p","t":"بک‌لاگ محصول فهرست مرتب‌شده همه چیزهایی است که ممکن است برای محصول انجام شود — ویژگی‌ها، اصلاح‌ها، کارهای فنی. «زنده» یعنی مدام تغییر می‌کند: آیتم‌های جدید می‌آیند، قدیمی‌ها حذف یا بازتعریف می‌شوند و ترتیب مدام بازبینی می‌شود. مالک محصول مسئول این لیست است و تنها کسی است که اولویت نهایی را تعیین می‌کند — نه به این دلیل که دیکتاتور است، بلکه چون باید یک نفر مسئولیت «چه چیزی ارزش ساختن دارد» را یکپارچه نگه دارد."},{"k":"h","t":"اولویت‌بندی؛ ارزش در برابر ریسک"},{"k":"p","t":"اولویت یعنی بیشترین ارزش با کمترین ریسک، اول. چند روش رایج هست: MoSCoW (باید باشد / خوب است باشد / می‌تواند باشد / نخواهد بود) برای شفاف‌کردن انتظارات، و مدل ارزش/تلاش برای یافتن «میوه‌های در دسترس» — کارهایی که ارزش بالا و تلاش کم دارند. یک تله رایج، اولویت‌دادن به کارهای پرزرق‌وبرق ولی کم‌ارزش فقط چون ذی‌نفع قدرتمندی اصرار دارد؛ وظیفه مالک محصول، نه گفتنِ مستدل است — و هر «بله» به یک کار، عملاً «نه» به کار دیگری است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["روش","مبنا","مناسب برای"],"rows":[["MoSCoW","ضرورت (باید/خوب/می‌تواند/نه)","شفاف‌کردن انتظارات با ذی‌نفع"],["ارزش/تلاش","نسبت ارزش به هزینه","یافتن برد‌های سریع"],["WSJF","ارزش تقسیم بر مدت","مقایسه کمی آیتم‌های بزرگ"]]},{"k":"warn","title":"دام رایج","t":"بک‌لاگی که فقط بزرگ می‌شود و هیچ‌وقت پالایش نمی‌شود، اعتماد تیم را از بین می‌برد؛ چون هیچ‌کس باورش نمی‌شود آن لیست واقعاً اجرا می‌شود. پالایش منظم (حذف، ادغام، بازتعریف) به‌اندازه خود اولویت‌بندی مهم است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["بک‌لاگ محصول همه‌چیز؛ بک‌لاگ اسپرینت فقط این دور","اولویت‌بندی با ارزش، ریسک و وابستگی","آیتم‌های بالایی باید ریز و آماده باشند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"بک‌لاگ نمونه","code":"۱. ورود با گوگل        [ارزش بالا، آماده]\n۲. سبد خرید            [ارزش بالا]\n۳. حالت تاریک          [ارزش متوسط]\n۴. گزارش PDF           [ارزش کم، بعداً]"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: بک‌لاگ محصول همه‌چیز؛ بک‌لاگ اسپرینت فقط این دور بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا آیتم‌های بالای بک‌لاگ باید ریز و آماده باشند؟","opts":["برای زیبایی","چون همان‌ها در اسپرینت بعدی انجام می‌شوند و باید بدون ابهام قابل‌تخمین و اجرا باشند","اجباری","برای تست"],"ans":1,"why":"تیم فقط بالای بک‌لاگ را در اسپرینت برمی‌دارد؛ اگر آن آیتم گنگ باشد، اسپرینت با ابهام شروع می‌شود."},{"q":"چرا فقط مالک محصول اولویت نهایی را تعیین می‌کند؟","opts":["چون بالاترین مقام است","چون باید یک نقطه واحد مسئول ارزش محصول باشد وگرنه اولویت‌ها با فشار ذی‌نفعان مختلف ضدونقیض می‌شود","چون تیم وقت ندارد","قانون اسکرام نیست"],"ans":1,"why":"اگر چند نفر همزمان اولویت تعیین کنند، بک‌لاگ به میدان جنگ تبدیل می‌شود؛ تمرکز مسئولیت در یک نقش، تصمیم‌ها را منسجم و پاسخگو نگه می‌دارد."},{"q":"«میوه در دسترس» در اولویت‌بندی چیست؟","opts":["کارهای سخت","کارهایی با ارزش بالا و تلاش کم که زود بازدهی می‌دهند","کارهای فوری","کارهای قدیمی"],"ans":1,"why":"این کارها با حداقل سرمایه‌گذاری بیشترین ارزش را آزاد می‌کنند و برای شروع یک اسپرینت یا جلب اعتماد ذی‌نفعان عالی‌اند — البته نباید فقط همان‌ها ساخته شوند."}]'::jsonb),
('se-b7', 'se', 'تخمین و Velocity', 63, 13, '[{"k":"p","t":"تخمین در اسکرام با امتیاز داستان (Story Point) و نسبی است نه ساعت؛ Velocity میانگین امتیاز تکمیل‌شده در هر اسپرینت و پایه برنامه‌ریزی بعدی است."},{"k":"h","t":"چرا امتیاز نسبی، نه ساعت"},{"k":"p","t":"انسان‌ها در تخمین زمان مطلق (چند ساعت) بدند ولی در مقایسه نسبی (این از آن بزرگ‌تر است) خوب. به همین دلیل در اسکرام از Story Point استفاده می‌شود: یک امتیاز بدون واحد که بزرگی نسبی یک کار را نشان می‌دهد — معمولاً با دنباله فیبوناچی (۱، ۲، ۳، ۵، ۸، ۱۳) تا فاصله بین سایزهای بزرگ بیشتر شود. تخمین نسبی دو مزیت دارد: سریع‌تر است (مقایسه با یک کار مرجع) و بین اعضای تیم قابل‌انتقال‌تر است (سرعت متفاوت آدم‌ها در امتیاز اثر کمتری دارد تا در ساعت)."},{"k":"h","t":"Velocity؛ آینه سرعت واقعی تیم"},{"k":"p","t":"Velocity میانگین امتیازی است که تیم در اسپرینت‌های اخیر واقعاً تمام کرده — نه تخمین زده، بلکه تحویل داده. این عدد پایه برنامه‌ریزی اسپرینت بعدی است: اگر میانگین ۳۰ امتیاز است، نباید ۴۵ برداریم. نکته مهم این است که Velocity فقط برای خودِ همان تیم معنی دارد؛ مقایسه Velocity دو تیم (یا فشار برای بالابردنش) کاملاً بی‌معنی است چون هر تیم معیار امتیازدهی خودش را دارد. Velocity هدف نیست — دماسنج است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"برنامه‌ریزی با Velocity","code":"سرعت ۳ اسپرینت اخیر تیم:\n  اسپرینت ۱۰: ۲۸ امتیاز\n  اسپرینت ۱۱: ۳۲ امتیاز\n  اسپرینت ۱۲: ۳۰ امتیاز\n  → Velocity ≈ ۳۰\n\nبرای اسپرینت ۱۳:\n  ظرفیت ≈ ۳۰ امتیاز\n  آیتم‌های انتخابی: ۸ + ۵ + ۵ + ۳ + ۸ = ۲۹ ✓\n  (یک آیتم کوچک هم برای ریسک جا گذاشته شد)"},{"k":"tip","title":"نکته منتور","t":"در جلسه تخمین، از Planning Poker استفاده کن: هرکس مخفیانه امتیاز می‌دهد و همه همزمان رو می‌کنند. اگر اختلاف زیاد بود (مثلاً ۳ و ۱۳)، یعنی دو نفر دو چیز متفاوت از کار فهمیده‌اند — همان گفت‌وگو ارزشمندترین بخش جلسه است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["Story Point سختی نسبی است نه زمان","Planning Poker برای هم‌فهمی تیم","Velocity میانگین چند اسپرینت اخیر، نه بهترین"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"Planning Poker","code":"آیتم: «ورود با گوگل»\nتیم: ۳ ، ۳ ، ۵ ، ۳ ، ۸\n→ بحث روی ۸ و ۳ → توافق: ۵"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: Story Point سختی نسبی است نه زمان بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا Story Point نسبی بهتر از تخمین ساعتی است؟","opts":["ساده‌تر","چون انسان در مقایسه نسبی دقیق‌تر از برآورد مطلق زمان است و وابستگی به فرد کم می‌شود","دقیق‌تر همیشه","اجباری"],"ans":1,"why":"گفتن «این دو برابر آن یکی سخت است» راحت‌تر و پایدارتر از «این ۶ ساعت می‌برد» است که برای هر کس فرق دارد."},{"q":"چرا تخمین نسبی از تخمین زمانی دقیق‌تر است؟","opts":["چون سریع‌تر است و خطای ادراک زمان را حذف می‌کند — مقایسه برای مغز ساده‌تر از عدد مطلق است","چون قانون است","چون ساعت واحد ندارد","دقیق‌تر نیست"],"ans":0,"why":"مغز انسان در مقایسه (این بزرگ‌تر از آن) خیلی قابل‌اتکاتر از برآورد مطلق (این ۷ ساعت است) عمل می‌کند؛ پس خطای تخمین با روش نسبی کمتر می‌شود."},{"q":"چرا مقایسه Velocity دو تیم بی‌معنی است؟","opts":["چون تیم‌ها متفاوت‌اند و هرکدام مقیاس امتیاز خودش را دارد — Velocity فقط درون یک تیم و در طول زمان معنی دارد","چون محرمانه است","چون یکسان است","معنی دارد"],"ans":0,"why":"یک تیم ممکن است کار ۸ امتیازی را کاری بداند که تیم دیگر ۳ می‌دهد؛ پس عدد مطلق قابل‌مقایسه نیست. Velocity فقط روندِ خودِ تیم را نشان می‌دهد."}]'::jsonb),
('se-b8', 'se', 'تعریف آماده و انجام', 56, 14, '[{"k":"p","t":"Definition of Ready شرط ورود یک آیتم به اسپرینت و Definition of Done شرط تکمیل آن است؛ این دو قرارداد، ابهام «تمام شد» را حذف می‌کنند."},{"k":"h","t":"Definition of Ready؛ درِ ورود اسپرینت"},{"k":"p","t":"DoR چک‌لیستی است که می‌گوید یک آیتم چه شرایطی داشته باشد که «آماده» برنامه‌ریزی در اسپرینت باشد: داستان واضح و قابل‌فهم است، معیار پذیرش دارد، وابستگی‌هایش حل شده، و آن‌قدر کوچک است که در یک اسپرینت جا شود. هدف DoR این نیست که همه‌چیز از قبل مشخص باشد (این می‌شود آبشار)، بلکه این است که تیم با ابهامِ فلج‌کننده وارد اسپرینت نشود. یک آیتم بدون DoR معمولاً وسط اسپرینت منفجر می‌شود و کل برنامه را به‌هم می‌ریزد."},{"k":"h","t":"Definition of Done؛ درِ خروج، و ضامن کیفیت"},{"k":"p","t":"DoD چک‌لیست مشترکی است که می‌گوید «تمام شد» یعنی چه: کد نوشته و ریویو شده، تست‌ها پاس شده، مستند شده، و (در صورت لزوم) دیپلوی شده. مهم‌ترین کارکرد DoD این است که «تمام» را از یک ادعای شخصی به یک استاندارد تیمی تبدیل می‌کند — وقتی می‌گوییم این کار Done است، همه دقیقاً می‌دانند پشتش چه اتفاقاتی افتاده. بدون DoD، هرکس «تمام» را به سلیقه خودش تفسیر می‌کند و انبوهی از کارهای «۹۰٪ تمام» ساخته می‌شود که هیچ‌وقت به ۱۰۰٪ نمی‌رسند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","Definition of Ready","Definition of Done"],"rows":[["کی","قبل از ورود به اسپرینت","برای اعلام تکمیل"],["سوال","آیا می‌توانیم شروع کنیم؟","آیا واقعاً تمام شد؟"],["مثال","معیار پذیرش دارد، وابستگی حل شده","تست پاس، کد ریویو، دیپلوی"]]},{"k":"warn","title":"دام رایج","t":"DoD را با «معیار پذیرش» اشتباه نگیر: معیار پذیرش برای هر داستان خاص است (این داستان چه باید بکند) ولی DoD برای همه آیتم‌ها یکی است (هر کاری که تمام می‌شود چه کیفیتی دارد). یکی شرطِ «چه» و دیگری شرطِ «چطور» است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["DoR: شفاف، کوچک، تخمین‌خورده، مستقل","DoD: کد زده، تست‌شده، ریویوشده، مستقرشده","DoD برای کل تیم مشترک و یکسان است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"Definition of Done","code":"□ کد نوشته شد\n□ تست واحد پاس شد\n□ Code Review تایید شد\n□ روی staging مستقر شد\n□ مستند به‌روز شد"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: DoR: شفاف، کوچک، تخمین‌خورده، مستقل بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"اگر آیتمی کدش زده ولی تست نشده، «تمام» است؟","opts":["بله","خیر — چون با Definition of Done تیم که شامل تست است، تطبیق ندارد","بستگی دارد","تقریباً"],"ans":1,"why":"DoD یک قرارداد صریح است؛ تا همه مواردش تیک نخورد، آیتم «در حال انجام» می‌ماند حتی اگر کدش کامل به نظر برسد."},{"q":"مهم‌ترین فایده Definition of Done چیست؟","opts":["کار را سریع می‌کند","«تمام شد» را از تفسیر شخصی به استاندارد شفاف تیمی تبدیل می‌کند","مستندات را کم می‌کند","جلسات را کوتاه می‌کند"],"ans":1,"why":"وقتی DoD مشترک باشد، جمله «این کار تمام شد» برای همه یک معنی دارد و دیگر انبوه کارهای نیمه‌تمامِ «تقریباً آماده» ساخته نمی‌شود."},{"q":"چرا DoR نباید خیلی سخت‌گیرانه باشد؟","opts":["چون وقت می‌گیرد","چون آن‌وقت به برنامه‌ریزی آبشاری برمی‌گردیم؛ هدف فقط رفع ابهامِ فلج‌کننده است نه مشخص‌کردن همه‌چیز","چون قانون نیست","چون تیم می‌ترسد"],"ans":1,"why":"اگر بخواهی همه جزئیات قبل از اسپرینت مشخص شود، عملاً به مدل آبشار برگشته‌ای؛ DoR فقط باید آن‌قدر باشد که تیم بتواند با اطمینان شروع کند."}]'::jsonb),
('se-b9', 'se', 'کد ریویو و کیفیت تیمی', 56, 15, '[{"k":"p","t":"کد ریویو هم باگ می‌گیرد هم دانش پخش می‌کند؛ ریویوی خوب روی منطق و طراحی تمرکز دارد نه وسواس سینتکسی، و با احترام و مشخص نوشته می‌شود."},{"k":"h","t":"کد ریویو؛ دو پرنده با یک تیر"},{"k":"p","t":"کد ریویو همزمان دو کار می‌کند که هیچ ابزار دیگری نمی‌کند: باگ و مشکل طراحی را قبل از ورود به شاخه اصلی می‌گیرد، و دانش را در تیم پخش می‌کند. وقتی چند نفر کد همدیگر را می‌خوانند، «تعداد اتوبوس» تیم بالا می‌رود — یعنی اگر کسی نبود، بقیه آن بخش را می‌شناسند. ریویو همچنین استانداردهای مشترک می‌سازد: وقتی می‌بینی همه چطور می‌نویسند، خودت هم هم‌سطح می‌شوی. تیمی که ریویو را جدی بگیرد، کیفیت کدش بدون هیچ جلسه آموزشی‌ای به‌مرور بالا می‌رود."},{"k":"h","t":"ریویوی خوب روی چه چیزی تمرکز دارد"},{"k":"p","t":"انرژی ریویو باید صرف چیزهایی شود که ابزار نمی‌تواند بگیرد: درستی منطق، مناسب‌بودن طراحی، خوانایی برای نفر بعدی، و پوشش تست. وسواس روی سینتکس و فاصله و نام‌گذاری کوچک را باید به linter و formatter خودکار سپرد — حیف است وقت انسان صرف چیزی شود که ماشین می‌تواند. لحن هم مهم است: نظر را به کد بده نه به نویسنده («این تابع سخت خوانده می‌شود» نه «تو بد نوشتی») و پیشنهاد بده نه فقط ایراد. ریویو باید جایی باشد که نویسنده از آن چیزی یاد بگیرد، نه جایی که احساس محاکمه کند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["در ریویو بررسی کن","به ابزار بسپار"],"rows":[["درستی منطق و شرایط مرزی","فاصله و فرمت (formatter)"],["طراحی و مسئولیت‌ها","سبک سینتکس (linter)"],["پوشش تست","غلط‌های ساده (type checker)"],["امنیت و ورودی‌ها","—"]]},{"k":"tip","title":"نکته منتور","t":"اگر یک PR بزرگ‌تر از ~۴۰۰ خط شد، ریویوی باکیفیت تقریباً غیرممکن است — ریویوکننده خسته می‌شود و فقط چشم می‌دواند. نویسنده‌های حرفه‌ای کار را به PRهای کوچک و مستقل می‌شکنند تا هرکدام واقعاً خوانده شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["قبل از ریویو، خودت diff را بخوان و تست را پاس کن","نظرها مشخص و پیشنهاددار باشند نه کلی","سینتکس را به linter بسپار نه انسان"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"یک نظر ریویوی خوب","code":"بد:  «اینجا اشکال دارد»\nخوب: «اگر items خالی باشد، .get(0) خطا می‌دهد؛\n      پیشنهاد می‌کنم اول isEmpty چک شود یا\n      از firstOrNull استفاده کنیم.»"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: قبل از ریویو، خودت diff را بخوان و تست را پاس کن بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"کد ریویو غیر از پیدا کردن باگ چه فایده‌ای دارد؟","opts":["هیچ","انتقال دانش بین اعضا، یکدست‌کردن سبک و بالا بردن کیفیت جمعی کد","سرعت را کم می‌کند","فقط برای تازه‌کارها"],"ans":1,"why":"هر ریویو یک جلسه آموزشی کوتاه است؛ دانش از نویسنده به بقیه منتقل و استاندارد تیم بلند می‌رود."},{"q":"چرا بررسی فاصله و فرمت را نباید در ریویوی انسانی انجام داد؟","opts":["چون مهم نیست","چون formatter و linter آن را خودکار و بدون خطا انجام می‌دهند — وقت انسان باید صرف منطق و طراحی شود","چون سخت است","چون قانون نیست"],"ans":1,"why":"این بررسی‌ها کاملاً ماشینی‌اند و انسان فقط وقتش را روی چیزهایی تلف می‌کند که ابزار بهتر انجام می‌دهد؛ بحث انسانی باید جایی باشد که قضاوت لازم است."},{"q":"چرا PRهای کوچک ریویوی بهتری دارند؟","opts":["چون سریع‌ترند","چون ذهن ریویوکننده روی مقدار کم تغییر می‌تواند واقعاً تمرکز کند — در PR بزرگ فقط چشم‌دوانی می‌شود","چون زیباترند","چون قانون است"],"ans":1,"why":"تمرکز انسان محدود است؛ تحقیق‌ها نشان می‌دهد بعد از چندصد خط، نرخ کشف نقص به‌شدت افت می‌کند. PR کوچک یعنی هر خط واقعاً خوانده می‌شود."}]'::jsonb),
('se-b10', 'se', 'بدهی فنی', 56, 16, '[{"k":"p","t":"بدهی فنی یعنی انتخاب راه سریع‌تر امروز به قیمت اصلاح گران‌تر فردا؛ مقدارش بد نیست اگر آگاهانه باشد و برنامه بازپرداخت داشته باشد."},{"k":"h","t":"بدهی فنی؛ وامِ آگاهانه یا ورشکستگی پنهان"},{"k":"p","t":"بدهی فنی یعنی امروز راه سریع‌تر ولی کثیف‌تر را انتخاب کنی تا زودتر تحویل بدهی — و بعداً باید با بهره (زمان اصلاح بیشتر) پس بدهی. خودِ بدهی فنی بد نیست؛ مثل وام گرفتن برای فرصت بازار است. مشکل وقتی است که ناآگاهانه و بی‌برنامه باشد: کپی‌پیست، بدون تست، سخت‌کدکردن — این‌ها وام‌هایی‌اند که هیچ‌کس ثبت نکرده و هیچ‌کس قصد پس‌دادن ندارد. تیم‌های بالغ بدهی فنی را می‌شناسند، ثبتش می‌کنند و برایش بودجه می‌گذارند؛ تیم‌های نابالغ وانمود می‌کنند وجود ندارد تا روزی زیر آوارش بمانند."},{"k":"h","t":"چهار نوع بدهی؛ همه‌شان یکسان نیستند"},{"k":"p","t":"یک تفکیک مفید: بدهی «عامدانه و محتاط» (می‌دانیم کثیف است، برای ددلاین قبول کردیم، برنامه پس‌دادن داریم — سالم‌ترین نوع)، «عامدانه و بی‌مبالات» (می‌دانیم ولی اهمیت نمی‌دهیم — خطرناک)، «ناخواسته و محتاط» (حالا می‌فهمیم که می‌شد بهتر نوشت — طبیعیِ یادگیری) و «ناخواسته و بی‌مبالات» (چون نمی‌دانستیم بهتر چطور است — یعنی تیم نیاز به آموزش دارد). این ماتریس نشان می‌دهد که راه‌حل هر بدهی متفاوت است: یکی بودجه می‌خواهد، یکی فرهنگ، یکی آموزش."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","محتاط","بی‌مبالات"],"rows":[["عامدانه","وام برنامه‌ریزی‌شده (سالم)","«فعلاً ولش کن» (خطرناک)"],["ناخواسته","یادگیری — حالا بهتر می‌دانیم","نبود دانش — نیاز به آموزش"]]},{"k":"tip","title":"نکته منتور","t":"بدهی فنی را مثل باگ در بک‌لاگ ثبت کن و به هر اسپرینت سهم ثابتی بده (مثلاً ۲۰٪)؛ اگر صبر کنی تا «وقت آزاد شود»، هیچ‌وقت نمی‌شود و بهره مرکب، در نهایت سرعت تیم را نصف می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["بدهی آگاهانه (تحویل سریع) و ناآگاهانه (بی‌دقتی)","مثل بدهی مالی، بهره دارد: هر تغییر بعدی کندتر می‌شود","زمانی برای refactor در هر اسپرینت نگه دار"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"نشانه‌های بدهی","code":"- تغییر کوچک، چند جا را می‌شکند\n- تست‌ها کند یا ناپایدارند\n- کسی جرات دست‌زدن به یک ماژول را ندارد\n- کپی‌پیست منطق در چند فایل"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: بدهی آگاهانه (تحویل سریع) و ناآگاهانه (بی‌دقتی) بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"کی بدهی فنی قابل‌توجیه است؟","opts":["هیچ‌وقت","وقتی آگاهانه برای یک فرصت زمانی گرفته شود و برنامه بازپرداختش هم باشد","همیشه","وقتی وقت نیست"],"ans":1,"why":"بدهی فنی مثل وام است؛ برای رسیدن زودتر به بازار منطقی است، به‌شرط اینکه بدانی باید با بهره برگردانی."},{"q":"کدام نوع بدهی فنی سالم‌ترین است؟","opts":["ناخواسته و بی‌مبالات","عامدانه و محتاط — آگاهانه، برای دلیل موجه، با برنامه بازپرداخت","همه بدند","عامدانه و بی‌مبالات"],"ans":1,"why":"مثل وامِ با برنامه است: می‌دانید چقدر است، چرا گرفتی و کی پس می‌دهی. خطر اصلی بدهی فنی ناآگاه و بی‌برنامه بودنش است، نه خودِ سریع‌رفتن."},{"q":"چرا بی‌توجهی به بدهی فنی در بلندمدت سرعت را کم می‌کند؟","opts":["چون کد زیاد می‌شود","چون با انباشتن، هر تغییر بعدی سخت‌تر و پرریسک‌تر می‌شود — بهره مرکبِ اصلاح، در نهایت تیم را کند می‌کند","چون سرور کند می‌شود","کند نمی‌کند"],"ans":1,"why":"هر بدهی پس‌داده‌نشده، تغییر بعدی را کمی سخت‌تر می‌کند؛ این سختی‌ها جمع می‌شوند تا جایی که اضافه‌کردن کوچک‌ترین فیچر هم به یک عمل جراحی پرریسک تبدیل می‌شود."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('se-b11', 'se', 'مستندسازی و ADR', 63, 17, '[{"k":"p","t":"مستند خوب کمتر ولی به‌جا است؛ ADR تصمیم‌های معماری را با زمینه و پیامد ثبت می‌کند تا بعداً معلوم باشد چرا این راه انتخاب شد."},{"k":"h","t":"مستندِ کمتر ولی به‌جا"},{"k":"p","t":"مستندات خوب با حجمش سنجیده نمی‌شود؛ مستندی که به‌روز نیست بدتر از نبودن است چون گمراه می‌کند. قاعده عملی: کد را طوری بنویس که خوانا باشد (نام‌گذاری خوب، توابع کوچک) تا نیاز به توضیح کم شود؛ بعد فقط چیزهایی را مستند کن که از خودِ کد برنمی‌آید — «چرا»ی تصمیم‌ها، قراردادها، و معماری کلی. و مستند را نزدیک کد نگه دار (در ریپازیتوری) تا با آن تغییر کند؛ مستندی که در یک ویکی دورافتاده زندگی می‌کند، محکوم به کهنگی است."},{"k":"h","t":"ADR؛ ثبت «چرا»ی تصمیم‌های معماری"},{"k":"p","t":"کد نشان می‌دهد «چه» ساختیم ولی نه «چرا» این راه را انتخاب کردیم. ADR (سند تصمیم معماری) یک فایل کوتاه است با چهار بخش: زمینه (مسئله چه بود)، تصمیم (چه انتخاب کردیم)، گزینه‌های ردشده (چه چیزهایی را در نظر گرفتیم و چرا نه) و پیامدها (چه هزینه‌ای پذیرفتیم). وقتی شش ماه بعد کسی بپرسد «چرا از X استفاده کردیم؟»، جواب در یک ADR است نه در ذهن کسی که شاید رفته باشد. ADRها تغییرناپذیرند — اگر تصمیم عوض شد، ADR جدیدی می‌نویسی که قبلی را باطل می‌کند، پس تاریخچه تفکر تیم حفظ می‌شود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"یک ADR نمونه","code":"# ADR-0007: انتخاب PostgreSQL به‌جای MongoDB\n\n## زمینه\nداده‌های سفارش رابطه‌های پیچیده دارند و تراکنش\nچندجدولی نیاز است.\n\n## تصمیم\nاز PostgreSQL استفاده می‌کنیم.\n\n## گزینه‌های ردشده\n- MongoDB: مدل سند برای داده رابطه‌ای ما مناسب نبود\n  و JOIN نداشت.\n\n## پیامدها\n+ تراکنش ACID و JOIN قوی\n- مقیاس‌افقی سخت‌تر از Mongo (فعلاً مهم نیست)"},{"k":"tip","title":"نکته منتور","t":"وقتی یک تصمیم معماری می‌گیری، همان لحظه ADR را بنویس — پنج دقیقه بعد از تصمیم، همه «چرا»ها در ذهنت زنده‌اند؛ فردا نیمی‌شان فراموش شده‌اند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["README: چیست، چطور اجرا، چطور تست","ADR: عنوان، وضعیت، زمینه، تصمیم، پیامد","کد تمیز و نام خوب، بخشی از مستندات است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"ساختار ADR","code":"ADR-007: استفاده از PostgreSQL\nوضعیت: پذیرفته\nزمینه: نیاز به تراکنش ACID و query پیچیده\nتصمیم: PostgreSQL به‌جای MongoDB\nپیامد: تیم باید SQL بداند؛ migration با Flyway"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: README: چیست، چطور اجرا، چطور تست بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"ADR چه سوالی را جواب می‌دهد که کد نمی‌تواند؟","opts":["چگونه","چرا — چرا این تصمیم در آن شرایط گرفته شد و چه گزینه‌هایی رد شد","چه کسی","کی"],"ans":1,"why":"کد نشان می‌دهد چه چیزی ساخته شد؛ ADR ثبت می‌کند چرا این راه و نه راه دیگر، تا تصمیم دوباره بی‌دلیل باز نشود."},{"q":"چرا «چرا»ی تصمیم‌ها مهم‌ترین چیز برای مستندکردن است؟","opts":["چون طولانی است","چون از خود کد برنمی‌آید — کد فقط نشان می‌دهد چه ساختیم، نه چرا این راه و نه راه دیگر","چون قانون است","مهم نیست"],"ans":1,"why":"هر خواننده باهوش می‌تواند بفهمد کد چه می‌کند؛ ولی بدون ثبت «چرا»، نفر بعدی ممکن است همان مشکلی را دوباره حل کند که تو قبلاً حل کرده‌ای — یا بدتر، یک راه‌حل ظاهراً بهتر که قبلاً رد شده را دوباره انتخاب کند."},{"q":"چرا ADRها تغییرناپذیر نگه داشته می‌شوند؟","opts":["چون سخت است","تا تاریخچه تفکر تیم حفظ شود — تصمیم جدید، ADR جدیدی است که قبلی را باطل می‌کند نه اینکه آن را بازنویسی کند","چون قانون است","تغییر می‌کنند"],"ans":1,"why":"اگر ADR را بازنویسی کنی، معلوم نمی‌شود قبلاً چه تصمیمی داشتیم و چرا عوض شد؛ با ابطال‌کردن، سیر تکامل فکر تیم قابل‌ردیابی می‌ماند."}]'::jsonb),
('se-b12', 'se', 'انتشار و Rollback', 63, 18, '[{"k":"p","t":"انتشار امن یعنی بتوانی سریع و مطمئن نسخه جدید را ببری و اگر مشکل بود برگردی؛ نسخه‌بندی معنایی و تگ‌ها این قابلیت را می‌سازند."},{"k":"h","t":"انتشار امن؛ مهم‌تر از انتشار سریع"},{"k":"p","t":"هدف از نسخه‌بندی و تگ‌گذاری این است که هر لحظه بدانی دقیقاً چه چیزی در تولید است و بتوانی به هر نقطه قبلی برگردی. نسخه‌بندی معنایی (SemVer) با سه عدد MAJOR.MINOR.PATCH این زبان مشترک را می‌سازد: تغییرات شکننده عدد اول را بالا می‌برند، ویژگی‌های جدید عدد دوم و اصلاح‌ها عدد سوم را. وقتی هر انتشار یک تگ git (مثل v2.3.1) دارد، «برگرد به نسخه سالم» یک فرمان است نه یک پروژه باستان‌شناسی. تیمی که نتواند در پنج دقیقه به نسخه قبل برگردد، در واقع هیچ نسخه امنی ندارد."},{"k":"h","t":"Rollback؛ دکمه‌ای که امیدوارم لازم نشود"},{"k":"p","t":"Rollback یعنی برگرداندن تولید به نسخه قبلی که می‌دانیم سالم است — و باید آن‌قدر ساده باشد که در نیمه‌شب با ذهن خسته هم اجرا شود. این کار چند پیش‌نیاز دارد: دیتابیس تغییرناپذیر یا سازگار با هر دو نسخه (اگر migration ستونی را پاک کرده، نسخه قدیم با آن کار نمی‌کند)، نسخه‌های قبلی image که هنوز در دسترس‌اند، و فرایندی که تمرین شده باشد. قاعده طلایی: migrationهای دیتابیس را طوری بنویس که با دو نسخه کد سازگار باشند (اول ستون جدید اضافه، بعداً در انتشار جدا، قدیمی پاک شود) تا Rollback همیشه ممکن بماند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"تگ‌گذاری و بازگشت","code":"# علامت‌گذاری نسخه منتشرشده\ngit tag -a v2.3.1 -m ''انتشار ۲.۳.۱''\ngit push --tags\n\n# لیست نسخه‌ها\ngit tag --sort=-creatordate\n\n# اگر تولید خراب شد: برگرد به آخرین نسخه سالم\ngit checkout v2.3.0\ngit switch -c hotfix/rollback-2.3.0\n# ... بیلد و دیپلوی این شاخه ..."},{"k":"warn","title":"دام رایج","t":"هرگز migration دیتابیس را با پاک‌کردن فوری ستون همراه نکن؛ اول ستون جدید را اضافه کن و کد جدید را منتشر کن، و فقط در یک انتشارِ بعدی (وقتی مطمئن شدی نسخه قدیم دیگر اجرا نمی‌شود) ستون قدیمی را پاک کن — وگرنه Rollback غیرممکن می‌شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["SemVer: major.minor.patch — هرکدام معنای خودش","تگ هر release در git نقطه بازگشت است","انتشار کوچک و مکرر کم‌ریسک‌تر از بزرگ و نادر است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"release.sh","code":"git tag v1.4.2 && git push --tags\n# v1.4.2 → تغییر سازگار و رفع باگ\n# اگر v2.0.0 مشکل داشت:\ngit checkout v1.4.2   # بازگشت امن"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: SemVer: major.minor.patch — هرکدام معنای خودش بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا انتشارهای کوچک و مکرر کم‌ریسک‌ترند؟","opts":["سرعت بیشتر","چون هر انتشار تغییر کمتری دارد؛ اگر مشکلی باشد، ریشه‌یابی و بازگشت ساده و محدوده آسیب کوچک است","اجباری","تست کمتر"],"ans":1,"why":"اگر هفته‌ای یک تغییر کوچک ببری و خراب شود، می‌دانی همان تغییر است؛ اگر سه‌ماه یک‌بار ۵۰۰ تغییر ببری، پیدا کردن مقصر ممکن نیست."},{"q":"در نسخه‌بندی معنایی، چه زمانی عدد MAJOR بالا می‌رود؟","opts":["با هر تغییر","وقتی تغییری ناسازگار با نسخه‌های قبل (breaking change) وارد می‌شود","وقتی باگ رفع می‌شود","تصادفی"],"ans":1,"why":"MAJOR یعنی مصرف‌کننده‌ها ممکن است بدون تغییر کدشان، با نسخه جدید به مشکل بخورند؛ MINOR برای افزودن سازگار و PATCH فقط برای اصلاح‌های داخلی است."},{"q":"چرا سازگاری migration با دو نسخه برای Rollback حیاتی است؟","opts":["چون migration سخت است","چون اگر migration ساختار را به شکل ناسازگار عوض کرده باشد، نسخه قبلی کد دیگر با دیتابیس کار نمی‌کند و بازگشت غیرممکن می‌شود","چون قانون است","مهم نیست"],"ans":1,"why":"Rollback فقط کد را برمی‌گرداند؛ اگر دیتابیس در این فاصله به شکلی عوض شده که نسخه قدیم نمی‌فهمد (مثلاً ستونی پاک شده)، برگشتن کد فایده‌ای ندارد."}]'::jsonb),
('react-r1', 'react', 'کامپوننت و ذهنیت اعلانی React', 55, 1, '[{"k":"p","t":"بزرگ‌ترین مانع یادگیری React سینتکس نیست، «عادت» است: ما سال‌ها یاد گرفته‌ایم به DOM بگوییم «این کار را بکن». React می‌گوید این کار را فراموش کن؛ تو فقط توصیف کن صفحه در این وضعیت چه شکلی است، بقیه‌اش با اوست. این تغییر از «دستوری» به «اعلانی»، کل داستان است."},{"k":"h","t":"کامپوننت یعنی تابعی از داده به ظاهر"},{"k":"p","t":"یک کامپوننت React در ساده‌ترین شکل، تابعی است که props می‌گیرد و JSX برمی‌گرداند؛ یعنی یک نگاشت خالص از «داده» به «توصیف ظاهر». چون یک تابع خالص است، با همان ورودی همیشه همان خروجی را می‌دهد و این قابل‌پیش‌بینی‌بودن، تست‌کردن و ترکیب‌کردن را ممکن می‌کند. کامپوننت‌ها مثل لگو روی هم سوار می‌شوند: کامپوننت‌های کوچک و مستقل، بلوک‌های سازنده‌ی صفحات پیچیده‌اند."},{"k":"h","t":"JSX؛ ظاهر در لباس جاوااسکریپت"},{"k":"p","t":"JSX یعنی نوشتن ساختار صفحه داخل جاوااسکریپت؛ ولی زیر پوسته، هر تگ یک فراخوانی تابع است که یک «شیء توصیف‌گر» می‌سازد — نه خودِ عنصر DOM. به همین دلیل می‌توانی داخلش از همه قدرت جاوااسکریپت استفاده کنی: متغیر، شرط، حلقه و تابع. چند قاعده مهم دارد: یک ریشه واحد (یا Fragment)، className به‌جای class، و بسته‌بودن همه تگ‌ها."},{"k":"h","t":"رندر یعنی بازتولید توصیف، نه تغییر مستقیم"},{"k":"p","t":"وقتی وضعیت عوض می‌شود، React کامپوننت را دوباره صدا می‌زند و توصیف جدیدی می‌گیرد؛ بعد توصیف جدید را با قبلی مقایسه (diff) و فقط تفاوت‌ها را روی DOM واقعی اعمال می‌کند. پس «رندر شدن» یک کامپوننت به‌معنی ساخته‌شدن دوباره‌اش در DOM نیست؛ فقط یعنی تابعش دوباره اجرا شده تا ببینیم آیا چیزی عوض شده یا نه. این مدل ذهنی، پایه فهم بهینه‌سازی‌های بعدی است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"tsx","title":"Card.tsx","code":"type Course = { title: string; hours: number };\n\nfunction CourseCard({ title, hours }: Course) {\n  return (\n    <div className=\"card\">\n      <h3>{title}</h3>\n      <span>{hours} ساعت</span>\n    </div>\n  );\n}\n\nfunction CourseList({ courses }: { courses: Course[] }) {\n  return (\n    <section>\n      {courses.length === 0\n        ? <p>دوره‌ای نیست</p>\n        : courses.map(c => <CourseCard key={c.title} {...c} />)}\n    </section>\n  );\n}"},{"k":"list","items":["CourseCard یک تابع خالص است: از روی title و hours، یک توصیف برمی‌گرداند؛ هیچ‌جا مستقیم چیزی را تغییر نمی‌دهد.","در JSX، {hours} یعنی «مقدار این متغیر را اینجا بگذار»؛ این همان جایی است که جاوااسکریپت و ظاهر به هم می‌رسند.","برای لیست از map استفاده می‌شود و key به React می‌گوید کدام عنصر کدام است؛ بدون key، تطبیق تغییرات ناکارآمد و گاهی اشتباه می‌شود."]},{"k":"def","term":"رندر اعلانی","t":"به‌جای اینکه مرحله‌به‌مرحله بگویی DOM را چطور تغییر دهد، توصیف می‌کنی که «با این داده، صفحه چه شکلی است» و کتابخانه تفاوت را اعمال می‌کند. مزیتش این است که هیچ حالت میانه‌ای از قلم نمی‌افتد؛ صفحه همیشه بازتاب دقیق وضعیت فعلی است."},{"k":"table","head":["رویکرد","نحوه کار","مشکل اصلی"],"rows":[["دستوری (jQuery)","خودت DOM را پیدا و تغییر می‌دهی","حالت‌های میانه و ناسازگاری"],["اعلانی (React)","توصیف می‌کنی؛ React diff می‌کند","همیشه با وضعیت هماهنگ"]]},{"k":"warn","title":"دام رایج","t":"ندادن key به عناصر لیست یا استفاده از ایندکس آرایه به‌عنوان key وقتی لیست تغییر می‌کند؛ این باعث می‌شود React عناصر را اشتباه تطبیق دهد و وضعیتِ کامپوننت‌ها جابه‌جا شود. key باید یک شناسه پایدار از خود داده باشد."},{"k":"tip","title":"نکته حرفه‌ای","t":"کامپوننت‌هایت را طوری بنویس که فقط از props و state خودشان خروجی بسازند و هیچ وابستگی پنهانی به بیرون نداشته باشند؛ این‌ها همان کامپوننت‌های «خالص»‌اند که قابل‌پیش‌بینی، قابل‌تست و قابل‌استفاده‌مجددند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["کامپوننت: تابعی خالص از props به توصیف ظاهر","JSX زیر پوسته، ساختن شیء توصیف‌گر است نه DOM","رندر یعنی اجرای دوباره تابع و diff، نه ساختن دوباره DOM","برای لیست‌ها از map با key پایدار استفاده کن"]}]'::jsonb, '[{"q":"کامپوننت React در ساده‌ترین شکل چیست؟","opts":["یک کلاس DOM","تابعی که props می‌گیرد و توصیفی از ظاهر (JSX) برمی‌گرداند","یک فایل HTML","یک کتابخانه"],"ans":1,"why":"کامپوننت یک نگاشت خالص از داده به توصیف ظاهر است؛ همین خالص‌بودن، پیش‌بینی‌پذیری می‌آورد."},{"q":"وقتی state عوض می‌شود چه اتفاقی می‌افتد؟","opts":["کل DOM از نو ساخته می‌شود","کامپوننت دوباره اجرا، توصیف جدید diff و فقط تفاوت‌ها اعمال می‌شود","هیچ","صفحه رفرش می‌شود"],"ans":1,"why":"React توصیف جدید و قدیم را مقایسه و حداقل تغییر لازم را روی DOM واقعی اعمال می‌کند."},{"q":"چرا key پایدار مهم است؟","opts":["برای زیبایی","تا React بتواند عناصر را درست تطبیق دهد و با تغییر لیست، وضعیت‌ها جابه‌جا نشوند","اجباری نیست","برای CSS"],"ans":1,"why":"key هویت عنصر را برای diff مشخص می‌کند؛ key اشتباه باعث تطبیق نادرست و جابه‌جایی state می‌شود."}]'::jsonb),
('react-r2', 'react', 'State و جریان یک‌طرفه داده', 55, 2, '[{"k":"p","t":"اگر کامپوننت «بدن» اپلیکیشن باشد، State «حافظه» آن است؛ چیزی که تعیین می‌کند الان چه چیزی نمایش داده شود. ولی State قدرتی است که اگر بی‌قاعده پخش شود، اپلیکیشن را به یک گره‌کورِ باگ تبدیل می‌کند. React با «جریان یک‌طرفه داده» این قدرت را مهار می‌کند."},{"k":"h","t":"چرا State را مستقیم تغییر نمی‌دهیم"},{"k":"p","t":"React تنها زمانی می‌فهمد چیزی عوض شده که از setter رسمیِ useState استفاده کنی؛ تغییر مستقیم متغیر (مثل ++count) هیچ رندری راه نمی‌اندازد چون React خبردار نمی‌شود. مهم‌تر اینکه state باید «تغییرناپذیر» به‌روز شود: به‌جای دستکاری شیء موجود، یک نسخه جدید بساز. این باعث می‌شود مقایسه مرجع‌ها کافی باشد تا React بفهمد چه چیزی عوض شده و فقط همان را به‌روز کند."},{"k":"h","t":"جریان یک‌طرفه داده"},{"k":"p","t":"داده در React همیشه از بالا به پایین جاری می‌شود: والد state را نگه می‌دارد و آن را به‌صورت props به فرزند می‌دهد؛ فرزند برای تغییر، یک callback می‌گیرد و آن را صدا می‌کند و والد state را به‌روز می‌کند. این چرخه بسته و یک‌جهته یعنی همیشه می‌دانی داده از کجا می‌آید و تغییرش کجا اتفاق می‌افتد؛ برخلاف اتصال دوطرفه که هر تغییر می‌تواند از چند جا شروع شود و ردیابی‌اش سخت است."},{"k":"h","t":"State را کجا نگه داریم"},{"k":"p","t":"قاعده: state را در «نزدیک‌ترین جد مشترک» همه کامپوننت‌هایی که به آن نیاز دارند نگه دار، نه بالاتر. اگر state را خیلی بالا ببری، همه‌چیز وابسته به آن می‌شود و تغییرش کل درخت را رندر می‌کند؛ اگر خیلی پایین، نمی‌توانی بین خواهرها همگامش کنی. پیدا کردن این نقطه تعادل، بخش بزرگی از طراحی خوب کامپوننت است و با تمرین، چشمی می‌شود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"tsx","title":"Counter.tsx","code":"function Counter() {\n  const [count, setCount] = useState(0);\n\n  return (\n    <div>\n      <p>شمار: {count}</p>\n      {/* ❌ count++ هیچ رندری راه نمی‌اندازد */}\n      <button onClick={() => setCount(count + 1)}>+۱</button>\n\n      {/* ✓ به‌روزرسانی بر اساس مقدار قبلی، امن در پشت‌سرهم */}\n      <button onClick={() => setCount(c => c + 1)}>+۱ امن</button>\n    </div>\n  );\n}\n\n// والد state را نگه می‌دارد، فرزند فقط خبر می‌دهد\nfunction Parent() {\n  const [items, setItems] = useState<string[]>([]);\n  return <Child onAdd={it => setItems(p => [...p, it])} />;\n}"},{"k":"list","items":["setCount(count + 1) از مقدار «لحظه رندر» استفاده می‌کند؛ اگر دو بار پشت‌سرهم صدا زده شود، هر دو از همان مقدار شروع می‌کنند و یکی گم می‌شود.","فرم تابعی setCount(c => c + 1) همیشه از آخرین مقدار شروع می‌کند؛ پس در رویدادهای پشت‌سرهم امن است.","در Parent، فرزند (Child) هیچ دسترسی مستقیمی به items ندارد؛ فقط onAdd را صدا می‌کند و والد تصمیم می‌گیرد — این یعنی جریان یک‌طرفه."]},{"k":"def","term":"به‌روزرسانی تغییرناپذیر","t":"به‌جای تغییر درجا، ساختن نسخه جدید از state (مثل [...list, item] به‌جای push). چون React با مقایسه مرجع تشخیص می‌دهد چه چیزی عوض شده، مرجع جدید تضمین می‌کند تغییر دیده شود و از باگ‌های «تغییر کرد ولی صفحه به‌روز نشد» جلوگیری می‌کند."},{"k":"table","head":["کار","راه درست","راه اشتباه"],"rows":[["افزودن به لیست","[...list, x]","list.push(x)"],["به‌روز کردن شیء","{...obj, done: true}","obj.done = true"],["افزایش شمارنده پشت‌سرهم","setCount(c => c+1)","setCount(count+1) دو بار"]]},{"k":"warn","title":"دام رایج","t":"نگه‌داشتن state در چندجا برای یک واقعیت واحد (مثلاً هم در والد هم در فرزند)؛ این‌ها بالاخره از هم جدا می‌شوند و نمی‌دانی کدام درست است. برای هر واقعیت، یک منبع واحد (single source of truth) داشته باش و بقیه از آن مشتق شوند."},{"k":"tip","title":"نکته حرفه‌ای","t":"هر چیزی که می‌توان از state موجود «محاسبه» کرد را به‌عنوان state جدا نگه ندار؛ مثلاً تعداد آیتم‌ها را از خود لیست حساب کن. state کمتر یعنی جای کمتری برای ناسازگاری و باگ."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["State فقط با setter رسمی و به‌صورت تغییرناپذیر به‌روز می‌شود","داده از والد به فرزند، تغییر از فرزند به والد (جریان یک‌طرفه)","State را در نزدیک‌ترین جد مشترک نگه دار","هر واقعیت یک منبع واحد؛ بقیه مشتق شوند"]}]'::jsonb, '[{"q":"چرا ++count صفحه را به‌روز نمی‌کند؟","opts":["چون count ثابت است","چون React فقط با setter رسمی از تغییر خبردار و رندر را راه می‌اندازد","چون JSX قدیمی است","به‌روز می‌کند"],"ans":1,"why":"تغییر مستقیم متغیر هیچ اعلانی به React نمی‌فرستد؛ فقط setCount است که چرخه رندر را شروع می‌کند."},{"q":"چرا setCount(c => c + 1) امن‌تر از setCount(count + 1) است؟","opts":["سریع‌تر است","چون همیشه از آخرین مقدار شروع می‌کند و در فراخوانی‌های پشت‌سرهم چیزی گم نمی‌شود","کمتر حافظه","تصادفی است"],"ans":1,"why":"فرم تابعی بر اساس جدیدترین state اجرا می‌شود؛ فرم مستقیم از مقدار لحظه رندر که ممکن است قدیمی باشد."},{"q":"«جریان یک‌طرفه داده» یعنی چه؟","opts":["داده فقط یک نوع است","state در والد است و به پایین پاس می‌شود؛ تغییر از طریق callback به بالا برمی‌گردد","داده کش می‌شود","فقط یک state مجاز است"],"ans":1,"why":"این چرخه یک‌جهته باعث می‌شود همیشه بدانی داده از کجا می‌آید و کجا تغییر می‌کند."}]'::jsonb),
('c7-l1', 'react', 'HTML معنادار و مدل جعبه', 45, 3, '[{"k":"p","t":"HTML فقط چیدمان متن نیست؛ معنای سند را تعریف می‌کند. مرورگر، موتور جست‌وجو و صفحه‌خوان‌ها همه از تگ‌های معنادار برای فهم صفحه استفاده می‌کنند. div و span فقط وقتی مجازند که تگ معنادار مناسبی وجود نداشته باشد."},{"k":"code","lang":"html","title":"index.html","code":"<!DOCTYPE html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Blog</title>\n</head>\n<body>\n    <header>\n        <nav aria-label=\"Main\">\n            <a href=\"/\">Home</a>\n            <a href=\"/blog\">Blog</a>\n        </nav>\n    </header>\n    <main>\n        <article>\n            <h1>First Post</h1>\n            <p>Every element has a meaning.</p>\n        </article>\n    </main>\n    <footer>© 2026</footer>\n</body>\n</html>"},{"k":"h","t":"مدل جعبه؛ همه‌چیز یک جعبه است"},{"k":"p","t":"هر عنصر در CSS یک جعبه مستطیلی است با چهار لایه: محتوا، padding (فاصله داخلی)، border و margin (فاصله بیرونی). بزرگ‌ترین منبع سردرگمی تازه‌کارها، محاسبه اندازه واقعی جعبه است — تا اینکه box-sizing وارد می‌شود."},{"k":"code","lang":"css","title":"box-model.css","code":"/* بدون box-sizing: عرض واقعی = 300 + 20 + 2 = 322px ! */\n.card {\n    width: 300px;\n    padding: 10px;\n    border: 1px solid #ccc;\n}\n\n/* راه‌حل استاندارد: ریست سراسری */\n*, *::before, *::after {\n    box-sizing: border-box;   /* padding و border داخل width */\n}\n\n.card {\n    margin: 16px;             /* margin بیرون می‌ماند */\n}"},{"k":"warn","title":"تله margin","t":"دو عنصر عمودی با margin ۲۰ و ۳۰، فاصله ۵۰ ندارند — فاصله ۳۰ است! به این پدیده Margin Collapse می‌گویند و فقط در جهت عمودی رخ می‌دهد. اگر فاصله دقیق می‌خواهی از Flexbox یا Grid با gap استفاده کن."},{"k":"tip","title":"نکته منتور","t":"قبل از هر CSS، DevTools را باز کن و در تب Computed، جعبه واقعی عنصر را ببین. درک بصری مدل جعبه، ۸۰٪ باگ‌های چیدمان را قبل از شروع حل می‌کند."},{"k":"h","t":"عمیق‌تر: HTML معنادار، سرمایه‌گذاری پنهان"},{"k":"p","t":"تفاوت div و article از نظر مرورگر تقریباً صفر است — اما برای موتور جست‌وجو، صفحه‌خوان نابینایان و خودِ تو شش ماه بعد، همه‌چیز است. HTML معنادار یعنی ساختار سند، محتوا را توصیف کند: nav یعنی ناوبری، main یعنی محتوای اصلیِ یکتا، headingها سلسله‌مراتب منطقی (نه سایز فونت!). گوگل از همین ساختار برای فهم صفحه استفاده می‌کند و صفحه‌خوان‌ها با آن بین بخش‌ها می‌پرند. قانون ساده: قبل از div، از خودت بپرس «این بخش واقعاً چیست؟» — جواب تقریباً همیشه یک تگ بهتر از div دارد."},{"k":"p","t":"مدل جعبه هم جایی است که ۹۰٪ باگ‌های چیدمان متولد می‌شوند: هر عنصر یک جعبه است با محتوا، padding، border و margin — و سوال حیاتی این است که width شامل کدام‌هاست؟ با box-sizing: border-box (که باید اولین خط هر پروژه باشد)، width شامل padding و border می‌شود و ریاضی چیدمان قابل‌فهم می‌ماند. marginها عمودی‌شان ادغام می‌شود (Collapse) که تازه‌کارها را گیج می‌کند؛ padding هیچ‌وقت. و یک راز حرفه‌ای: به‌جای margin برای فاصله بین عناصر، در Flexbox از gap استفاده کن — هم کوتاه‌تر است و هم مشکل «اولین/آخرین عنصر» را حذف می‌کند."},{"k":"code","lang":"html","title":"deepdive-semantic.html","code":"<!-- ساختار معنادار = هدیه‌ای به سئو و دسترس‌پذیری -->\n<body>\n  <header>\n    <nav aria-label=\"اصلی\">\n      <a href=\"/courses\">دوره‌ها</a>\n      <a href=\"/roadmap\">مسیر یادگیری</a>\n    </nav>\n  </header>\n\n  <main>\n    <article>\n      <h1>چرا Big-O مهم است؟</h1>   <!-- یک h1 در صفحه -->\n      <p>...</p>\n      <section>\n        <h2>مرتبه‌ها در عمل</h2>     <!-- سلسله‌مراتب منطقی -->\n      </section>\n    </article>\n    <aside>مطالب مرتبط</aside>\n  </main>\n\n  <footer>...</footer>\n</body>"},{"k":"p","t":"دسترس‌پذیری (a11y) را از روز اول جدی بگیر — نه به‌خاطر قانون، به‌خاطر اینکه سایتت را واقعاً برای همه کار می‌کند و تازه، برای همه راحت‌تر: دکمه واقعی button (نه div با onclick) با کیبورد کار می‌کند، alt تصویر برای کاربری که اینترنت ضعیف دارد هم لود را معنا می‌کند، و contrast کافی زیر نور آفتاب هم خوانا می‌ماند. ابزار رایگان Lighthouse در DevTools در چند ثانیه نمره دسترس‌پذیری می‌دهد — هدف‌گذاری ۹۵+ هزینه‌ای ندارد و حرفه‌ای‌بودن را فریاد می‌زند."},{"k":"tip","title":"نکته منتور","t":"یک هفته فقط با کیبورد (Tab و Enter) سایت‌های موردعلاقه‌ات را بگرد — تجربه‌ای که هر فرانت‌اندکاری باید داشته باشد. جایی که فوکوس گم می‌شود یا دکمه‌ای با Enter کار نمی‌کند، دقیقاً همان‌جایی است که HTML معنادار کم بوده است."}]'::jsonb, '[{"q":"با box-sizing: border-box، یک عنصر width: 300px و padding: 20px چه عرضی اشغال می‌کند؟","opts":["۳۴۰ پیکسل","۳۰۰ پیکسل","۳۲۰ پیکسل","بستگی به مرورگر دارد"],"ans":1,"why":"در border-box پدینگ و بوردر داخل همان ۳۰۰ پیکسل جا می‌گیرند؛ محتوای داخلی کوچک‌تر می‌شود ولی جعبه ثابت می‌ماند."},{"q":"کدام تگ برای ناوبری اصلی صفحه مناسب‌تر است؟","opts":["div","section","nav","span"],"ans":2,"why":"nav به مرورگر و صفحه‌خوان‌ها می‌گوید اینجا بلوک ناوبری است؛ صفحه‌خوان‌ها حتی میان‌بر پرش به آن دارند."}]'::jsonb),
('c7-l2', 'react', 'Flexbox و Grid؛ پایان جنگ چیدمان', 65, 4, '[{"k":"p","t":"قبل از این دو، چیدمان با float و position یک میدان جنگ بود. قانون ساده: Flexbox برای یک بُعد (یک ردیف یا یک ستون) و Grid برای دو بُعد (ردیف و ستون همزمان). با همین قاعده، ۹۵٪ چیدمان‌های وب مدرن حل می‌شوند."},{"k":"code","lang":"css","title":"flexbox.css","code":".navbar {\n    display: flex;\n    justify-content: space-between;  /* محور اصلی */\n    align-items: center;             /* محور فرعی */\n    gap: 16px;\n}\n\n/* کارت‌های هم‌اندازه که نشکنند */\n.cards {\n    display: flex;\n    flex-wrap: wrap;\n}\n.cards > * {\n    flex: 1 1 280px;    /* رشد کن، کوچک شو، حداقل 280px */\n}"},{"k":"code","lang":"css","title":"grid.css","code":"/* چیدمان کلاسیک صفحه */\n.layout {\n    display: grid;\n    grid-template-columns: 240px 1fr;   /* سایدبار + محتوا */\n    grid-template-rows: 64px 1fr auto;\n    grid-template-areas:\n        \"header header\"\n        \"sidebar main\"\n        \"footer footer\";\n    min-height: 100vh;\n}\n.header  { grid-area: header; }\n.sidebar { grid-area: sidebar; }\n.main    { grid-area: main; }\n.footer  { grid-area: footer; }\n\n/* گالری با تعداد ستون خودکار */\n.gallery {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n    gap: 12px;\n}"},{"k":"def","term":"minmax و auto-fill","t":"الگوی repeat(auto-fill, minmax(220px, 1fr)) بدون حتی یک Media Query، گالری‌ای می‌سازد که تعداد ستون‌هایش با عرض صفحه تنظیم می‌شود — قدرتمندترین یک‌خط CSS مدرن."},{"k":"tip","title":"نکته منتور","t":"gap را به margin ترجیح بده: فقط بین آیتم‌ها فاصله می‌گذارد نه دور‌تا‌دور، و در RTL هم درست کار می‌کند. فاصله‌گذاری با margin روی آیتم‌های flex/grid بوی کد قدیمی می‌دهد."},{"k":"h","t":"عمیق‌تر: مدل ذهنی Flexbox و Grid — یک‌بار برای همیشه"},{"k":"p","t":"Flexbox یک‌بعدی است: یک محور اصلی (main) و یک محور فرعی (cross) — عناصر در یک خط (یا خط‌های شکسته موازی) جریان دارند. هر خاصیتش را باید با این سوال بخوانی: روی کدام محور اثر می‌کند؟ justify-content محور اصلی، align-items محور فرعی. اگر این مدل ذهنی جا بیفتد، «چرا align-items عمودی‌ام را وسط نمی‌کند؟» برای همیشه حل می‌شود: چون در direction عمودی، محورها جابه‌جا شده‌اند! Grid اما دوبعدی است: همزمان سطر و ستون تعریف می‌کنی و عناصر در خانه‌های شبکه می‌نشینند — برای چیدمان کل صفحه و هر جایی که سطر و ستون واقعی داری."},{"k":"p","t":"قانون عملی صنعت: ناوبری، دکمه‌ها، کارت‌های هم‌ردیف و هر چیز «یک‌خطی» → Flexbox؛ چیدمان صفحه، گالری، داشبورد و هر چیز «جدولی» → Grid. و قدرتمندترین قابلیت Grid که کمتر استفاده می‌شود، grid-template-areas است: چیدمان را مثل نقاشی ASCII می‌نویسی — ''header header / sidebar main / footer footer'' — و خواندنش برای هر کسی، حتی غیربرنامه‌نویس، آسان است. برای ریسپانسیو هم کافی همین متن را عوض کنی؛ هیچ سلکتور جدیدی لازم نیست."},{"k":"code","lang":"css","title":"deepdive-grid.css","code":"/* چیدمان کامل صفحه با Area — مثل نقاشی */\n.page {\n  display: grid;\n  grid-template-areas:\n    \"header  header\"\n    \"sidebar main\"\n    \"footer  footer\";\n  grid-template-columns: 240px 1fr;\n  grid-template-rows: auto 1fr auto;\n  min-height: 100vh;\n}\n.header  { grid-area: header; }\n.sidebar { grid-area: sidebar; }\n.main    { grid-area: main; }\n.footer  { grid-area: footer; }\n\n@media (max-width: 768px) {\n  .page {                 /* فقط متن عوض می‌شود! */\n    grid-template-areas:\n      \"header\"\n      \"main\"\n      \"footer\";\n    grid-template-columns: 1fr;\n  }\n}\n\n/* Flexbox: سه کارت هم‌ردیف با فاصله هوشمند */\n.cards {\n  display: flex;\n  gap: 1rem;                 /* نه margin-first/last! */\n  flex-wrap: wrap;\n}\n.card { flex: 1 1 280px; }   /* حداقل ۲۸۰، بعد کش بیاید */"},{"k":"table","head":["سناریو","ابزار","چرا"],"rows":[["منوی افقی / دکمه‌ها","Flexbox","یک‌بعدی و ساده"],["صفحه‌آرایی کلی","Grid + Areas","دوبعدی و خوانا"],["گالری با اندازه‌های برابر","Grid + auto-fit","minmax(220px, 1fr) معجزه می‌کند"],["وسط‌کردن کامل یک عنصر","Grid: place-items: center","کوتاه‌ترین راه تاریخ CSS"],["توزیع فاصله پویا","Flexbox + gap","space-between فقط در یک جهت"]]},{"k":"tip","title":"نکته منتور","t":"flexboxfroggy.com و cssgridgarden.com دو بازی رایگان‌اند که در مجموع دو ساعت، این دو مدل ذهنی را با تکرار تعاملی جا می‌اندازند — بازدهی‌شان از خواندن ده مقاله بیشتر است. بعدش هم DevTools مرورگر را باز کن: در تب Layout، خط‌های Grid و Flex را رنگی روی صفحه می‌کشد و دیباگ چیدمان را از حدس‌زدن نجات می‌دهد."}]'::jsonb, '[{"q":"برای چیدمان «سه ستون با هدر تمام‌عرض» کدام ابزار مناسب‌تر است؟","opts":["Flexbox","Grid","float","position"],"ans":1,"why":"این چیدمان دوبُعدی است (ردیف هدر + ردیف ستون‌ها)؛ Grid با template-areas آن را declarative و خوانا می‌کند."},{"q":"خاصیت gap چه مزیتی نسبت به margin دارد؟","opts":["سریع‌تر رندر می‌شود","فقط بین آیتم‌ها فاصله می‌گذارد و در RTL سالم است","رنگ‌پذیر است","هیچ مزیتی ندارد"],"ans":1,"why":"margin دور همه آیتم‌ها فاصله می‌اندازد و در لبه‌ها باید خنثی شود؛ gap دقیقاً همان فاصله بین آیتم‌هاست."}]'::jsonb),
('c7-l3', 'react', 'ریسپانسیو و انیمیشن', 55, 5, '[{"k":"p","t":"طراحی ریسپانسیو یعنی یک صفحه برای همه اندازه‌ها؛ و رویکرد مدرن «موبایل اول» است: استایل پایه را برای کوچک‌ترین صفحه بنویس و با Media Query برای صفحه‌های بزرگ‌تر توسعه بده. واحد‌های نسبی (rem، %، vw) و توابعی مثل clamp() کار را تمیز می‌کنند."},{"k":"code","lang":"css","title":"responsive.css","code":"/* موبایل اول: تایپوگرافی سیال */\nh1 {\n    font-size: clamp(1.8rem, 4vw + 1rem, 3.2rem);\n}\n\n.container {\n    width: min(92%, 1100px);   /* حداکثر 1100px، وگرنه 92% */\n    margin-inline: auto;\n}\n\n/* دسکتاپ: منوی افقی و سایدبار */\n@media (min-width: 768px) {\n    .menu { flex-direction: row; }\n    .layout { grid-template-columns: 260px 1fr; }\n}"},{"k":"h","t":"انیمیشن با performance"},{"k":"code","lang":"css","title":"motion.css","code":".card {\n    transition: transform 0.25s ease, box-shadow 0.25s ease;\n}\n.card:hover {\n    transform: translateY(-6px);\n    box-shadow: 0 14px 30px rgba(0, 0, 0, 0.18);\n}\n\n/* فقط transform و opacity روی GPU انیمیت می‌شوند */\n@keyframes fade-up {\n    from { opacity: 0; transform: translateY(24px); }\n    to   { opacity: 1; transform: translateY(0); }\n}\n.reveal { animation: fade-up 0.6s ease both; }\n\n@media (prefers-reduced-motion: reduce) {\n    * { animation: none; transition: none; }\n}"},{"k":"warn","title":"قانون ۶۰ فریم","t":"فقط transform و opacity را انیمیت کن؛ انیمیشن روی width یا top باعث Reflow کل صفحه و لگ می‌شود. و همیشه prefers-reduced-motion را محترم بشمار — بعضی کاربران با حرکت زیاد واقعاً اذیت می‌شوند."},{"k":"def","term":"clamp()","t":"تابع clamp(min, preferred, max) مقداری سیال می‌دهد که از بازه خارج نمی‌شود؛ برای تایپوگرافی و فاصله‌ها بدون Media Query."},{"k":"h","t":"عمیق‌تر: ریسپانسیو مدرن — کمتر Media Query، بیشتر هوش"},{"k":"p","t":"ریسپانسیو کلاسیک یعنی ده‌ها Media Query برای هر سایز صفحه — و هر دستگاه جدید، یک شکست جدید. ریسپانسیو مدرن با سه ابزار این مشکل را ریشه‌ای حل می‌کند: اول Mobile-First (اول برای کوچک‌ترین صفحه بنویس و با min-width پله‌پله گسترش بده — کدتان همیشه پایه‌ی ساده دارد)، دوم واحدهای نسبی و سیال (rem برای فونت، درصد و fr برای چیدمان، و clamp() که اندازه را بین حداقل و حداکثر «سیال» می‌کند بدون یک خط Media Query)، و سوم Grid/Flex که خودشان می‌شکنند و می‌پیچند. نتیجه: به‌جای ۱۵ نقطه شکست، شاید ۲ تا لازم شود."},{"k":"p","t":"انیمیشن هم قانون مهندسی دارد: انیمیشن خوب اطلاعات می‌دهد (جهتِ تغییر، ارتباط علت و معلول)، نه اینکه فقط چشم را قلقلک بدهد. دو خاصیت طلایی: transform و opacity — چون بدون Reflow روی GPU اجرا می‌شوند و حتی در گوشی ضعیف، ۶۰ فریم می‌مانند؛ در مقابل، انیمیشن روی width یا top هر فریم کل چیدمان را دوباره محاسبه می‌کند. مدت استاندارد رابط کاربری ۱۵۰ تا ۳۰۰ میلی‌ثانیه است — کوتاه‌تر نامحسوس و بلندتر کلافه‌کننده. و transition را فقط روی خاصیت‌های مشخص بگذار، نه all — هم سریع‌تر است هم غافلگیری کمتری دارد."},{"k":"code","lang":"css","title":"deepdive-responsive.css","code":"/* Mobile-First: پایه، کوچک‌ترین صفحه است */\n.hero-title {\n  /* سیال بین ۲۴ تا ۶۴ پیکسل — بدون Media Query */\n  font-size: clamp(1.5rem, 4vw + 1rem, 4rem);\n}\n\n.container {\n  display: grid;\n  gap: 1.5rem;\n  /* خودش می‌شکند: حداقل ۲۶۰px، بقیه کش بیاید */\n  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\n}\n\n/* فقط یک نقطه شکست، آن هم برای تغییر ساختار: */\n@media (min-width: 1024px) {\n  .layout { grid-template-columns: 260px 1fr; }\n}\n\n/* دکمه: انیمیشن روی transform — GPU-friendly */\n.btn {\n  transition: transform 200ms ease, box-shadow 200ms ease;\n}\n.btn:hover  { transform: translateY(-2px); }\n.btn:active { transform: translateY(0); }\n\n/* احترام به کاربری که حرکت نمی‌خواهد */\n@media (prefers-reduced-motion: reduce) {\n  * { transition-duration: 0.01ms !important; animation: none !important; }\n}"},{"k":"p","t":"prefers-reduced-motion را جدی بگیر: کاربرانی که اختلال دهلیزی دارند، با انیمیشن‌های پارالاکس و اسلاید واقعاً دچار تهوع می‌شوند — و سیستم‌عامل‌ها حالا این ترجیح را به سایت اعلام می‌کنند. بستن انیمیشن‌ها برای این کاربران، یک خط کد است و تفاوت بین «سایت حرفه‌ای» و «سایتی که حالم را بد کرد». تصویرهای پاسخگو هم با srcset و sizes به مرورگر اجازه می‌دهند سایز مناسب دستگاه را دانلود کند — کاربر موبایل نباید عکس ۴K دسکتاپ را بکشد."},{"k":"tip","title":"نکته منتور","t":"قبل از هر Media Query جدید، سه جایگزین را چک کن: auto-fit/auto-fill در Grid، clamp() برای تایپوگرافی سیال، و flex-wrap برای جریان طبیعی. اگر هیچ‌کدام جواب نداد، آنگاه Media Query بنویس — و آن را با min-width (Mobile-First) بنویس، نه max-width."}]'::jsonb, '[{"q":"رویکرد «موبایل اول» یعنی چه؟","opts":["اول اپلیکیشن موبایل بساز","استایل پایه برای موبایل و توسعه با min-width","استفاده از max-width","طراحی فقط برای موبایل"],"ans":1,"why":"با min-width استایل‌های بزرگ‌تر فقط اضافه می‌شوند؛ کد پایه سبک می‌ماند و دستگاه‌های ضعیف‌تر CSS کمتری پردازش می‌کنند."},{"q":"چرا transform برای انیمیشن بهتر از تغییر top است؟","opts":["ساده‌تر نوشته می‌شود","بدون Reflow روی GPU اجرا می‌شود","در همه مرورگرها کار می‌کند","رنگ‌ها را هم تغییر می‌دهد"],"ans":1,"why":"تغییر top چیدمان کل صفحه را دوباره محاسبه می‌کند؛ transform فقط لایه عنصر را جابه‌جا می‌کند و بقیه صفحه دست‌نخورده می‌ماند."}]'::jsonb),
('c8-l1', 'react', 'زبان؛ متغیر، Scope و DOM', 55, 6, '[{"k":"p","t":"جاوااسکریپت مدرن (ES6+) سه نوع متغیر دارد و فقط یکی از آن‌ها را باید تقریباً همیشه استفاده کنی: const. تفاوت let و var در Scope است؛ var به بلاک if احترام نمی‌گذارد و منشاء باگ‌های کلاسیک است."},{"k":"code","lang":"js","title":"scope.js","code":"const API = \"https://api.example.com\";  // ثابت\nlet count = 0;                          // قابل تغییر\n\nfor (let i = 0; i < 3; i++) {\n    setTimeout(() => console.log(i), 100);\n}\n// با let: 0 1 2   |   با var: 3 3 3  (همه یک متغیر را می‌بینند!)\n\n// Template literal و Destructuring\nconst user = { name: \"Ali\", age: 25 };\nconst { name, age } = user;\nconsole.log(`${name} is ${age}`);"},{"k":"h","t":"DOM؛ پل بین کد و صفحه"},{"k":"code","lang":"js","title":"dom.js","code":"const btn = document.querySelector(\"#submit\");\nconst list = document.querySelector(\"#items\");\n\nbtn.addEventListener(\"click\", () => {\n    const li = document.createElement(\"li\");\n    li.textContent = \"New item\";\n    list.appendChild(li);\n});\n\n// Event Delegation: یک listener برای همه آیتم‌ها\nlist.addEventListener(\"click\", (e) => {\n    if (e.target.tagName === \"LI\") {\n        e.target.classList.toggle(\"done\");\n    }\n});"},{"k":"def","term":"Event Delegation","t":"به‌جای listener جداگانه برای هر آیتم، یک listener روی والد بگذار و از event.target بفهم کدام فرزند کلیک شده — حافظه کمتر و مدیریت آیتم‌های داینامیک رایگان."},{"k":"warn","title":"var را بازنشسته کن","t":"var دو مشکل بزرگ دارد: Scope تابعی به‌جای بلاکی و Hoisting گیج‌کننده. در کد جدید فقط const و بنویس و let فقط وقتی واقعاً بازتخصیص لازم داری."},{"k":"h","t":"عمیق‌تر: Scope و زنجیره‌ای که همه‌چیز را توضیح می‌دهد"},{"k":"p","t":"وقتی جاوااسکریپت متغیری را می‌خواند، از Scope فعلی شروع می‌کند و پله‌پله بالا می‌رود تا global — این «زنجیره Scope» است و تمام رفتارهای عجیب var/let را توضیح می‌دهد. var به نزدیک‌ترین «تابع» می‌چسبد (Function-scoped) و حتی Hoisting می‌شود: قبل از تعریف هم وجود دارد با مقدار undefined — تله‌ای که کدهای قدیمی را پر از باگ کرده. let و const به نزدیک‌ترین «بلوک» می‌چسبند و تا خط تعریف، در «منطقه مرده موقت» (TDZ) هستند؛ دسترسی زودتر از موعد، خطا می‌دهد — همان چیزی که می‌خواستیم. قاعده مدرن: همیشه const، فقط وقتی واقعاً reassing می‌شود let، و var فقط وقتی کد ۲۰۱۰ را می‌خوانی."},{"k":"p","t":"DOM را نه به‌عنوان «HTML در جاوااسکریپت»، که به‌عنوان یک API درختی ببین: هر تگ یک شیء است و تغییرش هزینه دارد. بزرگ‌ترین اشتباه تازه‌کارها، خواندن/نوشتن DOM در حلقه است — هر بار Reflow احتمالی. الگوی حرفه‌ای: داده را در حافظه تغییر بده، یک‌بار به DOM بنویس (یا از DocumentFragment برای درج گروهی استفاده کن). و رویدادها را با «تفویض» (Delegation) مدیریت کن: یک listener روی والد، به‌جای صد listener روی فرزندان — چون رویدادها از هدف به سمت ریشه حباب می‌شوند (Bubbling)، والد می‌تواند با e.target بفهمد کدام فرزند کلیک شده. هم حافظه کمتر، هم برای عناصری که بعداً اضافه می‌شوند کار می‌کند."},{"k":"code","lang":"js","title":"deepdive-delegation.js","code":"// ضدالگو: ۱۰۰ listener\nitems.forEach(li => li.addEventListener(''click'', handler));\n\n// الگوی تفویض: یک listener، امروز و برای آیتم‌های آینده\ndocument.querySelector(''#list'').addEventListener(''click'', (e) => {\n  const li = e.target.closest(''li'');   // نزدیک‌ترین جدِ li\n  if (!li) return;                     // کلیک جای دیگر بوده\n  console.log(''انتخاب شد:'', li.dataset.id);\n});\n\n// درج گروهی بدون Reflow مکرر:\nconst frag = document.createDocumentFragment();\nfor (let i = 0; i < 1000; i++) {\n  const li = document.createElement(''li'');\n  li.textContent = `آیتم ${i}`;\n  frag.appendChild(li);\n}\nlist.appendChild(frag);   // فقط یک بار به DOM واقعی\n\n// TDZ — چرا let بهتر از var است:\n// console.log(x);  → ReferenceError (خوب! باگ را زود نشان داد)\nconst x = 10;\n// اگر var بود: undefined می‌دیدیم و باگ قایم می‌ماند"},{"k":"table","head":["ویژگی","var","let","const"],"rows":[["محدوده","تابع","بلوک","بلوک"],["Hoisting با مقدار","بله (undefined) — تله","TDZ — خطا می‌دهد","TDZ — خطا می‌دهد"],["تغییرپذیری","بله","بله","خیر (برای مرجع اشیاء)"],["توصیه","هرگز","وقتی reassing لازم است","پیش‌فرض همیشگی"]]},{"k":"tip","title":"نکته منتور","t":"برای درک Bubbling، یک DevTools باز کن و در تب Elements، روی یک دکمه عمیق listener بگذار و ببین رویداد از کجاها رد می‌شود. درک این حباب، نیمی از سوال‌های مصاحبه DOM (stopPropagation، preventDefault، تفاوت capture/bubble) را یک‌جا حل می‌کند."}]'::jsonb, '[{"q":"خروجی حلقه بالا با var چیست؟","opts":["0 1 2","1 2 3","3 3 3","undefined"],"ans":2,"why":"var یک متغیر واحد برای کل حلقه می‌سازد؛ وقتی callbackها اجرا می‌شوند حلقه تمام شده و مقدارش ۳ است."},{"q":"Event Delegation چه مزیتی دارد؟","opts":["کلیک سریع‌تر ثبت می‌شود","یک listener روی والد، همه فرزندان را پوشش می‌دهد","جلوگیری از کلیک راست","نیاز به querySelector را حذف می‌کند"],"ans":1,"why":"هم حافظه کمتر مصرف می‌شود و هم آیتم‌هایی که بعداً داینامیک اضافه می‌شوند، خودبه‌خود پوشش داده می‌شوند."}]'::jsonb),
('c8-l2', 'react', 'توابع، Closure و آرایه‌ها', 60, 7, '[{"k":"p","t":"در جاوااسکریپت تابع شهروند درجه یک است: در متغیر ذخیره می‌شود، پاس داده می‌شود و برمی‌گردد. Closure وقتی شکل می‌گیرد که تابع، متغیرهای محدوده تولدش را حتی بعد از تمام‌شدن آن محدوده به یاد می‌آورد — یکی از قدرتمندترین و پرمصاحبه‌ترین مفاهیم زبان."},{"k":"code","lang":"js","title":"closure.js","code":"function counter() {\n    let count = 0;                 // در Scope بسته حبس می‌شود\n    return {\n        inc: () => ++count,\n        get: () => count,\n    };\n}\n\nconst c = counter();\nc.inc(); c.inc();\nconsole.log(c.get());   // 2 — count زنده ماند!\n\n// کاربرد واقعی: Debounce\nfunction debounce(fn, delay = 300) {\n    let timer;\n    return (...args) => {\n        clearTimeout(timer);\n        timer = setTimeout(() => fn(...args), delay);\n    };\n}"},{"k":"h","t":"متدهای آرایه؛ حلقه‌نویسی ممنوع"},{"k":"code","lang":"js","title":"arrays.js","code":"const products = [\n    { name: \"Laptop\", price: 1200, stock: 3 },\n    { name: \"Phone\",  price: 800,  stock: 0 },\n    { name: \"Tablet\", price: 600,  stock: 7 },\n];\n\nconst names = products.map(p => p.name);\nconst available = products.filter(p => p.stock > 0);\nconst total = products.reduce((sum, p) => sum + p.price, 0);\nconst expensive = products.find(p => p.price > 1000);\n\nconsole.log(available.length, total);   // 2 2600"},{"k":"tip","title":"نکته منتور","t":"به‌جای حلقه for برای تبدیل داده، اول فکر کن: map (تبدیل تک‌به‌تک)، filter (انتخاب)، reduce (جمع‌کردن به یک مقدار) یا find (اولین انطباق). این چهار تا ۹۰٪ پردازش داده در فرانت‌اند را پوشش می‌دهند."},{"k":"h","t":"عمیق‌تر: Closure — همان ایده‌ای که React را ممکن کرد"},{"k":"p","t":"Closure یعنی تابع، محیطی که در آن ساخته شده را «به همراه می‌برد»: متغیرهای Scope بیرونی‌اش زنده می‌مانند حتی بعد از اینکه تابع بیرونی برگشته. makeCounter() را که دیدی، Closure را دیدی: شمارنده در متغیر محلی makeCounter زندگی می‌کند و تابع برگشتی، کلیدش را دارد — نه از بیرون قابل‌دسترس، نه از بین می‌رود. این همان «کپسوله‌سازی به سبک جاوااسکریپت» است قبل از آنکه class وجود داشته باشد. و مهم‌تر: Hooks در React (useState و همه دوستانش) دقیقاً روی همین Closureها سوارند — وقتی می‌فهمی چرا state در کامپوننت ماندگار است، یعنی Closure را فهمیده‌ای."},{"k":"p","t":"چهار قاعده this را مثل جدول ضرب حفظ کن، چون نصف باگ‌های «کلاسیک» جاوااسکریپت از همین‌جاست: ۱) فراخوانی ساده obj.fn() → this می‌شود obj؛ ۲) فراخوانی تنها fn() → در strict می‌شود undefined؛ ۳) Arrow Function این خودش را «ندارد» و از محیط ارث می‌برد — پس در callbackهای داخل متد کلاس، Arrow تنها راه درست است؛ ۴) bind/call/apply می‌توانند دستی this را ببندند. اگر روزی دیدی this ناگهان undefined شده، یعنی تابع از مالکش «جدا» شده (مثلاً پاس‌داده‌شده به عنوان callback) — و درمانش Arrow یا bind است."},{"k":"code","lang":"js","title":"deepdive-closure.js","code":"function makeCounter(start = 0) {\n  let count = start;              // متغیر «زندانی» Closure\n  return {\n    inc:  () => ++count,\n    get:  () => count,\n  };\n}\nconst c = makeCounter(10);\nc.inc(); c.inc();\nconsole.log(c.get());   // 12 — و هیچ راهی برای دستکاری مستقیم count نیست\n\n// تله کلاسیک مصاحبه:\nfor (var i = 0; i < 3; i++) setTimeout(() => console.log(i), 0);\n// خروجی: 3 3 3  ← var یک متغیر واحد است؛ همه Closureها همان را می‌بینند\n\nfor (let i = 0; i < 3; i++) setTimeout(() => console.log(i), 0);\n// خروجی: 0 1 2  ← let در هر دور تکرار، متغیر تازه می‌سازد\n\n// Arrow و this — چرا داخل متد کلاس Arrow می‌نویسیم:\nclass Timer {\n  seconds = 0;\n  start() {\n    setInterval(() => {\n      this.seconds += 1;          // this از محیط (start) ارث برده — درست\n    }, 1000);\n    // اگر تابع معمولی بود: this = undefined → TypeError\n  }\n}"},{"k":"p","t":"توابع مرتبه‌بالا — توابعی که تابع می‌گیرند یا برمی‌گردانند — ابزار اصلی «انتزاع رفتار» در جاوااسکریپت‌اند: debounce و throttle (کنترل نرخ فراخوانی)، memoize (کش نتایج)، once (اجرای یک‌بار) و curry همه با سه خط Closure ساخته می‌شوند. یادگیری این چهار تابع کوچک، همزمان Closure را تثبیت می‌کند و جعبه‌ابزار روزمره‌ات را واقعی می‌کند — چون دیر یا زود در هر پروژه UI به debounce برای فیلد جست‌وجو نیاز پیدا می‌کنی."},{"k":"code","lang":"js","title":"deepdive-debounce.js","code":"// تا ۳۰۰ms بعد از آخرین تایپ، اجرا نشود:\nfunction debounce(fn, delay = 300) {\n  let timer;\n  return (...args) => {\n    clearTimeout(timer);                // هر تایپ، تایمر قبلی را باطل می‌کند\n    timer = setTimeout(() => fn(...args), delay);\n  };\n}\n\nsearchInput.addEventListener(''input'', debounce((e) => {\n  fetch(`/api/search?q=${e.target.value}`);\n}, 300));\n// نتیجه: به‌جای ۲۰ درخواست برای «ساختمان داده»، فقط ۱ درخواست"},{"k":"tip","title":"نکته منتور","t":"سوال کلاسیک «چرا حلقه var سه تا ۳ چاپ می‌کند؟» در مصاحبه‌های فرانت‌اند هنوز زنده است. جواب کامل سه بخش دارد: var به تابع می‌چسبد نه بلوک، Closureها مرجع را نگه می‌دارند نه مقدار را، و let در هر تکرار Binding تازه می‌سازد. این جواب، درک عمیق زبان را در ۳۰ ثانیه ثابت می‌کند."}]'::jsonb, '[{"q":"چرا تابع get هنوز به count دسترسی دارد؟","opts":["چون count سراسری است","چون Closure متغیرهای Scope تولد را نگه می‌دارد","چون جاوااسکریپت کش می‌کند","چون const بوده است"],"ans":1,"why":"وقتی تابعی ساخته می‌شود، به Scope زنجیره‌ای که در آن متولد شده وصل می‌ماند؛ حتی وقتی counter() برگشته، count زنده است."},{"q":"برای محاسبه مجموع قیمت‌ها کدام متد مناسب است؟","opts":["map","filter","reduce","find"],"ans":2,"why":"reduce یک آرایه را به یک مقدار واحد (عدد، شیء و...) کاهش می‌دهد — دقیقاً کاری که جمع‌زدن نیاز دارد."}]'::jsonb),
('c8-l3', 'react', 'ناهمگامی؛ Promise و async/await', 70, 8, '[{"k":"p","t":"جاوااسکریپت تک‌رشته‌ای است؛ پس عملیات طولانی (شبکه، فایل) نباید رشته را مسدود کند. راه‌حل: Event Loop. عملیات‌ها در پس‌زمینه انجام می‌شوند و نتیجه با Promise برمی‌گردد؛ async/await هم سینتکس خوانای همان Promise است، نه چیز جدیدی."},{"k":"code","lang":"js","title":"async.js","code":"// Promise: سه حالت — pending, fulfilled, rejected\nasync function getUser(id) {\n    const res = await fetch(`/api/users/${id}`);\n    if (!res.ok) throw new Error(`HTTP ${res.status}`);\n    return res.json();\n}\n\nasync function main() {\n    try {\n        const user = await getUser(42);\n        console.log(user.name);\n    } catch (err) {\n        console.error(\"Failed:\", err.message);\n    }\n}\n\nmain();"},{"k":"h","t":"موازی یا متوالی؟"},{"k":"code","lang":"js","title":"parallel.js","code":"// بد: متوالی — ۳ ثانیه + ۲ ثانیه = ۵ ثانیه\nconst a = await fetchJson(\"/a\");   // 3s\nconst b = await fetchJson(\"/b\");   // 2s\n\n// خوب: موازی — max(3, 2) = ۳ ثانیه\nconst [x, y] = await Promise.all([\n    fetchJson(\"/a\"),\n    fetchJson(\"/b\"),\n]);"},{"k":"warn","title":"اشتباه رایج","t":"استفاده از await داخل حلقه برای درخواست‌های مستقل، آن‌ها را متوالی می‌کند و سرعت را چند برابر کم می‌کند. اگر درخواست‌ها مستقل‌اند، Promise.all بزن؛ اگر ترتیب مهم نیست و شکست یکی قابل‌قبول است، Promise.allSettled."},{"k":"def","term":"Event Loop","t":"مکانیزمی که صف callbackها را بعد از خالی‌شدن پشته اجرا می‌کند؛ به همین دلیل setTimeout(fn, 0) هم بلافاصله اجرا نمی‌شود — اول باید پشته فعلی خالی شود."},{"k":"h","t":"عمیق‌تر: Event Loop، میکروتسک‌ها و چرا ترتیب خروجی گیج می‌کند"},{"k":"p","t":"جاوااسکریپت تک‌نخی است — فقط یک کار همزمان انجام می‌دهد — و با این حال وب همزمان هزار کار می‌کند. راز: کارهای «کند» (شبکه، تایمر، فایل) را به محیط می‌سپارد و وقتی تمام شدند، callbackشان در صف می‌نشیند؛ Event Loop هم هر وقت پشته خالی شد، یکی را برمی‌دارد. ظرافت کلیدی اینجاست که دو صف وجود دارد: میکروتسک‌ها (Promiseها) اولویت مطلق دارند و تا خالی نشوند، هیچ ماکروتسک‌ای (setTimeout) اجرا نمی‌شود. پس console.log اول، بعد .thenها، بعد timeout — حتی اگر timeout با تأخیر صفر ثبت شده باشد. این ترتیب، جواب تمام سوال‌های «خروجی این کد چیست» مصاحبه است."},{"k":"p","t":"async/await فقط پوشش خوش‌خط‌وتر برای Promise است: تابع async همیشه Promise برمی‌گرداند و await یعنی «اینجا تابع را متوقف کن، بقیه برنامه ادامه دارد، وقتی Promise نشست برگرد». اما سه تله دارد که حرفه‌ای‌ها را هم می‌گیرد: ۱) await داخل حلقه یعنی درخواست‌های سریالی — وقتی مستقل‌اند باید Promise.all زد و زمان را از جمع به بیشینه رساند؛ ۲) بدون try/catch، خطای Promise وسط تابع گم می‌شود و به unhandled rejection تبدیل می‌شود؛ ۳) await کردن چیزی که Promise نیست اشکالی ندارد ولی بیهوده است. و Promise.allSettled را بشناس: وقتی می‌خواهی همه نتایج (حتی شکست‌ها) را بگیری و یک خطا کل دسته را خراب نکند."},{"k":"code","lang":"js","title":"deepdive-eventloop.js","code":"// ترتیب خروجی را قبل از اجرا حدس بزن:\nconsole.log(''۱ — هماهنگ'');\n\nsetTimeout(() => console.log(''۴ — timeout (ماکروتسک)''), 0);\n\nPromise.resolve()\n  .then(() => console.log(''۳ — promise (میکروتسک)''));\n\nconsole.log(''۲ — هماهنگ'');\n// ترتیب واقعی: ۱، ۲، ۳، ۴ — حتی با timeout صفر!\n\n// ضدالگو: درخواست‌های سریالی — ۳ ثانیه\nfor (const id of ids) {\n  const user = await fetchUser(id);   // هر بار صبر کن!\n}\n\n// الگوی درست: موازی — ۱ ثانیه\nconst users = await Promise.all(ids.map(fetchUser));\n\n// اگر مستقل نیستند (هر کدام به قبلی نیاز دارد):\nlet cursor = null;\nconst pages = [];\nwhile (cursor !== undefined) {        // زنجیره واقعی وابستگی\n  const page = await fetchPage(cursor);\n  pages.push(page.data);\n  cursor = page.next;\n}"},{"k":"table","head":["ابزار","کی استفاده کنیم"],"rows":[["Promise.all","چند عملیات مستقل — همه باید موفق شوند"],["Promise.allSettled","چند عملیات مستقل — نتیجه هرکدام (موفق/شکست) را جدا بخواه"],["Promise.race","مسابقه: اولین نتیجه (مثلاً timeout در برابر API)"],["Promise.any","اولین موفقیت — شکست‌ها مهم نیستند"],["for...of + await","فقط وقتی واقعاً زنجیره وابستگی داری"]]},{"k":"warn","title":"حلقه بی‌پایان مخفی","t":"یک while که فقط میکروتسک تولید می‌کند (Promiseهای تو در تو)، Event Loop را برای همیشه گروگان می‌گیرد و UI قفل می‌شود — چون صف میکروتسک‌ها هیچ‌وقت خالی نمی‌شود تا نوبت به رندر برسد. کارهای سنگین محاسباتی را هم در Thread اصلی نگذار؛ Web Worker یا chunking با setTimeout راه‌حل‌های استانداردند."}]'::jsonb, '[{"q":"Promise.all با یکی از Promiseهای reject شده چه می‌کند؟","opts":["بقیه را ادامه می‌دهد","بلافاصله کل نتیجه reject می‌شود","undefined برمی‌گرداند","خطای syntax می‌دهد"],"ans":1,"why":"Promise.all همه‌یا‌هیچ است؛ برای تحمل شکستِ بخشی از کارها از Promise.allSettled استفاده کن."},{"q":"چرا جاوااسکریپت با وجود Event Loop گاهی «گیر» می‌کند؟","opts":["چون چندرشته‌ای است","چون کد همگامِ سنگین، پشته را اشغال می‌کند","چون Promiseها کندند","گیر نمی‌کند"],"ans":1,"why":"Event Loop فقط وقتی نوبت می‌گیرد که پشته خالی باشد؛ یک حلقه سنگین همگام، کل رابط کاربری را فریز می‌کند."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('c9-l1', 'react', 'کامپوننت و JSX؛ ذهنیت React', 50, 9, '[{"k":"p","t":"React صفحه را درختی از کامپوننت‌ها می‌بیند؛ هر کامپوننت تابعی است که props می‌گیرد و JSX برمی‌گرداند. JSX نه HTML است نه رشته — توصیفی از UI است که کامپایلر آن را به فراخوانی تابع تبدیل می‌کند. قانون طلایی: کامپوننت باید خالص باشد؛ همان ورودی، همان خروجی."},{"k":"code","lang":"jsx","title":"App.jsx","code":"function Badge({ children, color = \"teal\" }) {\n    return (\n        <span className={`badge badge-${color}`}>\n            {children}\n        </span>\n    );\n}\n\nfunction CourseCard({ course }) {\n    return (\n        <article className=\"card\">\n            <h3>{course.title}</h3>\n            <Badge color=\"amber\">{course.level}</Badge>\n            <p>{course.summary}</p>\n        </article>\n    );\n}\n\nexport default function App() {\n    return courses.map(c => <CourseCard key={c.id} course={c} />);\n}"},{"k":"def","term":"key","t":"شناسه‌ای که به React می‌گوید کدام آیتم کدام است؛ بدون key درست، React نمی‌فهمد کدام آیتم حذف یا جابه‌جا شده و State آیتم‌ها قاطی می‌شود. هرگز از اندیس آرایه برای لیست‌های تغییرپذیر استفاده نکن."},{"k":"warn","title":"خلوص کامپوننت","t":"در بدنه کامپوننت هرگز داده را mutate نکن، درخواست شبکه نزن و تاریخ/تصادفی را مستقیم نخوان. این کارها باید در Event Handlerها یا useEffect انجام شوند — وگرنه رندرهای غیرقابل‌پیش‌بینی خواهی داشت."},{"k":"tip","title":"نکته منتور","t":"قبل از نوشتن کد، UI را روی کاغذ به جعبه‌های تو در تو تقسیم کن و نام بگذار. این طراحی ۵ دقیقه‌ای، ساختار props و State را قبل از کد مشخص می‌کند."},{"k":"h","t":"عمیق‌تر: Reconciliation — چرا React «فکر می‌کند» قبل از اینکه بنویسد"},{"k":"p","t":"نوشتن مستقیم DOM کند و پر از باگ است چون «وضعیت» را پخش می‌کند: ده جای کد، ده جا درخت را عوض می‌کنند و کسی نمی‌داند صفحه الان واقعاً چه وضعیتی دارد. انقلاب React یک معادله ساده بود: UI = f(state). تو فقط وضعیت را توصیف می‌کنی؛ React نسخه مجازی و سبکی از درخت (Virtual DOM) می‌سازد، با نسخه قبلی مقایسه می‌کند (Diff)، و فقط تفاوت‌ها را به DOM واقعی می‌نویسد. نتیجه: ذهن تو روی «داده» متمرکز می‌ماند و هماهنگی UI، مسئله سیستم می‌شود نه مسئله تو. این «اعلانی» (Declarative) بودن، همان چیزی است که توسعه رابط کاربری را از هنرِ حالت‌داری به مهندسی تبدیل کرد."},{"k":"p","t":"کلیدها (keys) را هیچ‌وقت جدی نگیر یعنی Diff را کور کنی: React برای تشخیص اینکه «کدام عنصر همان عنصر قبلی است» در لیست‌ها، به key نگاه می‌کند. ایندکس آرایه به‌عنوان key وقتی داده‌ها حذف/جابه‌جا می‌شوند فاجعه می‌سازد — state هر ردیف به ردیف اشتباه می‌چسبد و باگ‌هایی می‌بینی که فقط «گاهی» رخ می‌دهند. key باید هویت پایدار داده باشد (id دیتابیس). و یک‌طرفه‌بودن جریان داده را هم جدی بگیر: داده از والد به فرزند پایین می‌آید (props) و رویدادها بالا می‌روند (callback) — به محض اینکه بخواهی این جهت را بشکنی، داری با فریم‌ورک می‌جنگی و حالت Lifting لازم است."},{"k":"code","lang":"tsx","title":"deepdive-keys.tsx","code":"// ❌ ایندکس به‌عنوان key — با حذف آیتم، stateها جابه‌جا می‌شوند\n{todos.map((todo, i) => <TodoRow key={i} todo={todo} />)}\n\n// ✓ هویت پایدار — هر ردیف، خودش می‌ماند\n{todos.map((todo) => <TodoRow key={todo.id} todo={todo} />)}\n\n// جریان یک‌طرفه + بالا بردن state:\nfunction TodoApp() {\n  const [todos, setTodos] = useState<Todo[]>([]);\n\n  const addTodo = (text: string) =>            // رویداد بالا می‌آید\n    setTodos((prev) => [...prev, makeTodo(text)]);\n\n  return (\n    <>\n      <TodoInput onAdd={addTodo} />            {/* داده/رفتار پایین می‌رود */}\n      <TodoList todos={todos} />\n    </>\n  );\n}\n// TodoInput خودش state ندارد — «کنترل‌شده» است؛\n// حقیقت واحد در TodoApp زندگی می‌کند و باگ sync وجود ندارد."},{"k":"p","t":"JSX هم که اول عجیب به‌نظر می‌رسد، در واقع کامپایل می‌شود به فراخوانی‌های تابع — و این یعنی دو نتیجه مهم: اول، هر جا بتوانی تابع بنویسی می‌توانی UI بسازی (map برای لیست‌ها، && برای شرط‌ها، متغیر برای بخش‌بندی)؛ دوم، کامپوننت فقط یک تابع است و همه ابزارهای جاوااسکریپت — ترکیب، انتزاع، تایپ — رویش کار می‌کنند. به همین دلیل الگوی «کامپوننت کوچک» در React جواب می‌دهد: کامپوننت رایگان است، پس بی‌رحمانه بشکن — هر بلوک بصری که نامی دارد، شایسته کامپوننت خودش است."},{"k":"tip","title":"نکته منتور","t":"قبل از نوشتن هر صفحه در React، سه دقیقه روی کاغذ انجام بده: ۱) مرز کامپوننت‌ها را دور بخش‌های بصری بکش، ۲) داده هر بخش را مشخص کن، ۳) state مشترک را به «نزدیک‌ترین جد مشترک» ببر. این سه قدم، همان متدولوژی رسمی «Thinking in React» است و ساختن UI را از آزمون‌وخطا نجات می‌دهد."}]'::jsonb, '[{"q":"چرا از اندیس آرایه به‌عنوان key در لیست‌های تغییرپذیر نباید استفاده کرد؟","opts":["کند است","با حذف/جابجایی، State آیتم‌های اشتباه به هم وصل می‌شود","کامپایل نمی‌شود","React اجازه نمی‌دهد"],"ans":1,"why":"اندیس به موقعیت می‌چسبد نه به هویت؛ وقتی آیتمی حذف شود، State آیتم بعدی به اشتباه جابه‌جا می‌شود."},{"q":"کامپوننت «خالص» یعنی چه؟","opts":["بدون props","همان ورودی، همیشه همان خروجی و بدون اثر جانبی","فقط HTML برگرداند","بدون className"],"ans":1,"why":"خلوص یعنی بدنه کامپوننت چیزی جز محاسبه UI انجام ندهد؛ اثرات جانبی به Event Handler و useEffect منتقل می‌شوند."}]'::jsonb),
('c9-l2', 'react', 'State؛ قلب تپنده React', 65, 10, '[{"k":"p","t":"State داده‌ای است که با گذر زمان تغییر می‌کند و UI باید به آن واکنش نشان دهد. وقتی setState صدا زده می‌شود، React دوباره کامپوننت را رندر می‌کند — اما نه کل صفحه؛ با مقایسه درخت مجازی (Virtual DOM) فقط بخش‌های تغییریافته را به‌روز می‌کند."},{"k":"code","lang":"jsx","title":"Counter.jsx","code":"import { useState } from \"react\";\n\nexport function Counter() {\n    const [count, setCount] = useState(0);\n\n    // فرم تابعی: همیشه از آخرین state مطمئن باش\n    const bump = () => setCount(c => c + 1);\n\n    return (\n        <div>\n            <p>Count: {count}</p>\n            <button onClick={() => { bump(); bump(); }}>\n                +2\n            </button>\n        </div>\n    );\n}"},{"k":"warn","title":"تله state قدیمی","t":"setCount(count + 1) دو بار پشت‌سرهم فقط یکی اضافه می‌کند! چون هر دو فراخوانی count یکسانی را می‌بینند. فرم تابعی setCount(c => c + 1) همیشه روی آخرین مقدار اعمال می‌شود و راه‌حل است."},{"k":"h","t":"جریان داده یک‌طرفه"},{"k":"p","t":"در React داده از بالا به پایین می‌رود (props) و رویدادها از پایین به بالا می‌آیند (callback). اگر دو کامپوننت هم‌سطح به یک state نیاز دارند، آن را به نزدیک‌ترین والد مشترک بالا ببر — الگویی که به Lifting State Up معروف است."},{"k":"code","lang":"jsx","title":"search.jsx","code":"function SearchBox({ value, onChange }) {\n    return <input value={value} onChange={e => onChange(e.target.value)} />;\n}\n\nfunction ResultList({ query }) {\n    const results = courses.filter(c => c.title.includes(query));\n    return <ul>{results.map(c => <li key={c.id}>{c.title}</li>)}</ul>;\n}\n\nexport function Search() {\n    const [query, setQuery] = useState(\"\");   // state در والد مشترک\n    return (\n        <div>\n            <SearchBox value={query} onChange={setQuery} />\n            <ResultList query={query} />\n        </div>\n    );\n}"},{"k":"h","t":"عمیق‌تر: State، Batch و به‌روزرسانی تابعی"},{"k":"p","t":"setState مثل بقیه توابع، همزمان اجرا نمی‌شود؛ React چند به‌روزرسانی را جمع می‌کند (Batching) و یک‌بار رندر می‌کند — برای سرعت. نتیجه‌اش تله‌ای است که همه می‌افتند: دو بار پشت‌سرهم setCount(count + 1) بنویسی، count فقط یکی زیاد می‌شود، چون هر دو از «همان snapshot قدیمی» خوانده‌اند. درمان، فرم تابعی است: setCount(c => c + 1) — یعنی «هر موقع خواستی اعمال کنی، از آخرین مقدار شروع کن». قانون: هر وقت مقدار جدید از مقدار قبلی محاسبه می‌شود، همیشه فرم تابعی بنویس؛ حتی اگر فعلاً یک‌بار است — چون فردا دومی اضافه می‌شود و باگش فقط شب‌های پرترافیک ظاهر می‌شود."},{"k":"p","t":"State در React تغییرناپذیر است — نه به‌خاطر سخت‌گیری، به‌خاطر ریاضیات: React برای فهمیدن «چه چیزی تغییر کرد» فقط مرجع‌ها را مقایسه می‌کند (Object.is). اگر آبجکت را مستقیم mutate کنی، مرجع عوض نمی‌شود و React اصلاً نمی‌فهمد اتفاقی افتاده — رندری در کار نیست و ساعت‌ها دیباگ می‌کنی. پس همه به‌روزرسانی‌ها «ساختن نسخه جدید» است: {...obj, field: value} برای آبجکت، [...arr, item] و arr.filter/map برای آرایه. و وقتی state پیچیده شد (چند فیلد با تغییرات وابسته)، useReducer با actionهای نام‌دار، منطق را از کامپوننت بیرون می‌کشد و تست‌پذیرش می‌کند — دقیقاً مثل Redux ولی محلی."},{"k":"code","lang":"tsx","title":"deepdive-state.tsx","code":"// ❌ تله snapshot قدیمی:\nonClick={() => {\n  setCount(count + 1);\n  setCount(count + 1);    // هنوز همان count قدیمی!\n}}\n// نتیجه: +1 به‌جای +2\n\n// ✓ فرم تابعی:\nonClick={() => {\n  setCount((c) => c + 1);\n  setCount((c) => c + 1);  // از نتیجه قبلی شروع می‌کند → +2\n}}\n\n// ✓ تغییرناپذیری — نسخه جدید بساز، قدیمی را دست نزن:\nconst addItem = (item: Item) =>\n  setCart((prev) => [...prev, item]);\n\nconst updateQty = (id: number, qty: number) =>\n  setCart((prev) =>\n    prev.map((it) => (it.id === id ? { ...it, qty } : it)));\n\n// useReducer برای state چندبخشی:\nconst [form, dispatch] = useReducer(formReducer, initialForm);\ndispatch({ type: ''SET_FIELD'', field: ''email'', value });\ndispatch({ type: ''RESET'' });\n// منطق تغییرات در formReducer است — خالص، خوانا، تست‌پذیر"},{"k":"table","head":["وضعیت","ابزار درست"],"rows":[["یک مقدار مستقل","useState"],["چند مقدار که با هم تغییر می‌کنند","یک useState با آبجکت یا useReducer"],["منطق تغییر پیچیده/چند action","useReducer (تست‌پذیر و قابل‌ردیابی)"],["داده از سرور","React Query — اصلاً state محلی نیست!"],["فرم بزرگ","React Hook Form — state را از رندر خارج می‌کند"]]},{"k":"warn","title":"State اشتباه","t":"قبل از ساختن هر useState بپرس: آیا این واقعاً state است؟ اگر از props قابل‌محاسبه است، اگر از داده سرور قابل‌استخراج است، یا اگر می‌شود هنگام رویداد محاسبه‌اش کرد — state نساز. «State مشتقی» بزرگ‌ترین منبع باگ‌های sync در React است: دو منبع حقیقت که بالاخره یک روز با هم دعوا می‌کنند."}]'::jsonb, '[{"q":"چرا setCount(c => c + 1) مطمئن‌تر از setCount(count + 1) است؟","opts":["سریع‌تر است","روی آخرین مقدار اعمال می‌شود نه مقدار قدیمیِ closure","دو بار اعمال می‌شود","رندر را حذف می‌کند"],"ans":1,"why":"فرم تابعی یک صف است؛ React هر به‌روزرسانی را روی نتیجه قبلی اعمال می‌کند، پس حتی چند فراخوانی متوالی درست جمع می‌شوند."},{"q":"وقتی دو کامپوننت هم‌سطح به یک داده نیاز دارند، state کجا می‌رود؟","opts":["در یکی از آن‌ها","نزدیک‌ترین والد مشترک","در سراسری‌ترین نقطه","در هر دو"],"ans":1,"why":"Lifting State Up: state به والد مشترک می‌رود و با props پایین می‌آید — کمترین سطح ممکن، نه الزاماً Context."}]'::jsonb),
('c9-l3', 'react', 'useEffect و رندر کارآمد', 70, 11, '[{"k":"p","t":"هر چیزی که «اثر جانبی» است — درخواست شبکه، اشتراک، تایمر، تغییر document — جای useEffect است. اما useEffect چاقوی دو لبه است؛ بیشتر باگ‌های «حلقه بی‌نهایت رندر» از آرایه وابستگی اشتباه می‌آید."},{"k":"code","lang":"jsx","title":"useEffect.jsx","code":"import { useEffect, useState } from \"react\";\n\nexport function UserPage({ userId }) {\n    const [user, setUser] = useState(null);\n\n    useEffect(() => {\n        let alive = true;\n        fetch(`/api/users/${userId}`)\n            .then(r => r.json())\n            .then(data => { if (alive) setUser(data); });\n\n        // Cleanup: اگر کامپوننت پرید یا userId عوض شد\n        return () => { alive = false; };\n    }, [userId]);   // فقط وقتی userId تغییر کند\n\n    return user ? <h1>{user.name}</h1> : <p>Loading...</p>;\n}"},{"k":"table","head":["آرایه وابستگی","رفتار"],"rows":[["[]","فقط یک بار بعد از mount"],["[a, b]","وقتی a یا b تغییر کند"],["(نباشد)","بعد از هر رندر — تقریباً همیشه اشتباه"]]},{"k":"h","t":"رندر کمتر، نه زودتر"},{"k":"list","items":["React.memo کامپوننتی که props یکسان دارد را دوباره رندر نمی‌کند","useMemo نتیجه محاسبات سنگین را کش می‌کند","useCallback هویت تابع را بین رندرها ثابت نگه می‌دارد","لیست‌های بزرگ را Virtualize کن (فقط آیتم‌های قابل‌دیدن رندر شوند)"]},{"k":"warn","title":"اشتباه کلاسیک","t":"ساخت آبجکت یا آرایه داخل JSX و پاس‌دادن آن به کامپوننت memo‌شده، memo را بی‌اثر می‌کند؛ چون هویت آبجکت هر رندر عوض می‌شود. آبجکت‌ها را با useMemo بساز."},{"k":"tip","title":"نکته منتور","t":"قبل از هر بهینه‌سازی، با React DevTools Profiler ببین چه چیزی واقعاً زیاد رندر می‌شود. ۹۰٪ «مشکلات کارایی» اصلاً وجود ندارند و ۱۰٪ بقیه معمولاً با بالا بردن state حل می‌شوند نه memo."},{"k":"h","t":"عمیق‌تر: useEffect بدون اشک — سه قانون و یک مدل ذهنی"},{"k":"p","t":"useEffect را نه به‌عنوان «جایی که کد اجرا می‌شود»، که به‌عنوان «همگام‌سازی React با دنیای بیرون» ببین: subscribe به WebSocket، عنوان سند، تایمر، درخواست شبکه — چیزهایی که خارج از مدل UI اتفاق می‌افتند. با این مدل ذهنی، سه قانون خودش را توجیه می‌کند: ۱) هر effect مسئول یک همگام‌سازی است؛ ۲) آرایه وابستگی یعنی «وقتی این‌ها عوض شدند، دوباره همگام کن»؛ ۳) اگر effect منبعی باز کرد (اتصال، تایمر، listener)، باید تابع cleanup برگرداند که آن را ببندد — چون قبل از اجرای دوباره و هنگام unmount، React همان cleanup را صدا می‌زند. Memory Leak در React تقریباً همیشه یعنی cleanup فراموش‌شده."},{"k":"p","t":"آرایه وابستگی قرارداد صداقت است: هر متغیری از scope کامپوننت که effect می‌خواند، باید در آرایه باشد — حذفش با کامنت eslint-disable یعنی ساختن باگی که امروز کار می‌کند و سه ماه بعد با داده‌ای متفاوت منفجر می‌شود. وابستگی خالی [] یعنی «فقط هنگام mount» — و اگر state‌ای را می‌خواند ولی در آرایه نیست، همیشه مقدار اولیه‌اش را می‌بیند (تله کلاسیک closure قدیمی). و حقیقتی که دیر یا زود می‌فهمی: بسیاری از useEffectها اصلاً لازم نیستند — محاسبات مشتقی را وسط رندر انجام بده و اثرات جانبی را به Event Handlerها ببر؛ «شاید useEffect لازم باشد» خودش اولین نشانه است که شاید لازم نباشد."},{"k":"code","lang":"tsx","title":"deepdive-effect.tsx","code":"// ✓ الگوی کامل: همگام‌سازی + cleanup + وابستگی درست\nfunction useRoomStatus(roomId: string) {\n  const [online, setOnline] = useState(0);\n\n  useEffect(() => {\n    const ws = new WebSocket(`/ws/rooms/${roomId}`);\n    ws.onmessage = (msg) => setOnline(JSON.parse(msg.data).count);\n\n    return () => ws.close();   // cleanup: بستن اتصال قدیمی\n    // اگر نباشد: هر تغییر roomId یک socket زامبی می‌سازد!\n  }, [roomId]);                // وابستگی: roomId استفاده شده ✓\n\n  return online;\n}\n\n// ❌ تله closure قدیمی:\nuseEffect(() => {\n  const id = setInterval(() => setCount(count + 1), 1000);\n  return () => clearInterval(id);\n}, []);                        // count حذف شده → همیشه 0+1!\n\n// ✓ درمان — یا وابستگی، یا فرم تابعی:\nuseEffect(() => {\n  const id = setInterval(() => setCount((c) => c + 1), 1000);\n  return () => clearInterval(id);\n}, []);                        // حالا درست: از آخرین مقدار می‌خواند"},{"k":"p","t":"وقتی یک effect را در دو کامپوننت کپی کردی، زمان ساخت Custom Hook است — همان تابع‌های معمولی که با use شروع می‌شوند و می‌توانند Hook صدا بزنند. useDebounce، useLocalStorage، useFetch، useOnlineStatus — این‌ها بلوک‌های سازنده واقعی React مدرن‌اند: منطقِ حالت‌دارِ تست‌شده که یک‌بار نوشته و همه‌جا مصرف می‌شود، بدون اینکه کامپوننت‌ها به هم گره بخورند. کتابخانه‌های بزرگ مثل TanStack Query در واقع چیزی جز مجموعه‌ای از Custom Hookهای بسیار مهندسی‌شده نیستند."},{"k":"tip","title":"نکته منتور","t":"React.StrictMode در توسعه، هر effect را عمداً دو بار اجرا می‌کند (mount → unmount → mount) تا effectهای بدون cleanup را لو بدهد. اگر چیزی در StrictMode دو بار اتفاق می‌افتد، کدت باگ دارد نه React — این بهترین معلم رایگانِ cleanup درست است؛ هرگز خاموشش نکن."}]'::jsonb, '[{"q":"اگر آرایه وابستگی useEffect فراموش شود چه می‌شود؟","opts":["فقط یک بار اجرا می‌شود","بعد از هر رندر اجرا می‌شود","هرگز اجرا نمی‌شود","کامپایلر خطا می‌دهد"],"ans":1,"why":"بدون آرایه وابستگی، React دلیلی برای اجرا نکردن ندارد؛ اثر بعد از هر رندر تکرار می‌شود و اگر state را تغییر دهد، حلقه بی‌نهایت می‌سازد."},{"q":"چرا آبجکت ساخته‌شده داخل رندر، React.memo را بی‌اثر می‌کند؟","opts":["چون بزرگ است","چون هویت مرجع آن هر رندر عوض می‌شود","چون memo فقط برای عدد کار می‌کند","بی‌اثر نمی‌کند"],"ans":1,"why":"memo با مقایسه سطحی props کار می‌کند؛ {} !== {} چون دو مرجع متفاوت‌اند. با useMemo هویت را ثابت نگه دار."}]'::jsonb),
('react-x1', 'react', 'مدیریت State سراسری — فراتر از useState', 55, 12, '[{"k":"p","t":"وقتی اپلیکیشن رشد می‌کند، داده‌هایی پیدا می‌شوند که مالِ هیچ کامپوننت خاصی نیستند: کاربر لاگین‌شده، سبد خرید، تم صفحه. پاس‌دادن این‌ها با props از ده سطح رد می‌شود (Prop Drilling) — بوی بدی که معماری State سراسری حلش می‌کند."},{"k":"code","lang":"tsx","title":"context.tsx","code":"import { createContext, useContext, useState } from ''react'';\n\nconst CartContext = createContext<{\n  items: string[];\n  add: (item: string) => void;\n} | null>(null);\n\nexport function CartProvider({ children }: { children: React.ReactNode }) {\n  const [items, setItems] = useState<string[]>([]);\n  const add = (item: string) => setItems((prev) => [...prev, item]);\n  return (\n    <CartContext.Provider value={{ items, add }}>\n      {children}\n    </CartContext.Provider>\n  );\n}\n\nexport function useCart() {\n  const ctx = useContext(CartContext);\n  if (!ctx) throw new Error(''useCart باید داخل CartProvider باشد'');\n  return ctx;\n}"},{"k":"code","lang":"tsx","title":"استفاده در هر عمقی","code":"function ProductCard({ name }: { name: string }) {\n  const { add } = useCart();          // بدون هیچ props!\n  return (\n    <div>\n      <h3>{name}</h3>\n      <button onClick={() => add(name)}>افزودن به سبد</button>\n    </div>\n  );\n}\n\nfunction CartBadge() {\n  const { items } = useCart();\n  return <span className=\"badge\">{items.length}</span>;\n}"},{"k":"table","head":["راه‌حل","کی استفاده کنیم","هزینه"],"rows":[["Context + useReducer","داده کم‌تغییر: تم، زبان، کاربر لاگین","تغییر Context همه مصرف‌کننده‌ها را رندر می‌کند"],["Zustand","State سراسری واقعی با آپدیت مکرر","کتابخانه سبک (~۱KB)، API ساده"],["React Query / TanStack","داده سرور: کش، همگام‌سازی، بارگذاری مجدد","الزامی برای هر اپی که با API حرف می‌زند"],["Redux Toolkit","اپ‌های بزرگ با نیاز به DevTools و Middleware","سربار Boilerplate؛ فقط وقتی واقعاً لازم است"]]},{"k":"def","term":"Prop Drilling","t":"وقتی داده از پنج سطح کامپوننت فقط عبور می‌کند تا به مصرف‌کننده برسد. نشانه‌اش: propsهایی که هیچ‌جا استفاده نمی‌شوند جز پاس‌دادن. درمان: Context برای داده پایدار، Zustand/React Query برای داده پویا — یا اصلاً State را به پایین‌ترین جد مشترک برگردان."},{"k":"warn","title":"Context جای Redux نیست","t":"هر بار تغییر مقدار Context، همه کامپوننت‌های مصرف‌کننده دوباره رندر می‌شوند — حتی آن‌هایی که فقط یک فیلد را می‌خوانند. برای سبد خریدی که ثانیه‌ای تغییر می‌کند، Zustand انتخاب مهندسی است؛ Context را برای چیزهایی که روزی یک‌بار عوض می‌شوند نگه دار."},{"k":"tip","title":"نکته منتور","t":"قبل از هر کتابخانه بپرس: آیا این داده واقعاً سراسری است یا فقط ساختار کامپوننت‌هایم بد است؟ خیلی از Prop Drillingها با جابه‌جایی State به جد مشترک و استفاده از Composition (children) حل می‌شوند — بدون یک خط کتابخانه."}]'::jsonb, '[{"q":"Prop Drilling یعنی چه و چرا بد است؟","opts":["استفاده زیاد از props — چون تایپ بیشتر می‌شود","عبور داده از سطح‌هایی که مصرفش نمی‌کنند — چون تغییر ساختار را سخت و کد را شکننده می‌کند","خطای runtime","نوعی Hook"],"ans":1,"why":"وقتی کامپوننت میانی فقط حامل است، هر تغییر در شکل داده باید در همه سطح‌ها اعمال شود؛ و تست هر سطح نیاز به props ساختگی دارد."},{"q":"کجا Context کافی نیست و باید سراغ Zustand رفت؟","opts":["وقتی داده سراسری مکرر تغییر می‌کند و رندر اضافی Context هزینه دارد","هرجا State داریم","وقتی داده سرور است","هیچ‌وقت"],"ans":0,"why":"Context در تغییر، همه مصرف‌کننده‌ها را رندر می‌کند؛ Zustand با subscribe انتخابی فقط کامپوننت‌هایی را رندر می‌کند که دقیقاً آن تکه داده را می‌خوانند."}]'::jsonb),
('react-x2', 'react', 'کارایی React — memo، Profiler و جنگ رندرهای بیهوده', 55, 13, '[{"k":"p","t":"رندر شدن در React ارزان است — Virtual DOM فقط محاسبه می‌کند؛ ولی وقتی کامپوننتی هزاران بار بیهوده رندر شود، جمعش سنگین می‌شود. قبل از هر بهینه‌سازی، قانون اول: اندازه بگیر. React DevTools Profiler را باز کن، یک عمل کاربر را ضبط کن و ببین چه کسی چند بار رندر شد — ۹۰٪ «مشکلات کارایی» اصلاً وجود ندارند و ۱۰٪ واقعی هم معمولاً یک رندر سنگین در جای مشخص‌اند، نه هزار رندر پخش. memo و useMemo را قبل از اندازه‌گیری نزن؛ هر کدام هزینه مقایسه خودشان را دارند و برای کامپوننت‌های سبک، خالص ضررند."},{"k":"code","lang":"tsx","title":"render-storm.tsx","code":"// ❌ طوفان رندر: هر تایپ در جست‌وجو، کل لیست ۵۰۰ ردیفی رندر می‌شود\nfunction Page() {\n  const [query, setQuery] = useState('''');\n  const rows = data.filter(...);          // هر رندر، دوباره محاسبه\n  return (\n    <>\n      <input value={query} onChange={(e) => setQuery(e.target.value)} />\n      <BigTable rows={rows} />            {/* ۵۰۰ رندر به‌ازای هر حرف! */}\n    </>\n  );\n}\n\n// ✓ درمان اول: محاسبه فقط وقتی ورودی‌اش عوض شد\nconst rows = useMemo(() => data.filter(...), [data]);\n\n// ✓ درمان دوم: کامپوننت فقط وقتی props عوض شد رندر شود\nconst BigTable = memo(function BigTable({ rows }) {\n  return <table>{rows.map(...)}</table>;\n});\n\n// ⚠ ولی memo با callback جدید هر رندر باطل می‌شود:\n<Row onSelect={() => select(id)} />      {/* هر رندر تابع تازه! */}\nconst onSelect = useCallback(select, []); // ← حالا مرجع ثابت است\n<Row onSelect={onSelect} />"},{"k":"p","t":"ولی قوی‌ترین بهینه‌سازی React اصلاً memo نیست — «ساختار» است: State را تا جایی که می‌شود پایین ببر (State جست‌وجو مالِ کامپوننت جست‌وجوست، نه کل صفحه)؛ بخش‌های پرتغییر را از بخش‌های گران ایزوله کن (Composition: children از بیرون می‌آیند و با رندر داخلی دوباره ساخته نمی‌شوند)؛ و لیست‌های بزرگ را Virtualize کن (فقط ردیف‌های دیده‌شده در DOM باشند — react-window). این سه تغییر ساختاری، معمولاً ده برابر همه memoهای دنیا اثر دارند و کد را هم ساده‌تر می‌کنند نه پیچیده‌تر."},{"k":"code","lang":"tsx","title":"composition-wins.tsx","code":"// ❌ هر تیکِ ساعت، گراف سنگین هم رندر می‌شود\nfunction Dashboard() {\n  const [now, setNow] = useState(Date.now());\n  useEffect(() => { const t = setInterval(() => setNow(Date.now()), 1000);\n                    return () => clearInterval(t); }, []);\n  return (\n    <>\n      <Clock now={now} />        {/* سبک — باید هر ثانیه رندر شود */}\n      <HeavyChart data={data} /> {/* سنگین — چرا باید رندر شود؟ */}\n    </>\n  );\n}\n\n// ✓ جداسازی: رندرِ ثانیه‌ای فقط Clock را لمس می‌کند\nfunction Dashboard() {\n  return (\n    <>\n      <Ticker>                   {/* State داغ این‌جاست */}\n        <Clock />\n      </Ticker>\n      <HeavyChart data={data} /> {/* دیگر هرگز بی‌دلیل رندر نمی‌شود */}\n    </>\n  );\n}"},{"k":"table","head":["ابزار","مسئله‌اش","کی بزنیم"],"rows":[["ساختار (State پایین/ایزوله)","رندر بیهوده از اساس","همیشه — اول از همه"],["Virtualization","لیست‌های بلند","هر لیست بالای ~۱۰۰ ردیف"],["memo","کامپوننت گران با props پایدار","بعد از اثبات مشکل در Profiler"],["useMemo/useCallback","ورودی‌های memo یا محاسبات گران","فقط جایی که اندازه‌گیری نشان داده"],["Transition (useTransition)","UI حین کار سنگین قفل می‌شود","جست‌وجو/فیلتر همزمان با رندر بزرگ"]]},{"k":"warn","title":"بت‌سازی memo","t":"پروژه‌هایی که هر کامپوننتشان memo و هر تابعشان useCallback دارد، معمولاً هم کندترند (هزاران مقایسه بیهوده در هر رندر) و هم خوانایی‌شان قربانی شده. memo پیش‌فرض نیست — نسخه است. و اگر memo گذاشتی ولی اثر نکرد، اول وابستگی‌هایش را چک کن: آبجکت یا تابع تازه‌ساز در props، هر رندر مرجع را عوض می‌کند و memo را باطل."},{"k":"tip","title":"نکته منتور","t":"یک بازی آموزشی عالی: Profiler را باز کن و «highlight updates» را روشن کن — بعد در اپت کلیک کن و ببین چه چیزهایی چشمک می‌زنند. جایی که چشمک نباید باشد، درس امروز شروع می‌شود. این دیدنِ رندر، مهارتی است که مصاحبه‌های «چرا اپ کند است» را یک‌جا حل می‌کند."}]'::jsonb, '[{"q":"چرا memo روی کامپوننتی که callback تازه‌ساز می‌گیرد بی‌اثر است؟","opts":["چون memo خراب است","چون مرجع تابع در هر رندر عوض می‌شود و مقایسه props همیشه «تغییر کرد» می‌گوید — باید useCallback","چون کامپوننت Stateless است","چون React نسخه قدیمی است"],"ans":1,"why":"memo با Object.is مقایسه می‌کند؛ () => {} هر بار تابع جدیدی است. useCallback مرجع را تا وقتی وابستگی‌ها ثابت‌اند، حفظ می‌کند."},{"q":"اولین قدم واقعی برای کارایی React چیست؟","opts":["memo گذاشتن همه‌جا","اندازه‌گیری با Profiler برای یافتن رندرهای واقعاً بیهوده یا سنگین","تغییر کتابخانه","کوچک‌کردن کامپوننت‌ها"],"ans":1,"why":"بدون داده، بهینه‌سازی حدس است — و حدس در React معمولاً memoهای بیهوده تولید می‌کند. Profiler گلوگاه واقعی را در ۳۰ ثانیه نشان می‌دهد."}]'::jsonb),
('react-b1', 'react', 'JSX و قوانین آن', 63, 14, '[{"k":"p","t":"JSX سینتکسی است که شبیه HTML در جاوااسکریپت نوشته می‌شود و به createElement کامپایل می‌شود؛ چند تفاوت مهم با HTML دارد که باید بدانی."},{"k":"h","t":"JSX یعنی چه؛ از <div> تا createElement"},{"k":"p","t":"JSX جاوااسکریپت نیست — یک سینتکس sugar است که بیلدر (Vite/Babel) هر تگ را به یک فراخوانی تبدیل می‌کند: <h2 className=\"card\">{title}</h2> می‌شود createElement(''h2'', { className: ''card'' }, title). نتیجه یک «شیء توصیف UI» است — نه خود DOM. این دیدگاه همه‌چیز را شفاف می‌کند: چرا className (چون شیء props یک شیء جاوااسکریپتی است و class رزرو است)، چرا style شیء است (camelCase چون propertyهای DOM در جاوااسکریپت این‌طورند) و چرا کامپوننت باید با حرف بزرگ شروع شود (وگرنه بیلدر آن را رشته تگ HTML فرض می‌کند نه متغیر کامپوننت). JSX در نهایت یعنی: UI به‌عنوان داده، و داده قابل‌برنامه‌نویسی است."},{"k":"h","t":"قوانین نانوشته‌ای که کد React را تمیز نگه می‌دارند"},{"k":"p","t":"سه قاعده که تازه‌کارها دیر یاد می‌گیرند: اول، Fragment (<>...</>) برای برگرداندن چند عنصر بدون افزودن div بی‌معنی به DOM — div اضافه یعنی لایه بی‌فایده در CSS و صفحه‌خوان. دوم، عبارت‌ها فقط داخل {} — ولی خودِ {} داخل JSX می‌تواند هر چیز جاوااسکریپتی باشد: فراخوانی تابع، ternary، حتی map. سوم و مهم‌تر: JSX باید «خالص» بماند — داخل رندر نباید fetch بزنی، state را عوض کنی یا لاگ سنگین بگذاری؛ رندر فقط باید «توصیف UI از روی داده‌های فعلی» باشد. اثرها (اثرگذاری‌ها) مال useEffect‌اند. این جداسازی توصیف/اثر، قلب مدل ذهنی React است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"tsx","title":"هر سه تفاوت با HTML در یک کامپوننت","code":"function Article({ post }: { post: Post }) {\n  return (\n    <article>\n      <label htmlFor=\"comment\">نظر شما</label>\n      <input id=\"comment\" className=\"field\" />\n      <span style={{ fontWeight: 700 }}>\n        {post.likes.toLocaleString(''fa-IR'')}\n      </span>\n      {post.tags.map(t => <em key={t}>{t}</em>)}\n    </article>\n  );\n}"},{"k":"def","term":"VDOM و توصیف UI","t":"React هرگز مستقیم DOM را نمی‌سازد؛ کامپوننت‌ها «درختی از اشیاء توصیف» برمی‌گردانند و React خودش تفاوت دو توصیف متوالی را حساب و حداقل تغییر واقعی را روی DOM اعمال می‌کند — این لایه واسط است که رندر شرطی و لیست‌ها را ساده می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["class برابر className و for برابر htmlFor است","هر JSX باید یک ریشه داشته باشد یا از Fragment <> </> استفاده کنی","عبارت‌ها داخل {} قرار می‌گیرند و style شیء است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"jsx.tsx","code":"function Card({ title }: { title: string }) {\n  return (\n    <>\n      <h2 className=\"card\">{title}</h2>\n      <p style={{ color: ''teal'' }}>{2 + 2}</p>\n    </>\n  );\n}"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: class برابر className و for برابر htmlFor است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا در JSX از className استفاده می‌شود؟","opts":["قشنگ‌تر است","چون class در جاوااسکریپت کلمه رزرو است","اجباری نیست","برای CSS است"],"ans":1,"why":"JSX در واقع جاوااسکریپت است و class رزرو شده؛ پس React از className استفاده می‌کند."},{"q":"چرا کامپوننت باید با حرف بزرگ شروع شود؟","opts":["سلیقه است","چون بیلدر تگ‌های کوچک را عنصر HTML و بزرگ‌ها را متغیر کامپوننت فرض می‌کند؛ lowercase یعنی <MyCard/> به‌جای کامپوننت، تگ mycard می‌شود","برای CSS","اجباری نیست"],"ans":1,"why":"قانون تفکیک بیلدر: تگ‌های built-in کوچک‌اند، کامپوننت‌ها بزرگ. بدون این، React نمی‌داند منظورت عنصر است یا تابع."},{"q":"Fragment (<>...</>) چه مشکلی را حل می‌کند؟","opts":["سرعت رندر","برگرداندن چند عنصر بدون افزودن گره بی‌معنی به DOM که CSS و صفحه‌خوان را خراب می‌کند","خطای TypeScript","state"],"ans":1,"why":"React هر کامپوننت را یک ریشه می‌خواهد؛ div اضافه سلسله‌مراتب CSS و Landmarkها را آلوده می‌کند. Fragment ریشه می‌سازد ولی در DOM نامرئی است."}]'::jsonb),
('react-b2', 'react', 'Props و جریان داده یک‌طرفه', 63, 15, '[{"k":"p","t":"Props ورودی‌های فقط‌خواندنی یک کامپوننت‌اند و داده در React همیشه از پدر به فرزند جاری است؛ فرزند برای تغییر، تابعی را از پدر صدا می‌زند."},{"k":"h","t":"چرا جریان یک‌طرفه، دیباگ را ممکن می‌کند"},{"k":"p","t":"در فریم‌ورک‌های قدیمی‌تر با اتصال دوطرفه (two-way binding)، داده بین اجزا آزادانه شناور بود و وقتی چیزی اشتباه نمایش داده می‌شد، معلوم نبود از کجا آمده. React قرارداد سفتی گذاشت: داده فقط پایین می‌رود (پدر به فرزند با props) و رویدادها فقط بالا می‌آیند (فرزند handler پدر را صدا می‌زند). نتیجه: هر مقدار را که روی صفحه می‌بینی، می‌دانی دقیقاً از state کدام جد آمده — یک مسیر مستقیم و قابل‌ردیابی. این «پیش‌بینی‌پذیری» ویژگی تزئینی نیست: در اپ‌های بزرگ، قابلیتِ «دیدن جریان داده در یک نگاه» همان چیزی است که DevToolsها و Time-Travel Debugging را ممکن می‌کند."},{"k":"h","t":"الگوی Callback؛ وقتی فرزند خبر می‌دهد"},{"k":"p","t":"فرزند نمی‌تواند (و نباید) state پدر را مستقیم عوض کند؛ قرارداد این است: پدر یک تابع می‌سازد که state خودش را تغییر می‌دهد، آن را به‌عنوان prop به فرزند می‌دهد و فرزند در لحظه درست صدایش می‌زند. مثل دکمه‌ای که نمی‌داند چه می‌کند — فقط خبر می‌دهد «فشرده شدم». این الگو سه برد دارد: منطق تغییر در یک‌جا می‌ماند (تست‌پذیر)، فرزند قابل‌استفاده‌مجدد می‌شود (چون به منطق خاصی وابسته نیست) و چند فرزند می‌توانند روی یک state اثر بگذارند بدون اینکه از هم خبر داشته باشند. وقتی این الگو را بدانی، Context و Redux فقط تعمیم همین ایده‌اند برای فاصله‌های دورتر."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"tsx","title":"رویداد بالا می‌رود، داده پایین می‌آید","code":"function Stepper({ value, onChange }: {\n  value: number; onChange: (v: number) => void;\n}) {\n  return (\n    <div>\n      <button onClick={() => onChange(value - 1)}>-</button>\n      <span>{value}</span>\n      <button onClick={() => onChange(value + 1)}>+</button>\n    </div>\n  );\n}\n\nfunction App() {\n  const [qty, setQty] = useState(1);\n  // Stepper از qty خبر ندارد؛ فقط می‌گوید «کم/زیاد کن»\n  return <Stepper value={qty} onChange={setQty} />;\n}"},{"k":"warn","title":"دام رایج","t":"تغییر مستقیم props در فرزند (مثل props.list.push(...)) — props فقط‌خواندنی‌اند؛ حتی اگر «کار کند»، پدر از تغییر خبر ندارد و رندر نمی‌شود. همیشه تغییر را به صاحب داده (پدر) بسپار."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["props را هرگز تغییر نده — فقط‌خواندنی‌اند","برای ارتباط فرزند→پدر، handler از پدر پاس بده","children خاص‌ترین prop است که محتوای بین تگ‌هاست"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"props.tsx","code":"function Button({ label, onClick }: {\n  label: string; onClick: () => void;\n}) {\n  return <button onClick={onClick}>{label}</button>;\n}\n\nfunction App() {\n  return <Button label=\"بزن\" onClick={() => alert(''!'')} />;\n}"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: props را هرگز تغییر نده — فقط‌خواندنی‌اند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا جریان داده در React یک‌طرفه است؟","opts":["تصادفی","چون پیش‌بینی‌پذیری و دیباگ را ساده می‌کند و تغییرات متمرکز می‌شود","برای سرعت","محدودیت فنی"],"ans":1,"why":"وقتی داده فقط پایین می‌رود، همیشه می‌دانی هر مقدار از کجا آمده و کجا تغییر می‌کند."},{"q":"چرا props فقط‌خواندنی‌اند؟","opts":["محدودیت فنی","چون React برای پیش‌بینی‌پذیری می‌خواهد تغییر فقط از صاحب state بیاید؛ تغییر مستقیم prop یعنی رندرهای گمشده و جریان غیرقابل‌ردیابی","برای سرعت","TypeScript اجازه نمی‌دهد"],"ans":1,"why":"اگر هر فرزندی بتواند ورودی‌اش را عوض کند، «منبع حقیقت» معلوم نیست. فقط‌خواندگی، جریان را یک‌طرفه و قابل‌ردیابی نگه می‌دارد."},{"q":"prop مخصوص children چیست؟","opts":["props.child","هر JSX که بین تگ باز و بسته کامپوننت نوشته شود، به‌عنوان props.children در دسترس است","state.children","وجود ندارد"],"ans":1,"why":"<Card><p>سلام</p></Card> یعنی Card محتوای p را به‌عنوان children می‌گیرد — اساس ساخت کامپوننت‌های قالبی مثل Modal و Layout."}]'::jsonb),
('react-b3', 'react', 'State و رندر مجدد', 63, 16, '[{"k":"p","t":"State داده‌ای است که با تغییرش، کامپوننت دوباره رندر می‌شود. setState همگام نیست و باید با callback یا مقدار جدید کار کنی."},{"k":"h","t":"رندر چیست و چه نیست؛ رفع بزرگ‌ترین سوءتفاهم"},{"k":"p","t":"«State عوض شد، پس React دوباره DOM را ساخت» — این جمله تقریباً غلط است. رندر یعنی فقط فراخوانی دوباره تابع کامپوننت و ساخت «توصیف جدید» (VDOM). React بعد این توصیف را با قبلی مقایسه (Reconciliation) می‌کند و فقط تفاوت واقعی را روی DOM اعمال می‌کند — شاید هیچ! پس رندر ارزان است مگر تابع کامپوننت کار سنگین بکند یا هزاران بار تکرار شود. این تمایز عملی‌اش اینجاست: لازم نیست از هر رندر بترسی؛ باید از رندرِ بی‌فایده‌ی کامپوننت‌های بزرگ و محاسبات گرانِ تکرارشونده بترسی — و ابزارهایش memo و useMemo‌اند، نه حذف state."},{"k":"h","t":"ناهمگامی setState؛ چرا setN(n+1) دوبار یکی اضافه می‌کند"},{"k":"p","t":"وقتی setN(n + 1) را دوبار پشت‌سرهم صدا می‌زنی، هر دو فراخوانی n را از closureِ رندر فعلی می‌خوانند — که هنوز مقدار قدیمی است؛ پس هر دو «قدیمی+۱» حساب می‌کنند و نتیجه یکی اضافه می‌شود نه دوتا. React عمداً این‌طور است: به‌روزرسانی‌ها در یک صف جمع و یک‌جا (Batch) پرداز می‌شوند تا رندر اضافه حذف شود. راه درست، شکل تابعی setter است: setN(prev => prev + 1) — اینجا React مقدار «واقعیِ قبلی» را به تابع می‌دهد، پس دوبار صدا یعنی واقعاً +۲. قاعده: هر جا مقدار جدید به مقدار قبلی وابسته است، همیشه از updater تابعی استفاده کن — حتی اگر فعلاً یک‌بار صدا می‌شود، چون روزی دوبار می‌شود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"tsx","title":"باگ کلاسیک و نسخه درست","code":"const [n, setN] = useState(0);\n\n// ❌ بعد از کلیک: n فقط ۱ زیاد می‌شود!\nfunction broken() {\n  setN(n + 1);\n  setN(n + 1);   // هر دو n=0 را دیدند\n}\n\n// ✓ بعد از کلیک: n واقعاً ۲ زیاد می‌شود\nfunction right() {\n  setN(prev => prev + 1);\n  setN(prev => prev + 1);   // زنجیره روی مقدار واقعی\n}"},{"k":"def","term":"Reconciliation (تطبیق)","t":"الگوریتم مقایسه توصیف قبلی و جدید درخت کامپوننت‌ها: اگر نوع عنصر همان باشد، فقط props عوض می‌شود؛ اگر نوع عوض شود، کل زیردرخت از نو ساخته می‌شود. کلیدها (keys) به این الگوریتم می‌گویند کدام عناصر لیست «همان قبلی‌ها»اند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["useState یک جفت [مقدار، setter] برمی‌گرداند","برای مقدار وابسته به قبلی، از setter(prev => ...) استفاده کن","رندر فقط یعنی ساخت VDOM؛ تغییر واقعی با reconciliation است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"state.tsx","code":"function Counter() {\n  const [n, setN] = useState(0);\n  return (\n    <button onClick={() => setN(p => p + 1)}>\n      {n}\n    </button>\n  );\n}"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: useState یک جفت [مقدار، setter] برمی‌گرداند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا setN(n+1) دوبار پشت‌سرهم، n را فقط یکی زیاد می‌کند؟","opts":["باگ است","چون n در هر دو فراخوان همان مقدار قدیمی است؛ باید setN(p=>p+1) بزنی","کند است","ممکن نیست"],"ans":1,"why":"setState همگام نیست؛ اگر از متغیر فعلی استفاده کنی، هر دو از مقدار یکسان حساب می‌کنند. تابع updater راه‌حل است."},{"q":"«رندر مجدد» در React دقیقاً یعنی چه؟","opts":["ساخت دوباره کل DOM","فراخوانی دوباره تابع کامپوننت و ساخت توصیف جدید؛ تغییر واقعی DOM فقط برای تفاوت‌هاست","بازسازی state","اجرای useEffect"],"ans":1,"why":"React توصیف جدید را با قبلی تطبیق می‌دهد و حداقل تغییر را اعمال می‌کند — شاید صفر تغییر. رندر ≠ تغییر DOM."},{"q":"کجا updater تابعی (prev => ...) الزامی است؟","opts":["همیشه","هر جا مقدار جدید به مقدار قبلی وابسته است — چون setterهای پشت‌سرهم روی یک snapshot قدیمی اجرا می‌شوند","هیچ‌وقت","فقط در useEffect"],"ans":1,"why":"چند setN پشت‌سرهم در یک Batch روی n قدیمی حساب می‌کنند؛ شکل تابعی مقدار واقعی لحظه‌پردازش را می‌گیرد و تکرارپذیر می‌شود."}]'::jsonb),
('react-b4', 'react', 'لیست‌ها و کلید', 63, 17, '[{"k":"p","t":"برای رندر لیست از map استفاده می‌کنی و هر عنصر باید key یکتا داشته باشد تا React بفهمد کدام آیتم عوض شده و کمترین تغییر DOM را بزند."},{"k":"h","t":"کلید؛ هویت عناصر در دنیای بی‌نام React"},{"k":"p","t":"وقتی یک لیست دوباره رندر می‌شود، React توصیف جدید را با قبلی مقایسه می‌کند — ولی عناصر آرایه «نام» ندارند؛ position دارند. بدون key، React فرض می‌کند عنصر i همان عنصر i قبلی است و فقط محتوایش عوض شده. حالا اگر آیتم اول را حذف کنی، React فکر می‌کند همه آیتم‌ها «یک محتوا جلوتر» شده‌اند — و state (مثل تیک‌خوردگی checkbox یا متن input) به عنصرِ اشتباه می‌چسبد! key یکتا و پایدار به React می‌گوید «این عنصر، همان عنصر با id فلان است» — پس حذف یعنی فقط حذف همان گره، بقیه دست نمی‌خورند. کلید، هویت است نه تزئین."},{"k":"h","t":"چرا ایندکس key خطرناک است و Math.random بدتر"},{"k":"p","t":"ایندکس به‌عنوان key فقط وقتی بی‌خطر است که لیست هیچ‌وقت تغییر ترتیب/حذف ندهد (مثل ردیفهای ثابت جدول ضرب). به‌محض حذف از وسط، ایندکس‌ها شیفت می‌خورند و همان فاجعه جابه‌جایی state رخ می‌دهد — بدتر، چون «هشدار کلید» هم نمی‌بینی، باگ پنهان می‌ماند. طرف دیگر، key تصادفی یا Date.now() یعنی هر رندر همه عناصر «جدید» فرض شوند: کل زیردرخت از نو ساخته می‌شود (state پاک، انیمیشن‌ها ریست، فوکوس پریده). بهترین منبع کلید، id دیتاست؛ اگر نداری و لیست فقط انتهایش رشد می‌کند، ایندکس قابل‌دفاع است — ولی لحظه‌ای که عملیات حذف/مرتب‌سازی اضافه شد، باید id بسازی."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"tsx","title":"باگ جابه‌جایی state با key ایندکس","code":"// هر TaskInput یک input با state داخلی است\nfunction List({ tasks }: { tasks: Task[] }) {\n  return tasks.map((t, i) => (\n    // ❌ حذف t2، متن تایپ‌شده را به t3 می‌چسباند!\n    // <TaskInput key={i} task={t} />\n\n    // ✓ هویت واقعی؛ حذف فقط همان گره را می‌برد\n    <TaskInput key={t.id} task={t} />\n  ));\n}\n\n// اگر id نداری و لیست تغییر نمی‌کند:\nconst FIXED = [''نام'', ''ایمیل'', ''شهر''];\nFIXED.map((label, i) => <Field key={i} label={label} />); // امن"},{"k":"warn","title":"دام رایج","t":"باگ‌های key معمولاً در تست دستی دیده نمی‌شوند و در production با داده واقعی ظاهر می‌شوند: inputها قاطی می‌شوند، انیمیشن‌ها می‌پرند، فوکوس گم می‌شود. قبل از هر عملیات حذف/مرتب‌سازی روی لیست، کلیدها را چک کن."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["key باید بین خواهرها یکتا و پایدار باشد","از ایندکس به‌عنوان key فقط وقتی لیست تغییر نمی‌کند استفاده کن","map را داخل JSX با {} قرار بده"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"list.tsx","code":"function List({ items }: { items: { id: number; t: string }[] }) {\n  return (\n    <ul>\n      {items.map(it => (\n        <li key={it.id}>{it.t}</li>\n      ))}\n    </ul>\n  );\n}"},{"k":"warn","title":"هشدار","t":"استفاده از ایندکس به‌عنوان key وقتی آیتم‌ها حذف/اضافه می‌شوند، باعث رندر اشتباه و از دست رفتن state عناصر می‌شود."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: key باید بین خواهرها یکتا و پایدار باشد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا key لازم است؟","opts":["برای CSS","تا React هویت عناصر را بین رندرها تشخیص دهد و کمترین تغییر را بزند","اجباری نیست","برای مرتب‌سازی"],"ans":1,"why":"بدون key، React نمی‌داند کدام عنصر کدام است و ممکن است همه را از نو بسازد یا state را جابه‌جا کند."},{"q":"بدون key، حذف آیتم اول لیست چه اتفاقی می‌اندازد؟","opts":["هیچ","React همه عناصر را «تغییرکرده» می‌بیند؛ محتواها شیفت می‌خورند و state داخلی هر عنصر به همسایه‌اش می‌چسبد","لیست پاک می‌شود","خطا می‌دهد"],"ans":1,"why":"بدون هویت، تطبیق بر اساس position است؛ حذف از اول یعنی همه positionها یکی جابه‌جا — React به‌جای حذف یک گره، n-1 گره را به‌روز می‌کند و stateها جابه‌جا می‌شوند."},{"q":"چرا key={Math.random()} بدترین انتخاب است؟","opts":["تصادفی است","هر رندر همه عناصر جدید فرض می‌شوند: زیردرخت کامل بازسازی، state پاک و فوکوس پریده","کند نیست","React اجازه نمی‌دهد"],"ans":1,"why":"کلید باید بین رندرها پایدار باشد تا هویت حفظ شود؛ تصادفی یعنی هیچ عنصری هویت ندارد — نتیجه، بازسازی کامل در هر رندر."}]'::jsonb),
('react-b5', 'react', 'useEffect و همگام‌سازی', 56, 18, '[{"k":"p","t":"useEffect برای اثرهایی است که خارج از رندر رخ می‌دهند: دریافت داده، اشتراک، تایمر. آرایه وابستگی تعیین می‌کند چه زمانی اجرا شود."},{"k":"h","t":"useEffect؛ برای کارهای بیرون از رندر"},{"k":"p","t":"کامپوننت‌ها با رندرکردن، UI را توصیف می‌کنند؛ ولی خیلی کارها «بیرون از رندر» اتفاق می‌افتند: دریافت داده از سرور، اشتراک در یک رویداد، راه‌اندازی تایمر، یا دستکاری مستقیم DOM. این‌ها را «اثر جانبی» (side effect) می‌گویند و جای آن‌ها داخل بدنه رندر نیست چون هر رندر دوباره اجرا می‌شوند. useEffect یک Hook است که می‌گوید: این کد را بعد از رندر اجرا کن — و به این ترتیب منطق اثر جانبی را از منطق توصیف UI جدا می‌کند."},{"k":"h","t":"آرایه وابستگی؛ چه‌وقت اجرا شود"},{"k":"p","t":"دومین آرگومان useEffect یک آرایه وابستگی است که تعیین می‌کند چه‌وقت دوباره اجرا شود: اگر [] بدهی، فقط یک‌بار هنگام mount اجرا می‌شود؛ اگر [x] بدهی، هر بار x تغییر کرد دوباره اجرا می‌شود؛ و اگر اصلاً ندهی، بعد از هر رندر اجرا می‌شود (که معمولاً نمی‌خواهی). مهم‌ترین قسمت، پاک‌سازی (cleanup) است: اگر از effect تابعی برگردانی، قبل از اجرای بعدی و هنگام unmount صدا زده می‌شود — جای درست برای لغو اشتراک، پاک‌کردن تایمر و جلوگیری از نشت."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["آرایه وابستگی","کی اجرا می‌شود","کاربرد"],"rows":[["[]","فقط هنگام mount","راه‌اندازی یک‌باره"],["[x]","هر بار x تغییر کرد","واکنش به تغییر یک مقدار"],["(نداده)","بعد از هر رندر","به‌ندرت لازم است"]]},{"k":"warn","title":"دام رایج","t":"فراموش‌کردن پاک‌سازی یکی از شایع‌ترین باگ‌هاست؛ اگر در effect تایمر یا اشتراکی ساختی و تابع cleanup برنگرداندی، بعد از unmount همچنان زنده می‌ماند و نشت حافظه می‌سازد یا روی کامپوننتی که دیگر نیست setState می‌کند."},{"k":"tip","title":"نکته منتور","t":"اگر دیدی در useEffect فقط داری state را از props یا state دیگر محاسبه می‌کنی، احتمالاً اصلاً به effect نیاز نداری؛ چنین مقدار مشتق‌شده‌ای را مستقیم در رندر حساب کن تا ساده‌تر و بدون باگِ همگام‌سازی باشد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["[] یعنی فقط یک‌بار هنگام mount","[x] یعنی هر بار x عوض شد","بازگرداندن تابع، پاک‌سازی است که قبل از اجرای بعدی یا unmount صدا می‌شود"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"effect.tsx","code":"useEffect(() => {\n  const id = setInterval(() => setN(n => n + 1), 1000);\n  return () => clearInterval(id);   // پاک‌سازی\n}, []);"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: [] یعنی فقط یک‌بار هنگام mount بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا پاک‌سازی در useEffect مهم است؟","opts":["کد کوتاه می‌شود","تا اشتراک‌ها و تایمرها بعد از unmount نشت نکنند و حافظه هدر نرود","اجباری نیست","برای سرعت"],"ans":1,"why":"بدون پاک‌سازی، تایمرها و listenerها بعد از حذف کامپوننت هم زنده می‌مانند و memory leak می‌سازند."},{"q":"useEffect برای چه نوع کاری استفاده می‌شود؟","opts":["توصیف UI","اثرهای جانبی که بیرون از رندر اتفاق می‌افتند؛ مثل دریافت داده، اشتراک و تایمر","ساخت state","مرتب‌سازی"],"ans":1,"why":"بدنه رندر باید خالص باشد و فقط UI توصیف کند؛ کارهایی که با دنیای بیرون سروکار دارند (شبکه، رویداد، DOM) اثر جانبی‌اند و جای آن‌ها در useEffect بعد از رندر است."},{"q":"تابع cleanup که از useEffect برمی‌گردد چه‌وقت اجرا می‌شود؟","opts":["هرگز","قبل از اجرای دوباره effect و هنگام unmount؛ برای لغو اشتراک و پاک‌کردن تایمر","فقط هنگام mount","تصادفی"],"ans":1,"why":"چون effect ممکن است چندبار اجرا شود یا کامپوننت حذف شود، cleanup تضمین می‌کند منابع (تایمر، اشتراک) قبل از اجرای بعدی یا هنگام حذف آزاد شوند و نشت پیش نیاید."}]'::jsonb)
